type DialogSize = 'AUTO' | 'S' | 'M' | 'L' | 'XL'

const dialogSizeClasses: Record<DialogSize, string> = {
  AUTO: 'sm:w-auto sm:max-w-md sm:max-h-[calc(100vh-2rem)]',
  S: 'sm:w-[35vw] sm:max-w-[35vw] sm:h-[35vh] sm:max-h-[35vh]',
  M: 'sm:w-[50vw] sm:max-w-[50vw] sm:h-[50vh] sm:max-h-[50vh]',
  L: 'sm:w-[75vw] sm:max-w-[75vw] sm:h-[75vh] sm:max-h-[75vh]',
  XL: 'sm:w-[95vw] sm:max-w-[95vw] sm:h-[95vh] sm:max-h-[95vh]',
}

function dialogSizeClass(size: DialogSize): string {
  return dialogSizeClasses[size]
}

function scrollToFormBuilderSection(sectionId: string) {
  document.getElementById(sectionId)?.scrollIntoView({ behavior: 'smooth', block: 'start' })
}

function activateSvgControl(event: React.KeyboardEvent<SVGGElement>, action: () => void) {
  if (event.key !== 'Enter' && event.key !== ' ') return
  event.preventDefault()
  event.stopPropagation()
  action()
}

type Flash = {
  message: string
  type: string
  details?: string
} | null

type OneFlowEvent = {
  id: string
  label: string
  status: 'info' | 'active' | 'complete' | 'error'
  timestamp: string
}

function OneFlowEventLog({ events }: { events: OneFlowEvent[] }) {
  return <div className="grid gap-2 border-t pt-4" aria-live="polite">
    <div className="flex items-center justify-between gap-3">
      <div><p className="text-sm font-medium">BuilderX OneFlow activity</p><p className="mt-1 text-xs text-muted-foreground">Live timestamped events for this workflow run.</p></div>
      <Activity className="size-4 text-muted-foreground" aria-hidden="true" />
    </div>
    {events.length > 0 ? <div className="grid gap-1.5" role="log" aria-label="BuilderX OneFlow activity log">{events.map((event) => <div key={event.id} className="flex items-start gap-2 bg-muted/20 px-3 py-2 text-xs"><span className={cn('mt-0.5 shrink-0', event.status === 'complete' ? 'text-emerald-500' : event.status === 'error' ? 'text-destructive' : event.status === 'active' ? 'text-amber-500' : 'text-muted-foreground')}>{event.status === 'complete' ? <CheckCircle2 className="size-3.5" /> : event.status === 'error' ? <AlertTriangle className="size-3.5" /> : event.status === 'active' ? <LoaderCircle className="size-3.5 animate-spin" /> : <Circle className="size-3.5" />}</span><span className="min-w-0 flex-1 leading-5">{event.label}</span><time className="shrink-0 font-mono text-[10px] text-muted-foreground" dateTime={event.timestamp}>{new Date(event.timestamp).toLocaleTimeString()}</time></div>)}</div> : <p className="text-xs text-muted-foreground">No workflow events yet.</p>}
  </div>
}

function makeOneFlowEvent(label: string, status: OneFlowEvent['status'] = 'info'): OneFlowEvent {
  return { id: `${Date.now()}-${Math.random().toString(36).slice(2)}`, label, status, timestamp: new Date().toISOString() }
}

function appendOneFlowEvent(events: OneFlowEvent[], label: string, status: OneFlowEvent['status'] = 'info'): OneFlowEvent[] {
  if (status === 'active') {
    const activeIndex = events.findLastIndex((event) => event.status === 'active' && event.label === label)
    if (activeIndex >= 0) {
      return events.map((event, index) => index === activeIndex ? { ...event, timestamp: new Date().toISOString() } : event)
    }
  }
  return [...events, makeOneFlowEvent(label, status)].slice(-30)
}

function settleOneFlowEvents(events: OneFlowEvent[], status: 'complete' | 'error'): OneFlowEvent[] {
  return events.map((event) => event.status === 'active' ? { ...event, status } : event)
}

