type CodexHandoff = {
  cwd: string
  task: string
  execution: {
    sandboxMode: 'danger-full-access'
    approvalPolicy: 'never'
  }
  context: Record<string, unknown>
}

function codexHandoffFromPrepared(prepared: Record<string, any> | null | undefined, fallbackTask: string): CodexHandoff {
  const raw = prepared?.handoff && typeof prepared.handoff === 'object' && !Array.isArray(prepared.handoff) ? prepared.handoff : {}
  const cwd = String(raw.cwd || phaseData?.projectRoot || '')
  if (cwd === '') throw new Error('BuilderX did not provide the project working directory for Codex Chat.')
  return {
    cwd,
    task: String(raw.task || fallbackTask),
    execution: {
      sandboxMode: 'danger-full-access',
      approvalPolicy: 'never',
    },
    context: raw.context && typeof raw.context === 'object' && !Array.isArray(raw.context) ? raw.context : {
      handoff_mode: String(prepared?.handoff_mode || 'general'),
      files: Array.isArray(prepared?.files) ? prepared.files : [],
    },
  }
}

async function sendCodexHandoff(handoff: CodexHandoff, legacyCommand = ''): Promise<Response> {
  const sourceContext = handoff.context && typeof handoff.context === 'object' && !Array.isArray(handoff.context) ? handoff.context : {}
  const mysqlTransactionKey = String((sourceContext as Record<string, unknown>).mysql_transaction_key || '')
  const mysqlMode = mysqlTransactionKey !== ''
  const command = legacyCommand || (mysqlMode ? `Process BuilderX MySQL AI transaction ${mysqlTransactionKey}.` : handoff.task)
  if (!command.trim() || command.length > 2000) throw new Error('BuilderX requires a non-empty message of 2,000 characters or fewer.')
  return fetch(`${visualCodexBridgeUrl}/handoff`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      workspace_root: handoff.cwd,
      command: command.trim(),
    }),
  })
}

type AdminThemeMode = 'light' | 'dark'
const sidebarCookieName = 'sidebar_state'
const sidebarMobileCookieName = 'sidebar_mobile_state'
const sidebarCookieMaxAge = 60 * 60 * 24 * 7

function readBooleanCookie(name: string): boolean | null {
  if (typeof document === 'undefined') return null

  const value = document.cookie
    .split('; ')
    .find((row) => row.startsWith(`${name}=`))
    ?.split('=')[1]

  if (value === 'true') return true
  if (value === 'false') return false

  return null
}

function writeBooleanCookie(name: string, value: boolean): void {
  if (typeof document === 'undefined') return

  document.cookie = `${name}=${value}; path=/; max-age=${sidebarCookieMaxAge}`
}

function themeStorageKey(): string {
  const userKey = data.user?.key || 'guest'
  const projectKey = data.projectBasePath || window.location.pathname.split('/administrator/')[0] || '/'
  const areaKey = 'administrator'

  return `builderx:theme:${encodeURIComponent(projectKey)}:${encodeURIComponent(areaKey)}:${encodeURIComponent(userKey)}`
}

function readStoredAdminTheme(): AdminThemeMode {
  if (typeof window === 'undefined') return 'light'

  return window.localStorage.getItem(themeStorageKey()) === 'dark' ? 'dark' : 'light'
}

function applyAdminTheme(theme: AdminThemeMode): void {
  if (typeof document === 'undefined') return

  document.documentElement.classList.toggle('dark', theme === 'dark')
  document.documentElement.style.colorScheme = theme
}

function projectUrl(path = ''): string {
  const basePath = data.projectBasePath || '../'
  return `${basePath.replace(/\/?$/, '/')}${path.replace(/^\/+/, '')}`
}

function settingValue(name: string, fallback = ''): string {
  return data.settings.find((setting) => setting.setting_name === name)?.setting_value || fallback
}

function loginSettingValue(name: string, fallback = ''): string {
  return settingValue(`login_${name}`, fallback)
}

