function SubmissionFeedback({ flash }: { flash: Flash }) {
  const [open, setOpen] = React.useState(false)
  const [showDetails, setShowDetails] = React.useState(false)
  const isSuccess = flash?.type === 'success'

  React.useEffect(() => {
    if (!flash?.message) {
      setOpen(false)
      setShowDetails(false)
      return
    }

    setOpen(true)
    setShowDetails(false)
    if (!isSuccess) return

    const timer = window.setTimeout(() => setOpen(false), 3500)
    return () => window.clearTimeout(timer)
  }, [flash?.message, flash?.type, flash?.details, isSuccess])

  if (!flash?.message) return null

  return (
    <>
      {isSuccess && open ? (
        <div
          role="status"
          aria-live="polite"
          className="fixed right-4 top-20 z-[80] max-w-md rounded-md border border-green-200 bg-green-50 px-4 py-3 text-sm font-medium text-green-700 shadow-lg dark:border-green-900/60 dark:bg-green-950 dark:text-green-300"
        >
          {flash.message}
        </div>
      ) : null}
      {!isSuccess ? (
        <AlertDialog open={open} onOpenChange={setOpen}>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>Submission failed</AlertDialogTitle>
              <AlertDialogDescription>{flash.message}</AlertDialogDescription>
              {flash.details ? (
                <div className="mt-3 rounded-md bg-muted/60 p-3 text-left">
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    className="h-auto px-0 font-medium text-foreground hover:bg-transparent hover:underline"
                    aria-expanded={showDetails}
                    onClick={() => setShowDetails((current) => !current)}
                  >
                    {showDetails ? 'Hide details' : 'View more'}
                  </Button>
                  {showDetails ? (
                    <pre className="mt-2 max-h-48 overflow-auto whitespace-pre-wrap break-words text-xs leading-relaxed text-muted-foreground">
                      {flash.details}
                    </pre>
                  ) : null}
                </div>
              ) : null}
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogAction type="button" onClick={() => setOpen(false)}>Close</AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      ) : null}
    </>
  )
}

function FlashMessage() {
  return <SubmissionFeedback flash={data.flash} />
}

function AdminSidebarMobilePersistence({ defaultOpen }: { defaultOpen: boolean }) {
  const { isMobile, openMobile, setOpenMobile } = useSidebar()
  const [mobileRestored, setMobileRestored] = React.useState(false)

  React.useEffect(() => {
    if (!isMobile) {
      setMobileRestored(false)
      return
    }

    setOpenMobile(
      readBooleanCookie(sidebarMobileCookieName) ??
        readBooleanCookie(sidebarCookieName) ??
        defaultOpen,
    )
    setMobileRestored(true)
  }, [defaultOpen, isMobile, setOpenMobile])

  React.useEffect(() => {
    if (!isMobile || !mobileRestored) return

    writeBooleanCookie(sidebarMobileCookieName, openMobile)
  }, [isMobile, mobileRestored, openMobile])

  return null
}

