function DebugDetailTable({ rows }: { rows: Array<[string, string]> }) {
  return (
    <div className="rounded-md border">
      <Table>
        <TableBody>
          {rows.map(([label, value]) => (
            <TableRow key={label}>
              <TableCell className="w-36 font-medium">{label}</TableCell>
              <TableCell className="font-mono text-xs text-muted-foreground">{value}</TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  )
}

function AdminDebugBar({ activeView, buildTarget, title }: { activeView: string; buildTarget: string; title: string }) {
  const debugEnabled = data.isSignedIn && data.isAdmin && settingValue('debug_enabled', '0') === '1'

  if (!debugEnabled) {
    return null
  }

  const route = `/administrator/?tab=${activeView}`
  const phaseTask = buildTarget.replace(/^Build Target\s+/i, '')
  const summary = `Debug Bar: ${route} | 0 AJAX | 0 queries | ${phaseTask} | 0 errors`
  const requestRows: Array<[string, string]> = [
    ['Route', route],
    ['React View', title],
    ['PHP Entry', 'administrator/index.php'],
    ['App Shell', 'React/shadcn Administrator Shell'],
    ['Mode', 'Preview output until the live collector is implemented'],
  ]
  const ajaxRows: Array<[string, string]> = [
    ['Count', '0 captured AJAX calls'],
    ['Expected', 'Future fetch/jQuery calls should attach or return a debug trace ID'],
    ['Storage', 'storage/logs/debug/<trace-id>.json'],
  ]
  const queryRows: Array<[string, string]> = [
    ['Count', '0 captured queries'],
    ['Expected', 'Future ADOdb helpers should record SQL, duration, row count, and redacted parameters'],
    ['Show Queries', settingValue('debug_show_queries', '0') === '1' ? 'Enabled' : 'Disabled'],
  ]
  const fileRows: Array<[string, string]> = [
    ['Frontend', 'frontend/src/App.tsx'],
    ['Backend', 'administrator/index.php, app/foundation.php'],
    ['Show Files', settingValue('debug_show_files', '1') === '1' ? 'Enabled' : 'Disabled'],
  ]
  const phaseRows: Array<[string, string]> = [
    ['Phase/Task', phaseTask],
    ['Known Mapping', activeView === 'users' ? 'P1-T10 Administrator Users' : `${phaseTask} ${title}`],
    ['Show Mapping', settingValue('debug_show_phase_task', '1') === '1' ? 'Enabled' : 'Disabled'],
  ]
  const errorRows: Array<[string, string]> = [
    ['Errors', '0 captured errors'],
    ['Warnings', '0 captured warnings'],
    ['Redaction', 'Passwords, tokens, cookies, API keys, and CSRF values must be hidden'],
  ]

  return (
    <Sheet>
      <div className="border-t bg-background px-4 py-2">
        <SheetTrigger
          render={
            <button
              type="button"
              className="mx-auto flex min-h-10 w-full max-w-[1600px] items-center justify-between gap-3 rounded-md border bg-muted/20 px-3 py-2 text-left text-xs text-muted-foreground transition-colors hover:bg-muted/40 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
            />
          }
        >
          <span className="flex min-w-0 items-center gap-2">
            <TerminalSquare aria-hidden="true" />
            <span className="truncate font-mono">{summary}</span>
          </span>
          <Badge variant="secondary">Open</Badge>
        </SheetTrigger>
      </div>
      <SheetContent side="right" className="w-full sm:max-w-2xl">
        <SheetHeader>
          <SheetTitle>Debug Output</SheetTitle>
          <SheetDescription>Admin-only preview for the current Administrator page. Live query and AJAX capture will populate these sections when the collector is implemented.</SheetDescription>
        </SheetHeader>
        <div className="px-4 pb-4">
          <Tabs defaultValue="request" className="w-full">
            <TabsList className="flex h-auto flex-wrap">
              <TabsTrigger value="request">Request</TabsTrigger>
              <TabsTrigger value="ajax">AJAX</TabsTrigger>
              <TabsTrigger value="queries">Queries</TabsTrigger>
              <TabsTrigger value="files">Files</TabsTrigger>
              <TabsTrigger value="phase">Phase/Task</TabsTrigger>
              <TabsTrigger value="errors">Errors</TabsTrigger>
            </TabsList>
            <TabsContent value="request"><DebugDetailTable rows={requestRows} /></TabsContent>
            <TabsContent value="ajax"><DebugDetailTable rows={ajaxRows} /></TabsContent>
            <TabsContent value="queries"><DebugDetailTable rows={queryRows} /></TabsContent>
            <TabsContent value="files"><DebugDetailTable rows={fileRows} /></TabsContent>
            <TabsContent value="phase"><DebugDetailTable rows={phaseRows} /></TabsContent>
            <TabsContent value="errors"><DebugDetailTable rows={errorRows} /></TabsContent>
          </Tabs>
        </div>
      </SheetContent>
    </Sheet>
  )
}

