function BranchStatusButton({
  branch,
  status,
  label,
  icon,
  setConfirmation,
}: {
  branch: Record<string, string>
  status: string
  label: string
  icon: React.ReactNode
  setConfirmation: (confirmation: ConfirmationState) => void
}) {
  const formRef = React.useRef<HTMLFormElement>(null)
  const destructive = status === 'DELETED' || status === 'ARCHIVED'

  return (
    <form ref={formRef} method="post">
      <input type="hidden" name="csrf" value={data.csrf} />
      <input type="hidden" name="action" value="set_branch_status" />
      <input type="hidden" name="branch_key" value={branch.branch_key} />
      <input type="hidden" name="branch_status" value={status} />
      <Button
        type="button"
        variant="outline"
        size="sm"
        onClick={() => setConfirmation({
          title: `${label} branch`,
          message: destructive
            ? `${label} branch ${branch.branch_code}? This changes availability for linked projects and assignments.`
            : `${label} branch ${branch.branch_code}?`,
          confirmLabel: label,
          destructive,
          onConfirm: () => formRef.current?.requestSubmit(),
        })}
      >
        {icon}
        {label}
      </Button>
    </form>
  )
}

