function phaseField(record: Record<string, any> | null | undefined, key: string, fallback = ''): string {
  const value = record?.[key]
  return value === null || value === undefined ? fallback : String(value)
}

function normalizeReviewMarkdown(value: string): string {
  return value
    .replace(/\\r\\n/g, '\n')
    .replace(/\\n/g, '\n')
    .replace(/\s+(#{1,6}\s+)/g, '\n$1')
    .replace(/\s+(-\s+)/g, '\n$1')
    .replace(/\n{3,}/g, '\n\n')
    .trim()
}

type UiUxFlowReadBlock =
  | { kind: 'heading'; level: number; text: string }
  | { kind: 'paragraph'; lines: string[] }
  | { kind: 'list'; items: string[] }

function parseUiUxFlowReadBlocks(value: string): UiUxFlowReadBlock[] {
  const blocks: UiUxFlowReadBlock[] = []
  let paragraphLines: string[] = []
  let listItems: string[] = []

  const flushParagraph = () => {
    if (paragraphLines.length > 0) {
      blocks.push({ kind: 'paragraph', lines: paragraphLines })
      paragraphLines = []
    }
  }

  const flushList = () => {
    if (listItems.length > 0) {
      blocks.push({ kind: 'list', items: listItems })
      listItems = []
    }
  }

  value.replace(/\r\n/g, '\n').trim().split('\n').forEach((rawLine) => {
    const line = rawLine.trim()
    const heading = line.match(/^(#{1,6})\s+(.+)$/)
    const listItem = line.match(/^(?:[-*]|\d+\.)\s+(.+)$/)

    if (line === '') {
      flushParagraph()
      flushList()
      return
    }

    if (heading) {
      flushParagraph()
      flushList()
      blocks.push({ kind: 'heading', level: heading[1].length, text: heading[2].trim() })
      return
    }

    if (listItem) {
      flushParagraph()
      listItems.push(listItem[1].trim())
      return
    }

    if (listItems.length > 0) {
      listItems[listItems.length - 1] = `${listItems[listItems.length - 1]} ${line}`
      return
    }

    paragraphLines.push(line)
  })

  flushParagraph()
  flushList()
  return blocks
}

function safeUiUxFlowReadHref(value: string): boolean {
  return value.startsWith('/') || value.startsWith('#') || value.startsWith('?') || /^https?:\/\//i.test(value)
}

function renderUiUxFlowReadInline(value: string, keyPrefix: string): React.ReactNode[] {
  const tokenPattern = /(\*\*.+?\*\*|`[^`]+`|\[[^\]]+\]\([^)]+\))/g

  return value.split(tokenPattern).filter(Boolean).map((part, index) => {
    if (part.startsWith('**') && part.endsWith('**')) {
      return <strong key={`${keyPrefix}-strong-${index}`} className="font-semibold text-foreground">{part.slice(2, -2)}</strong>
    }

    if (part.startsWith('`') && part.endsWith('`')) {
      return <code key={`${keyPrefix}-code-${index}`} className="rounded bg-muted px-1.5 py-0.5 font-mono text-[0.85em] text-foreground">{part.slice(1, -1)}</code>
    }

    const link = part.match(/^\[([^\]]+)\]\(([^)]+)\)$/)
    if (link) {
      return safeUiUxFlowReadHref(link[2]) ? (
        <a key={`${keyPrefix}-link-${index}`} href={link[2]} target="_blank" rel="noreferrer" className="font-medium text-primary underline underline-offset-2 hover:text-primary/80">
          {link[1]}
        </a>
      ) : <span key={`${keyPrefix}-link-text-${index}`}>{link[1]}</span>
    }

    return <React.Fragment key={`${keyPrefix}-text-${index}`}>{part}</React.Fragment>
  })
}

function uiUxFlowReadListIcon(item: string): React.ReactNode {
  if (/risk|missing|pending|unreviewed|not started|none linked/i.test(item)) {
    return <AlertTriangle className="mt-0.5 size-4 text-amber-400" aria-hidden="true" />
  }
  if (/implemented|validation|passed|completed|done/i.test(item)) {
    return <CheckCircle2 className="mt-0.5 size-4 text-emerald-400" aria-hidden="true" />
  }
  return <Circle className="mt-0.5 size-4 text-primary" aria-hidden="true" />
}

function UiUxFlowReadContent({ value }: { value: string }) {
  const trimmedValue = value.trim()
  let isJson = false
  try {
    JSON.parse(trimmedValue)
    isJson = trimmedValue.startsWith('{') || trimmedValue.startsWith('[')
  } catch {
    // Render normal AI text below when the saved response is not JSON.
  }

  if (isJson) {
    return <pre className="overflow-x-auto rounded-lg border bg-muted/20 p-4 font-mono text-xs leading-6 text-foreground/90">{JSON.stringify(JSON.parse(trimmedValue), null, 2)}</pre>
  }

  const blocks = parseUiUxFlowReadBlocks(trimmedValue)

  return (
    <div className="space-y-4">
      <div className="flex items-start gap-3 border-y border-primary/20 bg-primary/5 py-3">
        <div className="mt-0.5 text-primary"><BookOpen className="size-4" aria-hidden="true" /></div>
        <div className="min-w-0">
          <p className="text-sm font-semibold">Read-only flow summary</p>
          <p className="mt-1 text-xs leading-5 text-muted-foreground">Formatted from the saved AI Chat response. Project files and database records are unchanged.</p>
        </div>
      </div>

      {blocks.map((block, blockIndex) => {
        if (block.kind === 'heading') {
          const Heading = block.level <= 2 ? 'h3' : 'h4'
          return <Heading key={`flow-read-heading-${blockIndex}`} className={cn('font-semibold tracking-tight text-foreground', block.level <= 2 ? 'text-base' : 'text-sm')}>{renderUiUxFlowReadInline(block.text, `heading-${blockIndex}`)}</Heading>
        }

        if (block.kind === 'list') {
          return (
            <div key={`flow-read-list-${blockIndex}`} className="divide-y divide-border">
              {block.items.map((item, itemIndex) => (
                <div key={`flow-read-item-${blockIndex}-${itemIndex}`} className="flex items-start gap-3 py-3 first:pt-0 last:pb-0">
                  {uiUxFlowReadListIcon(item)}
                  <p className="min-w-0 text-sm leading-6 text-foreground/90">{renderUiUxFlowReadInline(item, `item-${blockIndex}-${itemIndex}`)}</p>
                </div>
              ))}
            </div>
          )
        }

        return (
          <p key={`flow-read-paragraph-${blockIndex}`} className="text-sm leading-7 text-foreground/90">
            {renderUiUxFlowReadInline(block.lines.join(' '), `paragraph-${blockIndex}`)}
          </p>
        )
      })}
    </div>
  )
}

function promptPreviewSections(value: string): Array<{ title: string; body: string }> {
  const normalized = normalizeReviewMarkdown(value)
  if (normalized === '') return []

  const sections: Array<{ title: string; body: string }> = []
  let title = 'Prompt'
  let body: string[] = []
  const flush = () => {
    const content = body.join('\n').trim()
    if (content !== '') sections.push({ title, body: content })
    body = []
  }

  normalized.split('\n').forEach((line) => {
    const heading = line.trim().match(/^#{1,6}\s+(.+)$/)
    if (heading) {
      flush()
      title = heading[1].trim()
      return
    }
    body.push(line)
  })
  flush()

  return sections.length > 0 ? sections : [{ title: 'Prompt', body: normalized }]
}

function reviewInternalMarkerIndex(value: string): number {
  const markers = [
    '### BuilderX Scoped AI Memory',
    '## BuilderX Scoped AI Memory',
    'BuilderX Scoped AI Memory',
    'Current note context:',
    'Previous review JSON:',
    'Chat history:',
    'Estimated prompt tokens:',
    'Estimated context tokens:',
    'Estimated full-memory context tokens:',
  ]
  const indexes = markers.map((marker) => value.indexOf(marker)).filter((index) => index >= 0)

  return indexes.length > 0 ? Math.min(...indexes) : -1
}

function stripReviewInternalContext(value: string): { visible: string; hasInternalContext: boolean } {
  const normalized = normalizeReviewMarkdown(value)
  const markerIndex = reviewInternalMarkerIndex(normalized)
  if (markerIndex < 0) return { visible: normalized, hasInternalContext: false }

  return {
    visible: normalized.slice(0, markerIndex).trim(),
    hasInternalContext: true,
  }
}

function simplifyReviewLanguage(value: string): string {
  return value
    .replace(
      /The\s+([A-Za-z0-9_ -]+)\s+table is planned,\s+but no CRUD field is currently configured\.\s+Please resolve that inconsistency and confirm the remaining ([^.]+) before implementation\./gi,
      (_match, tableName: string, remaining: string) => (
        `Table ${tableName.trim()} is selected for this form. Next: add or confirm the fields the form should use, then review ${remaining.trim()} before building.`
      )
    )
    .replace(/\bCRUD field\b/g, 'form/database field')
    .replace(/\bresolve that inconsistency\b/gi, 'finish that setup')
}

function reviewTextHasStaleUnconfiguredFieldWarning(value: string): boolean {
  return /table is planned,\s+but no (?:CRUD|form\/database) field is currently configured/i.test(value)
    || /no (?:CRUD|form\/database) field is currently configured/i.test(value)
    || /crud_field_name\s+is\s+NONE/i.test(value)
}

function formPayloadConfiguredFieldNames(note: Record<string, any> | null | undefined): Array<string> {
  const payload = note?.formAiPayload && typeof note.formAiPayload === 'object' ? note.formAiPayload : {}
  const names = new Set<string>()
  const addField = (field: Record<string, any> | null | undefined) => {
    const fieldName = phaseField(field, 'field_name')
    if (fieldName !== '') {
      names.add(fieldName)
    }
  }
  const collectFromPayload = (source: Record<string, any>) => {
    ;(Array.isArray(source.fields) ? source.fields : []).forEach(addField)
    ;(Array.isArray(source.builder_layout?.rows) ? source.builder_layout.rows : []).forEach((row: Record<string, any>) => {
      ;(Array.isArray(row.fields) ? row.fields : []).forEach(addField)
    })
    addField(source.form_variables?.key_field)
    ;(Array.isArray(source.form_variables?.query_fields) ? source.form_variables.query_fields : []).forEach(addField)
  }

  collectFromPayload(payload)
  ;(Array.isArray(payload.form_instances) ? payload.form_instances : []).forEach((instance: Record<string, any>) => {
    if (instance && typeof instance === 'object') {
      collectFromPayload(instance)
    }
  })

  return Array.from(names)
}

function noteHasConfiguredFormFields(note: Record<string, any> | null | undefined): boolean {
  return formPayloadConfiguredFieldNames(note).length > 0
}

function staleConfiguredFormReviewMessage(note: Record<string, any> | null | undefined, originalText: string): string {
  if (!reviewTextHasStaleUnconfiguredFieldWarning(originalText) || !noteHasConfiguredFormFields(note)) return ''

  const tableName = phaseField(note, 'crudTargetTable')
    || phaseField(note?.formAiPayload, 'database_table')
    || 'the selected table'
  const fields = formPayloadConfiguredFieldNames(note)
  const fieldPreview = fields.slice(0, 6).join(', ')
  const extraCount = fields.length > 6 ? `, +${fields.length - 6} more` : ''

  return `This saved AI review is older than the current Form Builder setup. ${tableName} now has configured form fields${fieldPreview !== '' ? `: ${fieldPreview}${extraCount}` : ''}. Re-run Review Notes to refresh the remaining checks.`
}

function reviewUserFacingText(value: string): { visible: string; hasInternalContext: boolean } {
  const parsed = stripReviewInternalContext(value)
  const visible = simplifyReviewLanguage(parsed.visible)

  return {
    visible: visible || (parsed.hasInternalContext ? 'AI review completed.' : ''),
    hasInternalContext: parsed.hasInternalContext,
  }
}

function noteRawText(note: Record<string, any> | null | undefined): string {
  return phaseField(note, 'refinedText')
    || phaseField(note, 'note_text_refined')
    || phaseField(note, 'originalText')
    || phaseField(note, 'note_text_original')
    || phaseField(note, 'description')
    || phaseField(note, 'noteTitle')
    || phaseField(note, 'note_text')
}

function noteUserFacingText(note: Record<string, any> | null | undefined, fallback = 'No user prompt saved.'): string {
  const parsed = stripReviewInternalContext(noteRawText(note))
  return simplifyReviewLanguage(parsed.visible) || fallback
}

function userFacingTextValue(value: string, fallback = ''): string {
  const parsed = stripReviewInternalContext(value)
  return simplifyReviewLanguage(parsed.visible) || fallback
}

function ReviewFormattedText({ text, className = '' }: { text: string; className?: string }) {
  const normalized = normalizeReviewMarkdown(text)
  if (normalized === '') return <p className={className}>No review details returned.</p>

  return (
    <div className={cn('grid gap-2 break-words text-sm leading-6', className)}>
      {normalized.split('\n').map((line, index) => {
        const trimmed = line.trim()
        if (trimmed === '') return <div key={`review-space-${index}`} className="h-1" aria-hidden="true" />

        const heading = trimmed.match(/^(#{1,6})\s+(.+)$/)
        if (heading) {
          return <h4 key={`review-heading-${index}`} className="pt-1 text-sm font-semibold text-foreground">{heading[2]}</h4>
        }

        if (/^-\s+/.test(trimmed)) {
          return <div key={`review-bullet-${index}`} className="flex items-start gap-2 text-muted-foreground"><span className="mt-2 size-1.5 shrink-0 rounded-full bg-current" aria-hidden="true" /><span>{trimmed.replace(/^-\s+/, '')}</span></div>
        }

        return <p key={`review-line-${index}`} className="text-muted-foreground">{trimmed}</p>
      })}
    </div>
  )
}

type UiUxDataSymbolType = 'view_sql' | 'view_sql_data' | 'search_sql'

function noteDataSymbols(note: Record<string, any> | null | undefined): Array<Record<string, any>> {
  const payload = note?.dataSymbols
  if (Array.isArray(payload)) return payload
  if (payload && typeof payload === 'object' && Array.isArray(payload.symbols)) return payload.symbols

  return []
}

function dataSymbolTypeLabel(type: string): string {
  if (type === 'view_sql_data') return 'ViewSQLData'
  if (type === 'search_sql') return 'SearchSQL'

  return 'ViewSQL'
}

function databaseAiFieldName(field: Record<string, any>): string {
  const fieldName = phaseField(field, 'field_name', 'field_name')
  const normalized = fieldName.toLowerCase()
  if (normalized === 'x_id') return 'x_Id'
  if (normalized === 'zstatus') return 'zStatus'
  if (normalized === 'created_at' || normalized === 'zcreated_at') return 'zCreated_At'
  if (normalized === 'updated_at' || normalized === 'zupdated_at') return 'zUpdated_At'
  if (normalized === 'server_timestamp' || normalized === 'zservertimestamp') return 'zServerTimeStamp'

  return stripConfiguredTablePrefix(fieldName)
}

function databaseAiDataType(field: Record<string, any>): string {
  const fieldName = databaseAiFieldName(field)
  if (fieldName === 'x_Id') return 'INT(10)'
  if (fieldName === 'zServerTimeStamp') return 'FIREBASE SERVER TIME STAMP'

  return phaseField(field, 'data_type', 'VARCHAR(255)')
}

function configuredTablePrefix(): string {
  const prefix = phaseField(phaseData?.tableNamingConventions, 'tablePrefix')
    .toLowerCase()
    .replace(/[^a-z0-9_]+/g, '_')
    .replace(/_+/g, '_')

  return prefix === '' ? '' : prefix.replace(/^([0-9])/, 'data_$1').slice(0, 64)
}

function ensureConfiguredTablePrefix(value: string): string {
  const normalized = value.trim().toLowerCase().replace(/[^a-z0-9_]+/g, '_').replace(/_+/g, '_').replace(/^_+|_+$/g, '')
  const prefix = configuredTablePrefix()
  if (normalized === '' || prefix === '' || normalized.startsWith(prefix)) return normalized

  return `${prefix}${normalized}`.slice(0, 128)
}

function stripConfiguredTablePrefix(value: string): string {
  const prefix = configuredTablePrefix()
  const normalizedValue = value.trim()

  return prefix !== '' && normalizedValue.toLowerCase().startsWith(prefix) ? normalizedValue.slice(prefix.length) : normalizedValue
}

function phaseNumber(record: Record<string, any> | null | undefined, key: string): number {
  const value = Number(record?.[key] ?? 0)
  return Number.isFinite(value) ? value : 0
}

function stripChartCodePrefix(label: string, code: string): string {
  const trimmedLabel = label.trim()
  const trimmedCode = code.trim()
  if (trimmedCode === '') return trimmedLabel

  if (trimmedLabel.toLowerCase().startsWith(trimmedCode.toLowerCase())) {
    return trimmedLabel.slice(trimmedCode.length).replace(/^\s*[:-]\s*/, '').trim()
  }

  return trimmedLabel
}

function chartCodeLabel(code: string, title: string, fallback: string): string {
  const cleanCode = code.trim()
  const cleanTitle = stripChartCodePrefix(title, cleanCode) || fallback.trim()

  return cleanCode !== '' ? `${cleanCode} : ${cleanTitle || 'Untitled'}` : cleanTitle || fallback
}

function phaseHref(path = ''): string {
  const basePath = phaseData?.projectBasePath || window.location.pathname.split('/phases/')[0] || '/'
  return `${basePath.replace(/\/?$/, '/')}${path.replace(/^\/+/, '')}`
}

function phaseLocalHref(params: Record<string, string>): string {
  const search = new URLSearchParams(params)
  return `./?${search.toString()}`
}

