type DisplayRoadmapTask = {
  taskId: string
  taskTitle: string
  taskDescription: string
  taskType: string
  track: 'web' | 'android' | 'shared'
  route: string
  apiEndpoint: string
  tableName: string
  resourceRefs: string[]
  indicators: string[]
  suggestions: Record<string, any>
  subTasks: Array<{ subtaskId: string; subtaskTitle: string; subtaskDescription: string; acceptanceCriteria: string[]; dependsOn: string[]; todos: Array<{ todoId: string; todoTitle: string; todoDescription: string; todoType: string; status: string }> }>
  legacyTrack?: 'web' | 'android'
  legacyIndex?: number
}

function displayRoadmapTasks(phase: Record<string, any>, phaseId: string): DisplayRoadmapTask[] {
  if (Array.isArray(phase.tasks)) {
    return phase.tasks.map((task: Record<string, any>, index: number) => ({
      taskId: String(task.taskId || `${phaseId}-TASK-${String(index + 1).padStart(2, '0')}`),
      taskTitle: String(task.taskTitle || `Task ${index + 1}`),
      taskDescription: String(task.taskDescription || ''),
      taskType: String(task.taskType || 'vertical_slice'),
      track: ['web', 'android', 'shared'].includes(task.track) ? task.track : 'shared',
      route: String(task.route || ''),
      apiEndpoint: String(task.apiEndpoint || ''),
      tableName: String(task.tableName || task.suggestions?.tableName || ''),
      resourceRefs: Array.isArray(task.resourceRefs) ? task.resourceRefs.map((ref: unknown) => String(ref)) : [],
      indicators: Array.isArray(task.indicators) ? task.indicators.map((indicator: unknown) => String(indicator)) : [],
      suggestions: task.suggestions && typeof task.suggestions === 'object' ? task.suggestions : { tableName: '', tableFields: [], relatedFiles: [], forms: [] },
      subTasks: Array.isArray(task.subTasks) ? task.subTasks.map((subtask: Record<string, any>, subtaskIndex: number) => ({ subtaskId: String(subtask.subtaskId || `${phaseId}-TASK-${index + 1}-SUB-${subtaskIndex + 1}`), subtaskTitle: String(subtask.subtaskTitle || `Sub-task ${subtaskIndex + 1}`), subtaskDescription: String(subtask.subtaskDescription || ''), acceptanceCriteria: Array.isArray(subtask.acceptanceCriteria) ? subtask.acceptanceCriteria.map((criterion: unknown) => String(criterion)) : [], dependsOn: Array.isArray(subtask.dependsOn) ? subtask.dependsOn.map((dependency: unknown) => String(dependency)) : [], todos: Array.isArray(subtask.todos) ? subtask.todos.map((todo: Record<string, any>, todoIndex: number) => ({ todoId: String(todo.todoId || `${phaseId}-TASK-${index + 1}-SUB-${subtaskIndex + 1}-TODO-${todoIndex + 1}`), todoTitle: String(todo.todoTitle || `Todo ${todoIndex + 1}`), todoDescription: String(todo.todoDescription || ''), todoType: String(todo.todoType || 'implementation'), status: String(todo.status || 'Pending') })) : [] })) : [],
    }))
  }
  return (['web', 'android'] as const).flatMap((track) => {
    const field = track === 'web' ? 'webTrackTasks' : 'androidTrackTasks'
    return (Array.isArray(phase[field]) ? phase[field] : []).map((task: unknown, index: number) => ({
      taskId: `${phaseId}-${track.toUpperCase()}-TASK-${String(index + 1).padStart(2, '0')}`,
      taskTitle: `${track === 'web' ? 'Web' : 'Android'} task ${index + 1}`,
      taskDescription: String(task),
      taskType: 'vertical_slice',
      track,
      route: '',
      apiEndpoint: '',
      tableName: '',
      resourceRefs: [],
      indicators: [],
      suggestions: { tableName: '', tableFields: [], relatedFiles: [], forms: [] },
      subTasks: [],
      legacyTrack: track,
      legacyIndex: index,
    }))
  })
}

function roadmapTaskInvolvement(task: DisplayRoadmapTask) {
  const indicatorSet = new Set(task.indicators)
  const taskType = task.taskType.trim().toLowerCase()
  const suggestedForms = Array.isArray(task.suggestions?.forms) ? task.suggestions.forms : []
  const suggestedFields = Array.isArray(task.suggestions?.tableFields) ? task.suggestions.tableFields : []
  const hasForm = indicatorSet.has('forms') || taskType === 'form' || suggestedForms.length > 0
  const hasDatabase = indicatorSet.has('database') || indicatorSet.has('crud') || taskType === 'database' || Boolean(task.tableName.trim()) || Boolean(String(task.suggestions?.tableName || '').trim()) || suggestedFields.length > 0
  const indicators = [...new Set([
    ...task.indicators,
    ...(hasForm ? ['forms'] : []),
    ...(hasDatabase ? ['database'] : []),
  ])]
  const summary = [hasForm ? 'Form involved' : '', hasDatabase ? 'Database involved' : ''].filter(Boolean).join(' · ')
  return { hasForm, hasDatabase, indicators, summary }
}

const roadmapTodoInvolvementIcons: Record<string, React.ElementType> = {
  view: Eye,
  insert: Plus,
  edit: Pencil,
  delete: Trash2,
  database: Database,
  api: Workflow,
  forms: PenLine,
  authentication: KeyRound,
  authorization: ShieldCheck,
  validation: CheckCircle2,
  testing: TestTube2,
  files: FileText,
  implementation: Wrench,
  analysis: FileBarChart,
  verification: CheckCircle2,
}

const roadmapTodoInvolvementLabels: Record<string, string> = {
  view: 'View or screen involved',
  insert: 'Insert or create involved',
  edit: 'Edit or update involved',
  delete: 'Delete involved',
  database: 'Database involved',
  api: 'API involved',
  forms: 'Form involved',
  authentication: 'Authentication involved',
  authorization: 'Authorization involved',
  validation: 'Validation involved',
  testing: 'Testing involved',
  files: 'Files involved',
  implementation: 'Implementation todo',
  analysis: 'Analysis todo',
  verification: 'Verification todo',
}

function roadmapTodoInvolvement(todo: DisplayRoadmapTask['subTasks'][number]['todos'][number], task: DisplayRoadmapTask) {
  const source = `${todo.todoType} ${todo.todoTitle} ${todo.todoDescription}`.toLowerCase()
  const taskIndicators = new Set(task.indicators)
  const taskType = task.taskType.trim().toLowerCase()
  const involvement = new Set<string>()
  const has = (patterns: RegExp[]) => patterns.some((pattern) => pattern.test(source))
  const add = (key: string) => involvement.add(key)

  if (has([/\bview\b/, /\bscreen\b/, /\bpage\b/, /\bportal\b/, /\brender\b/, /\bdisplay\b/, /\blist\b/, /\bread-only\b/]) || taskType === 'page') add('view')
  if (has([/\binsert\b/, /\bcreate\b/, /\badd\b/, /\bsave\b/, /\bpersist\b/])) add('insert')
  if (has([/\bedit\b/, /\bupdate\b/, /\bmodify\b/, /\bchange\b/])) add('edit')
  if (has([/\bdelete\b/, /\bremove\b/, /\barchive\b/])) add('delete')
  if (taskIndicators.has('api') || taskType === 'api' || Boolean(task.apiEndpoint.trim()) || has([/\bapi\b/, /\bendpoint\b/, /\bservice\b/, /\brequest\b/])) add('api')
  if (roadmapTaskInvolvement(task).hasDatabase || has([/\bdatabase\b/, /\btable\b/, /\bsql\b/, /\bquery\b/, /\brecord\b/, /\bstorage\b/])) add('database')
  if (roadmapTaskInvolvement(task).hasForm || has([/\bform\b/, /\binput\b/, /\bfield\b/])) add('forms')
  if (taskIndicators.has('authentication') || has([/\bauthentication\b/, /\bsign-in\b/, /\bsession\b/, /\btoken\b/])) add('authentication')
  if (taskIndicators.has('authorization') || has([/\bauthorization\b/, /\bpermission\b/, /\brole\b/, /\baccess\b/])) add('authorization')
  if (taskIndicators.has('validation') || has([/\bvalidation\b/, /\binvariant\b/, /\binput rules?\b/])) add('validation')
  if (taskIndicators.has('testing') || has([/\btest\b/, /\bverify\b/, /\bverification\b/, /\bacceptance\b/])) add('testing')
  if (taskIndicators.has('files') || has([/\bfile\b/, /\bimage\b/, /\bscreenshot\b/, /\bupload\b/])) add('files')
  if (involvement.size === 0) add(['analysis', 'implementation', 'verification'].includes(todo.todoType.toLowerCase()) ? todo.todoType.toLowerCase() : 'implementation')

  return Array.from(involvement).map((key) => ({ key, label: roadmapTodoInvolvementLabels[key] || key, Icon: roadmapTodoInvolvementIcons[key] || Wrench }))
}

function ExecutionRoadmapTab({
  phaseKey,
  roadmap,
  progress,
  busyTaskKey,
  children,
  beforeQuickJump,
  moduleCatalog,
  onTaskChange,
}: {
  phaseKey: string
  roadmap: Record<string, any>
  progress: Record<string, boolean>
  busyTaskKey: string
  children?: React.ReactNode
  beforeQuickJump?: React.ReactNode
  moduleCatalog?: Array<Record<string, any>>
  onTaskChange: (phaseId: string, taskId: string, subtaskId: string, todoId: string, completed: boolean, legacyTrack?: 'web' | 'android', legacyIndex?: number) => void
}) {
  const overview = roadmap?.phaseExecutionOverview && typeof roadmap.phaseExecutionOverview === 'object' ? roadmap.phaseExecutionOverview : {}
  const phases = Array.isArray(roadmap?.phases) ? roadmap.phases : []
  const hasRoadmap = phases.length > 0
  const displayPhases = phases.map((phase: Record<string, any>, phaseIndex: number) => {
    const phaseId = String(phase.phaseId || `PHASE-${String(phaseIndex + 1).padStart(2, '0')}`)
    return { phase, phaseId, phaseIndex, tasks: displayRoadmapTasks(phase, phaseId) }
  })
  const progressItems = displayPhases.flatMap(({ phaseId, tasks }) => tasks.flatMap((task) => [
    { key: task.legacyTrack ? `${phaseId}:${task.legacyTrack}:${task.legacyIndex}` : `${phaseId}:${task.taskId}`, task },
    ...task.subTasks.flatMap((subtask) => [{ key: `${phaseId}:${task.taskId}:${subtask.subtaskId}`, task }, ...subtask.todos.map((todo) => ({ key: `${phaseId}:${task.taskId}:${subtask.subtaskId}:${todo.todoId}`, task }))]),
  ]))
  const completedItems = progressItems.filter(({ key }) => progress[key] === true).length
  const completionPercent = progressItems.length > 0 ? Math.round((completedItems / progressItems.length) * 100) : 0
  const taskCount = displayPhases.reduce((total, { tasks }) => total + tasks.length, 0)
  const subtaskCount = displayPhases.reduce((total, { tasks }) => total + tasks.reduce((taskTotal, task) => taskTotal + task.subTasks.length, 0), 0)
  const roadmapPhaseAnchor = (phaseId: string) => `execution-${phaseId.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')}`
  const roadmapModuleAnchor = (moduleId: string, moduleIndex: number) => `execution-module-${(moduleId || `module-${moduleIndex + 1}`).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')}`
  const moduleGroups = (() => {
    const catalog = Array.isArray(moduleCatalog) ? moduleCatalog : []
    const assignedPhaseIds = new Set<string>()
    const groups = catalog.map((module, moduleIndex) => {
      const moduleId = String(module.moduleId || `MODULE-${String(moduleIndex + 1).padStart(3, '0')}`)
      const modulePhases = displayPhases.filter(({ phase, phaseId }) => String(phase.moduleId || '') === moduleId && !assignedPhaseIds.has(phaseId))
      modulePhases.forEach(({ phaseId }) => assignedPhaseIds.add(phaseId))
      return { module, moduleId, modulePhases, moduleIndex }
    }).filter(({ modulePhases }) => modulePhases.length > 0)
    const unassignedPhases = displayPhases.filter(({ phaseId }) => !assignedPhaseIds.has(phaseId))
    if (unassignedPhases.length > 0) groups.push({ module: { moduleTitle: catalog.length > 0 ? 'Other roadmap phases' : 'Execution roadmap' }, moduleId: 'unassigned', modulePhases: unassignedPhases, moduleIndex: groups.length })
    return groups.length > 0 ? groups : [{ module: { moduleTitle: 'Execution roadmap' }, moduleId: 'roadmap', modulePhases: displayPhases, moduleIndex: 0 }]
  })()

  if (!hasRoadmap) {
    return (
      <div className="grid gap-4">
        {children}{beforeQuickJump}
        <div id="execution-roadmap-overview" className="scroll-mt-24 grid min-h-60 place-items-center rounded-md bg-muted/20 p-6 text-center">
          <div className="max-w-xl">
            <TerminalSquare className="mx-auto size-8 text-muted-foreground" />
            <h2 className="mt-3 text-base font-semibold">No execution roadmap yet</h2>
            <p className="mt-2 text-sm leading-6 text-muted-foreground">Complete System Architecture &amp; Build Manifest, then generate the Phase → Task → Sub-task roadmap. Suggestions are advisory and remain inside the Phase Builder artifact.</p>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="grid gap-4">
      <section id="execution-roadmap-overview" className="scroll-mt-24 rounded-lg bg-gradient-to-br from-emerald-500/10 via-background to-sky-500/10 p-5">
        <div className="flex flex-wrap items-start justify-between gap-3"><div className="min-w-0"><p className="text-xs font-semibold uppercase tracking-wider text-emerald-700 dark:text-emerald-300">Implementation decomposition</p><h2 className="mt-1 text-xl font-semibold">{String(overview.projectTitle || 'Execution & UI/UX Roadmap · Saved phase analysis')}</h2><p className="mt-2 max-w-4xl text-sm leading-6 text-muted-foreground">{String(overview.strategy || 'Stage 1 phase analysis is saved below. Run Stage 2 to add implementation tasks.')}</p></div><div className="flex flex-wrap items-center gap-2">{roadmap.schemaVersion === 'builderx.execution-roadmap.v1' ? <ExecutionRoadmapPhaseManagerExport phaseKey={phaseKey} roadmap={roadmap} /> : null}<Badge variant="outline">{phases.length} Phases</Badge><Badge variant="outline">{taskCount} Tasks</Badge><Badge variant="outline">{subtaskCount} Sub-tasks</Badge><Badge>{completedItems} / {progressItems.length} Done</Badge><Tooltip><TooltipTrigger render={<Button type="button" variant="outline" size="icon-sm" aria-label="Refresh Execution Roadmap content" title="Refresh Execution Roadmap content" onClick={reloadPagePreservingScroll} />}><RotateCcw /></TooltipTrigger><TooltipContent>Refresh saved roadmap content</TooltipContent></Tooltip></div></div>
        <div className="mt-4"><div className="flex items-center justify-between gap-2 text-xs"><span className="text-muted-foreground">Overall implementation progress</span><strong>{completionPercent}%</strong></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-emerald-500 transition-all" style={{ width: `${completionPercent}%` }} /></div></div>
      </section>

      {children}{beforeQuickJump}
      <nav aria-label="Execution roadmap module quick jumps" className="sticky top-[6.6rem] z-20 flex self-start flex-wrap items-center gap-2 rounded-lg bg-background/95 p-3 shadow-[0_0_18px_rgba(16,185,129,0.14),0_8px_24px_rgba(0,0,0,0.24)] ring-1 ring-emerald-400/10 backdrop-blur supports-[backdrop-filter]:bg-background/85"><span className="mr-1 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">Module list</span><a href="#execution-roadmap-overview" className={buttonClassName({ variant: 'outline', size: 'sm' })}>Overview</a>{moduleGroups.map(({ module, moduleId, modulePhases, moduleIndex }) => <a key={`roadmap-module-jump-${moduleId}`} href={`#${roadmapModuleAnchor(moduleId, moduleIndex)}`} title={`${String(module.moduleTitle || module.moduleKey || moduleId)} · ${modulePhases.length} phases`} className={buttonClassName({ variant: 'outline', size: 'sm' })}>{String(module.moduleTitle || module.moduleKey || moduleId)}</a>)}</nav>

      <div className="grid gap-4">
        {moduleGroups.map(({ module, moduleId, modulePhases, moduleIndex }) => (
          <section id={roadmapModuleAnchor(moduleId, moduleIndex)} key={moduleId} className="scroll-mt-[12rem] grid gap-3 rounded-lg bg-muted/10 p-3">
            <div className="flex flex-wrap items-start justify-between gap-3 px-1"><div><p className="text-[11px] font-semibold uppercase tracking-wider text-emerald-700 dark:text-emerald-300">Module {moduleIndex + 1}</p><h3 className="mt-1 text-base font-semibold">{String(module.moduleTitle || module.moduleKey || moduleId)}</h3><p className="mt-1 text-xs text-muted-foreground">{modulePhases.length} phase{modulePhases.length === 1 ? '' : 's'} generated for this module.</p></div><Badge variant="outline">{moduleId}</Badge></div>
            <div className="grid gap-4">
        {modulePhases.map(({ phase, phaseId, tasks, phaseIndex }) => {
          const phaseProgressItems = tasks.flatMap((task) => [task.legacyTrack ? `${phaseId}:${task.legacyTrack}:${task.legacyIndex}` : `${phaseId}:${task.taskId}`, ...task.subTasks.flatMap((subtask) => [`${phaseId}:${task.taskId}:${subtask.subtaskId}`, ...subtask.todos.map((todo) => `${phaseId}:${task.taskId}:${subtask.subtaskId}:${todo.todoId}`)])])
          const phaseDone = phaseProgressItems.filter((taskKey) => progress[taskKey] === true).length
          const status = phaseDone === phaseProgressItems.length && phaseProgressItems.length > 0 ? 'Completed' : phaseDone > 0 ? 'In Progress' : String(phase.status || 'Pending')
          return (
            <section id={roadmapPhaseAnchor(phaseId)} key={phaseId} className="scroll-mt-24 overflow-hidden rounded-lg bg-muted/5">
              <div className="flex flex-wrap items-start justify-between gap-3 border-b bg-muted/20 p-4"><div className="flex min-w-0 gap-3"><span className="grid size-9 shrink-0 place-items-center rounded-full border font-mono text-xs">{phaseIndex + 1}</span><div className="min-w-0"><p className="font-mono text-[11px] text-sky-700 dark:text-sky-300">{phaseId}</p><h3 className="mt-1 font-semibold">{String(phase.phaseTitle || phase.phaseName || `Phase ${phaseIndex + 1}`)}</h3><p className="mt-1 text-sm leading-6 text-muted-foreground">{String(phase.phaseDescription || phase.description || '')}</p></div></div><div className="flex flex-wrap items-center justify-end gap-2"><Badge variant={status === 'Completed' ? 'default' : status === 'In Progress' ? 'secondary' : 'outline'}>{status} · {phaseDone}/{phaseProgressItems.length}</Badge><a href="#execution-roadmap-overview" className={buttonClassName({ variant: 'ghost', size: 'sm' })}>Back to top</a></div></div>
              {phase.phaseType || Array.isArray(phase.systemFlow) || phase.proposedResources ? <div className="grid gap-3 border-b bg-background/40 p-4"><div className="flex flex-wrap items-center gap-2"><Badge variant="secondary">{String(phase.phaseType || 'implementation')}</Badge>{phase.entryPoint ? <span className="text-xs text-muted-foreground">Entry: {String(phase.entryPoint)}</span> : null}{phase.exitPoint ? <span className="text-xs text-muted-foreground">Exit: {String(phase.exitPoint)}</span> : null}</div>{Array.isArray(phase.systemFlow) && phase.systemFlow.length > 0 ? <Collapsible><CollapsibleTrigger className="flex items-center gap-2 text-xs font-medium text-muted-foreground hover:text-foreground"><Workflow className="size-3.5" />System flow<ChevronDown className="size-3.5" /></CollapsibleTrigger><CollapsibleContent className="mt-3 grid gap-2">{phase.systemFlow.map((step: Record<string, any>, flowIndex: number) => <div key={String(step.flowStepId || flowIndex)} className="grid gap-1 rounded-md bg-muted/30 p-3 text-xs"><div className="flex flex-wrap items-center gap-2"><span className="font-mono text-muted-foreground">{String(step.flowStepId || `FLOW-${flowIndex + 1}`)}</span><Badge variant="outline">{String(step.nodeType || 'step')}</Badge><span className="font-medium">{String(step.from || 'Start')} → {String(step.to || 'Next')}</span></div><p className="text-muted-foreground">{String(step.action || '')}</p>{step.route || step.apiRef ? <p className="font-mono text-muted-foreground">{[step.route, step.apiRef].filter(Boolean).join(' · ')}</p> : null}</div>)}</CollapsibleContent></Collapsible> : null}{phase.proposedResources ? <Collapsible><CollapsibleTrigger className="flex items-center gap-2 text-xs font-medium text-muted-foreground hover:text-foreground"><Database className="size-3.5" />Proposed implementation resources<ChevronDown className="size-3.5" /></CollapsibleTrigger><CollapsibleContent className="mt-3 grid gap-2 text-xs sm:grid-cols-2">{(['forms', 'tables', 'apis', 'backgroundProcesses', 'reports', 'analytics'] as const).map((resourceType) => { const resources = Array.isArray(phase.proposedResources[resourceType]) ? phase.proposedResources[resourceType] : []; return <div key={resourceType} className="rounded-md bg-muted/30 p-3"><p className="font-medium">{resourceType}</p><p className="mt-1 text-muted-foreground">{resources.length > 0 ? resources.map((resource: Record<string, any>) => String(resource.formName || resource.tableName || resource.name || resource.operation || 'Proposed resource')).join(' · ') : 'None proposed'}</p></div>})}</CollapsibleContent></Collapsible> : null}</div> : null}
              <div className="grid gap-3 p-4">
                {tasks.map((task) => {
                  const taskKey = task.legacyTrack ? `${phaseId}:${task.legacyTrack}:${task.legacyIndex}` : `${phaseId}:${task.taskId}`
                  const taskCompleted = progress[taskKey] === true
                  const taskBusy = busyTaskKey === taskKey
                  const suggestions = task.suggestions
                  const hasSuggestions = Boolean(suggestions.tableName || suggestions.tableFields?.length || suggestions.relatedFiles?.length || suggestions.forms?.length)
                  const involvement = roadmapTaskInvolvement(task)
                  const indicatorTone = involvement.summary ? 'border-orange-500/60 bg-orange-500/15 text-orange-700 shadow-[0_0_9px_rgba(249,115,22,0.24)] dark:text-orange-300' : 'border-sky-500/30 bg-sky-500/10 text-sky-600 dark:text-sky-300'
                  return <article key={taskKey} className={cn('grid gap-3 rounded-md bg-background/70 p-4', taskCompleted && 'bg-emerald-500/5', taskBusy && 'opacity-60')}>
                    <div className="flex items-start gap-3"><input type="checkbox" className={cn('mt-1 size-4 shrink-0 accent-emerald-600', involvement.summary && 'accent-orange-500')} checked={taskCompleted} disabled={busyTaskKey !== ''} onChange={(event) => onTaskChange(phaseId, task.taskId, '', '', event.target.checked, task.legacyTrack, task.legacyIndex)} aria-label={`Complete ${task.taskTitle}`} /><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><span className={cn('font-mono text-[10px] text-muted-foreground', involvement.summary && 'text-orange-700 dark:text-orange-300')} title={involvement.summary || undefined}>{task.taskId}</span><Badge variant="outline" className={involvement.summary ? 'border-orange-500/50 bg-orange-500/10 text-orange-700 dark:text-orange-300' : undefined}>{task.taskType}</Badge><Badge variant="outline">{task.track === 'android' ? 'Android' : task.track === 'web' ? 'Web' : 'Shared'}</Badge><div className="flex items-center gap-1" aria-label={involvement.summary ? `Task indicators · ${involvement.summary}` : 'Task indicators'}>{involvement.indicators.map((indicator) => { const IndicatorIcon = executionRoadmapIndicatorIcons[indicator] || Wrench; const indicatorLabel = executionRoadmapIndicatorLabels[indicator] || indicator; const inferred = !task.indicators.includes(indicator); const tooltipLabel = inferred ? `${indicatorLabel} involved (inferred from task resources)` : indicatorLabel; return <Tooltip key={indicator}><TooltipTrigger render={<span className={cn('grid size-6 place-items-center rounded-full border', indicatorTone)} aria-label={tooltipLabel} title={tooltipLabel}><IndicatorIcon className="size-3.5" /></span>} /><TooltipContent>{tooltipLabel}</TooltipContent></Tooltip> })}</div></div><h4 className={cn('mt-1 text-sm font-semibold', taskCompleted && 'text-muted-foreground line-through')}>{task.taskTitle}</h4><p className="mt-1 text-sm leading-5 text-muted-foreground">{task.taskDescription}</p>{task.route || task.apiEndpoint || task.tableName ? <p className="mt-2 text-xs text-muted-foreground">{[task.route, task.apiEndpoint, task.tableName ? `table: ${task.tableName}` : ''].filter(Boolean).join(' · ')}</p> : null}</div>{taskBusy ? <LoaderCircle className="size-4 shrink-0 animate-spin" /> : taskCompleted ? <CheckCircle2 className="size-4 shrink-0 text-emerald-600 dark:text-emerald-300" /> : null}</div>
                    {task.subTasks.length > 0 ? <ol className="ml-7 grid gap-3 border-l pl-4">{task.subTasks.map((subtask) => { const subtaskKey = `${phaseId}:${task.taskId}:${subtask.subtaskId}`; const subtaskCompleted = progress[subtaskKey] === true; const subtaskBusy = busyTaskKey === subtaskKey; return <li key={subtaskKey} className="grid gap-2"><label className={cn('flex cursor-pointer items-start gap-2 text-sm', subtaskBusy && 'opacity-60')}><input type="checkbox" className="mt-0.5 size-4 shrink-0 accent-sky-600" checked={subtaskCompleted} disabled={busyTaskKey !== ''} onChange={(event) => onTaskChange(phaseId, task.taskId, subtask.subtaskId, '', event.target.checked)} aria-label={`Complete ${subtask.subtaskTitle}`} /><span className={cn('min-w-0', subtaskCompleted && 'text-muted-foreground line-through')}><span className="mr-2 font-mono text-[10px] text-muted-foreground">{subtask.subtaskId}</span>{subtask.subtaskTitle}{subtask.subtaskDescription ? <span className="mt-1 block text-xs leading-5 text-muted-foreground">{subtask.subtaskDescription}</span> : null}</span></label>{subtask.acceptanceCriteria.length > 0 ? <div className="ml-6 text-xs text-muted-foreground"><span className="font-medium text-foreground">Acceptance:</span> {subtask.acceptanceCriteria.join(' · ')}</div> : null}{subtask.todos.length > 0 ? <ul className="ml-6 grid gap-1 border-l pl-3">{subtask.todos.map((todo) => { const todoKey = `${phaseId}:${task.taskId}:${subtask.subtaskId}:${todo.todoId}`; const todoCompleted = progress[todoKey] === true; return <li key={todoKey}><label className="flex cursor-pointer items-start gap-2 text-xs"><input type="checkbox" className="mt-0.5 size-3.5 shrink-0 accent-violet-600" checked={todoCompleted} disabled={busyTaskKey !== ''} onChange={(event) => onTaskChange(phaseId, task.taskId, subtask.subtaskId, todo.todoId, event.target.checked)} aria-label={`Complete ${todo.todoTitle}`} /><span className={cn(todoCompleted && 'text-muted-foreground line-through')}><span className="mr-1 font-medium">{todo.todoTitle}</span><span className="text-muted-foreground">· {todo.todoDescription}</span></span></label></li>})}</ul> : null}</li>})}</ol> : null}
                    {hasSuggestions ? <Collapsible><CollapsibleTrigger className="ml-7 flex items-center gap-2 text-xs font-medium text-muted-foreground hover:text-foreground"><Wrench className="size-3.5" />Implementation suggestions<ChevronDown className="size-3.5" /></CollapsibleTrigger><CollapsibleContent className="ml-7 mt-3 grid gap-3 border-l pl-4 text-xs"><div className="grid gap-1"><span className="font-medium">Suggested table</span><span className="font-mono text-muted-foreground">{String(suggestions.tableName || 'No table suggestion')}</span>{Array.isArray(suggestions.tableFields) && suggestions.tableFields.length > 0 ? <span className="font-mono text-muted-foreground">Fields: {suggestions.tableFields.map((field: Record<string, any>) => `${field.name} ${field.type}${field.nullable ? '' : ' NOT NULL'}`).join(' · ')}</span> : null}</div>{Array.isArray(suggestions.forms) && suggestions.forms.length > 0 ? <div className="grid gap-1"><span className="font-medium">Suggested forms</span><span className="text-muted-foreground">{suggestions.forms.map((form: Record<string, any>) => `${form.name} · ${form.action}`).join(' · ')}</span></div> : null}{Array.isArray(suggestions.relatedFiles) && suggestions.relatedFiles.length > 0 ? <div className="grid gap-1"><span className="font-medium">Related files</span><span className="font-mono text-muted-foreground">{suggestions.relatedFiles.join(' · ')}</span></div> : null}</CollapsibleContent></Collapsible> : null}
                  </article>
                })}
              </div>
            </section>
          )
        })}
            </div>
          </section>
        ))}
      </div>
    </div>
  )
}

type NarrativeCanvasNodeKind = 'standard' | 'coordinator' | 'agent' | 'skill'

type NarrativeCanvasNode = {
  id: string
  label: string
  detail: string
  x: number
  y: number
  width: number
  height: number
  tone: 'sky' | 'violet' | 'indigo' | 'cyan' | 'amber' | 'lime' | 'orange' | 'blue' | 'emerald'
  kind?: NarrativeCanvasNodeKind
}

type NarrativeCanvasEdge = {
  from: string
  to: string
  label?: string
  dashed?: boolean
  tone: NarrativeCanvasNode['tone']
}

type NarrativeCoordinatorProcessStep = {
  id: string
  label: string
  owner: string
  technology: string
  action: string
  endpoint: string
  tone: NarrativeCanvasNode['tone']
  kind?: NarrativeCanvasNodeKind
}

type NarrativeCoordinatorProcessSchema = {
  schemaVersion: string
  processKey: string
  tab: string
  coordinator: { agentId: string; label: string; skillId: string; skillLabel: string; calls: number; objective: string }
  specialists: Array<{ agentId: string; label: string; skillId: string; skillLabel: string; calls: number; status: string }>
  skills: Array<{ id: string; label: string; usedBy: string; calls: number }>
  responseSchema: Array<{ key: string; type: string; required: boolean }>
  steps: NarrativeCoordinatorProcessStep[]
  safeguards: string[]
  coordinatorCalls: number
  specialistCalls: number
}

function compactPromptSection(value: unknown, maxChars: number): string {
  const text = typeof value === 'string' ? value : JSON.stringify(value, null, 2) || ''
  return text.length > maxChars ? `${text.slice(0, maxChars)}\n[context compacted for local bridge envelope]` : text
}

function buildNarrativeCoordinatorProcessSchema(agentName: string, skillId: string, skillLabel: string, parallelAgents: unknown[], parallelSkills: unknown[]): NarrativeCoordinatorProcessSchema {
  const agents = parallelAgents.filter((agent): agent is Record<string, any> => Boolean(agent && typeof agent === 'object' && !Array.isArray(agent)))
  const skills = parallelSkills.filter((skill): skill is Record<string, any> => Boolean(skill && typeof skill === 'object' && !Array.isArray(skill)))
  const coordinatorAgent = agents.find((agent) => String(agent.id || '') === 'coordinator') || { id: 'coordinator', name: 'Coordinator', skill: 'coordination' }
  const coordinatorSkillId = String(coordinatorAgent.skill || 'coordination')
  const configuredCoordinatorSkill = skills.find((skill) => String(skill.id || '') === coordinatorSkillId)
  const coordinatorSkillLabel = String(configuredCoordinatorSkill?.label || 'Coordination')
  const configuredSpecialists = agents
    .filter((agent) => String(agent.id || '') !== 'coordinator' && agent.active !== false)
    .map((agent) => {
      const specialistSkillId = String(agent.skill || '')
      const specialistSkill = skills.find((skill) => String(skill.id || '') === specialistSkillId)
      return { agentId: String(agent.id || ''), label: String(agent.name || agent.id || 'Specialist'), skillId: specialistSkillId, skillLabel: String(specialistSkill?.label || specialistSkillId || 'Assigned skill'), calls: 1, status: 'available' }
    })
  const specialistsForProcess = configuredSpecialists.length > 0
    ? configuredSpecialists
    : [{ agentId: 'requirements', label: agentName || 'Narrative Documentation Specialist', skillId: skillId || 'narrative-cleanup', skillLabel: skillLabel || 'Narrative Cleanup', calls: 1, status: 'available' }]
  const processSkills = [
    { id: coordinatorSkillId, label: coordinatorSkillLabel, usedBy: String(coordinatorAgent.name || 'Coordinator'), calls: 1 },
    ...specialistsForProcess.map((specialist) => ({ id: specialist.skillId, label: specialist.skillLabel, usedBy: specialist.label, calls: 1 })),
  ].filter((skill, index, collection) => collection.findIndex((candidate) => candidate.id === skill.id) === index)
  const responseSchema = [
    { key: 'correctedNarrativePreview', type: 'string', required: true },
    { key: 'originalNarrativeSnapshot', type: 'string', required: true },
    { key: 'saveReady', type: 'boolean', required: true },
    { key: 'changeHistoryLog', type: 'array', required: true },
    { key: 'preservedConstraints', type: 'array', required: true },
    { key: 'ambiguities', type: 'array', required: true },
    { key: 'openQuestions', type: 'array', required: true },
    { key: 'sourceReferences', type: 'array', required: true },
  ]
  const steps: NarrativeCoordinatorProcessStep[] = [
    { id: 'browser-refine', label: 'Browser Refine action', owner: 'React', technology: 'Browser action', action: 'runHybridStageAction()', endpoint: 'Tab 1 Refine', tone: 'sky' },
    { id: 'php-context', label: 'PHP context gate', owner: 'PHP', technology: 'PHP request validation', action: 'Validate stage and active phase', endpoint: 'prepare_narrative_hybrid_context', tone: 'violet' },
    { id: 'mysql-rag', label: 'MySQL Memory RAG', owner: 'PHP + MySQL', technology: 'Phase-scoped retrieval', action: 'Load bounded active-phase memory', endpoint: 'aiMemoryBuildContext()', tone: 'indigo' },
    { id: 'react-prompt', label: 'React prompt + schema', owner: 'React', technology: 'Prompt assembly', action: `Fill ${responseSchema.length}-field Stage 1 JSON contract`, endpoint: 'hybrid prompt', tone: 'cyan' },
    { id: 'php-transaction', label: 'PHP MySQL transaction', owner: 'PHP + MySQL', technology: 'AI transaction + handoff', action: 'Persist transaction and materialize handoff', endpoint: 'begin_phase_codex_transaction · prepare_visual_codex_handoff', tone: 'amber' },
    { id: 'bridge-ready', label: 'Codex bridge gate', owner: 'User IDE bridge', technology: 'Visible Chat transport', action: 'Check launcher, thread, extension, and busy state', endpoint: '127.0.0.1:43127/health', tone: 'blue' },
    { id: 'coordinator-dispatch', label: 'Smart Universal Coordinator dispatch', owner: 'Coordinator', technology: coordinatorSkillLabel, action: 'Analyze Tab 1 task level and route only the required 1–3 specialists', endpoint: '/orchestration-run', tone: 'amber', kind: 'coordinator' },
    { id: 'specialist-call', label: 'Selected analysis agent(s)', owner: 'Required analyst(s)', technology: 'Assigned analyst skills', action: 'Return scoped evidence and the exact Tab 1 contract through visible Codex Chat', endpoint: 'stage=analysis', tone: 'lime', kind: 'agent' },
    { id: 'contract-check', label: 'Independent contract and safety check', owner: 'Contract & Safety Checker', technology: 'contract-check', action: 'Reject incomplete, unsafe, or out-of-scope plans before any update', endpoint: 'stage=quality', tone: 'violet', kind: 'agent' },
    { id: 'coordinator-approval', label: 'Coordinator approval gate', owner: 'Smart Universal Coordinator', technology: coordinatorSkillLabel, action: 'Approve review-only completion or authorize one implementation owner and exact scope', endpoint: 'approval=required', tone: 'amber', kind: 'coordinator' },
    { id: 'implementation-owner', label: 'Approved implementation owner', owner: 'Code or Database Implementation Agent', technology: 'code-implementation · database-implementation', action: 'Apply only the approved source or reversible database change and report evidence', endpoint: 'stage=implementation', tone: 'orange', kind: 'agent' },
    { id: 'test-validation', label: 'Independent test and validation', owner: 'Test & Validation Agent', technology: 'testing-verification', action: 'Run focused non-destructive checks and report regressions and release readiness', endpoint: 'stage=quality', tone: 'lime', kind: 'agent' },
    { id: 'final-verification', label: 'Final coordinator verification', owner: 'Smart Universal Coordinator', technology: coordinatorSkillLabel, action: 'Require checker approval, implementation evidence, tester pass, and the exact result contract', endpoint: 'terminal-gate', tone: 'amber', kind: 'coordinator' },
    { id: 'php-readback', label: 'PHP + MySQL read-back', owner: 'PHP + MySQL', technology: 'Validation and persistence', action: 'Validate JSON, save revision, verify active draft', endpoint: 'save_phase_narrative_codex_reply', tone: 'emerald' },
    { id: 'react-hydrate', label: 'React result hydration', owner: 'React', technology: 'Rendered read-back', action: 'Update draft, revision, change log, and status', endpoint: 'narrative_draft + narrative_revision', tone: 'sky' },
  ]
  return {
    schemaVersion: 'builderx.narrative-coordinator.v1',
    processKey: 'tab1-narrative-refine',
    tab: 'Narrative & Cleanup',
    coordinator: { agentId: String(coordinatorAgent.id || 'coordinator'), label: 'Smart Universal Coordinator', skillId: coordinatorSkillId, skillLabel: coordinatorSkillLabel, calls: 3, objective: 'Analyze the Tab 1 task level, select only required analysts, gate implementation, and close only after testing and read-back evidence.' },
    specialists: specialistsForProcess,
    skills: processSkills,
    responseSchema,
    steps,
    safeguards: ['Active phase is required before dispatch.', 'Context and bridge payloads remain bounded.', 'Only the Coordinator can authorize an implementation owner.', 'Code and database writers receive only an explicit approved scope.', 'Checker approval, tester evidence, persistence, and database read-back must verify before React replaces the draft.'],
    coordinatorCalls: 3,
    specialistCalls: specialistsForProcess.length,
  }
}

const narrativeCanvasTone: Record<NarrativeCanvasNode['tone'], { fill: string; stroke: string; text: string }> = {
  sky: { fill: '#082f49', stroke: '#38bdf8', text: '#bae6fd' },
  violet: { fill: '#2e1065', stroke: '#a78bfa', text: '#ddd6fe' },
  indigo: { fill: '#1e1b4b', stroke: '#818cf8', text: '#c7d2fe' },
  cyan: { fill: '#083344', stroke: '#22d3ee', text: '#a5f3fc' },
  amber: { fill: '#451a03', stroke: '#f59e0b', text: '#fde68a' },
  lime: { fill: '#1a2e05', stroke: '#a3e635', text: '#d9f99d' },
  orange: { fill: '#431407', stroke: '#fb923c', text: '#fed7aa' },
  blue: { fill: '#172554', stroke: '#60a5fa', text: '#bfdbfe' },
  emerald: { fill: '#022c22', stroke: '#34d399', text: '#a7f3d0' },
}

function narrativeCanvasRoundRect(context: CanvasRenderingContext2D, x: number, y: number, width: number, height: number, radius: number): void {
  const r = Math.min(radius, width / 2, height / 2)
  context.beginPath()
  context.moveTo(x + r, y)
  context.arcTo(x + width, y, x + width, y + height, r)
  context.arcTo(x + width, y + height, x, y + height, r)
  context.arcTo(x, y + height, x, y, r)
  context.arcTo(x, y, x + width, y, r)
  context.closePath()
}

function narrativeCanvasWrappedText(context: CanvasRenderingContext2D, text: string, x: number, y: number, maxWidth: number, lineHeight: number, maxLines: number): number {
  const words = text.split(/\s+/).filter(Boolean)
  const lines: string[] = []
  let current = ''
  words.forEach((word) => {
    const next = current === '' ? word : `${current} ${word}`
    if (current !== '' && context.measureText(next).width > maxWidth) {
      lines.push(current)
      current = word
    } else {
      current = next
    }
  })
  if (current !== '') lines.push(current)
  const visibleLines = lines.slice(0, maxLines)
  visibleLines.forEach((line, index) => context.fillText(line, x, y + index * lineHeight))
  return visibleLines.length
}

function NarrativeProcessCanvas({ process }: { process: NarrativeCoordinatorProcessSchema }) {
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const dragRef = React.useRef<{ x: number; y: number; offsetX: number; offsetY: number } | null>(null)
  const [view, setView] = React.useState({ scale: 0.58, offsetX: 18, offsetY: 24 })

  const nodes = React.useMemo<NarrativeCanvasNode[]>(() => process.steps.map((step, index) => ({
    id: step.id,
    label: step.label,
    detail: `${step.technology} · ${step.action} · ${step.endpoint}`,
    x: 40 + index * 230,
    y: 175,
    width: 190,
    height: 84,
    tone: step.tone,
    kind: step.kind,
  })), [process])

  const edges = React.useMemo<NarrativeCanvasEdge[]>(() => process.steps.slice(0, -1).map((step, index) => ({
    from: step.id,
    to: process.steps[index + 1].id,
    label: step.id === 'coordinator-dispatch' ? 'selects 1–3 analysts' : step.id === 'implementation-owner' ? 'conditional writer' : step.id === 'test-validation' ? 'required test gate' : undefined,
    tone: step.tone,
  })), [process])

  const nodeMap = React.useMemo(() => new Map(nodes.map((node) => [node.id, node])), [nodes])

  const fitToView = React.useCallback(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const width = canvas.clientWidth || 900
    const height = canvas.clientHeight || 430
    const graph = { x: 20, y: 20, width: Math.max(2480, process.steps.length * 230 + 60), height: 548 }
    const scale = Math.max(0.25, Math.min(1.15, Math.min((width - 36) / graph.width, (height - 36) / graph.height)))
    setView({ scale, offsetX: (width - graph.width * scale) / 2 - graph.x * scale, offsetY: (height - graph.height * scale) / 2 - graph.y * scale })
  }, [process.steps.length])

  React.useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const parent = canvas.parentElement
    if (!parent) return
    let disposed = false
    const draw = () => {
      if (disposed) return
      const ratio = Math.min(2, window.devicePixelRatio || 1)
      const width = parent.clientWidth
      const height = parent.clientHeight
      canvas.width = Math.max(1, Math.floor(width * ratio))
      canvas.height = Math.max(1, Math.floor(height * ratio))
      const context = canvas.getContext('2d')
      if (!context) return
      context.setTransform(ratio, 0, 0, ratio, 0, 0)
      context.clearRect(0, 0, width, height)
      const backgroundGradient = context.createLinearGradient(0, 0, width, height)
      backgroundGradient.addColorStop(0, '#1f3357')
      backgroundGradient.addColorStop(0.58, '#142643')
      backgroundGradient.addColorStop(1, '#0b1020')
      context.fillStyle = backgroundGradient
      context.fillRect(0, 0, width, height)
      context.save()
      context.translate(view.offsetX, view.offsetY)
      context.scale(view.scale, view.scale)
      context.fillStyle = '#cbd5e1'
      context.font = '700 13px Geist, Inter, sans-serif'
      context.fillText(`TAB 1 · NARRATIVE & CLEANUP · ${process.coordinator.label.toUpperCase()} PROCESS`, 40, 38)
      context.fillStyle = '#64748b'
      context.font = '500 11px Geist, Inter, sans-serif'
      context.fillText(`Solid = ${process.steps.length} coordinator-owned steps · up to 3 selected analysts · checker/writer/test gates · ${process.skills.length} skills`, 40, 58)

      const drawArrow = (edge: NarrativeCanvasEdge) => {
        const from = nodeMap.get(edge.from)
        const to = nodeMap.get(edge.to)
        if (!from || !to) return
        const start = { x: from.x + from.width, y: from.y + from.height / 2 }
        const end = { x: to.x, y: to.y + to.height / 2 }
        const controlX = (start.x + end.x) / 2
        const tone = narrativeCanvasTone[edge.tone]
        context.save()
        context.strokeStyle = tone.stroke
        context.globalAlpha = edge.dashed ? 0.78 : 0.92
        context.lineWidth = 2.5
        context.setLineDash(edge.dashed ? [9, 7] : [])
        context.beginPath()
        context.moveTo(start.x, start.y)
        context.bezierCurveTo(controlX, start.y, controlX, end.y, end.x, end.y)
        context.stroke()
        context.setLineDash([])
        const angle = Math.atan2(end.y - (end.y + start.y) / 2, end.x - controlX)
        context.fillStyle = tone.stroke
        context.beginPath()
        context.moveTo(end.x, end.y)
        context.lineTo(end.x - 10 * Math.cos(angle - Math.PI / 6), end.y - 10 * Math.sin(angle - Math.PI / 6))
        context.lineTo(end.x - 10 * Math.cos(angle + Math.PI / 6), end.y - 10 * Math.sin(angle + Math.PI / 6))
        context.closePath()
        context.fill()
        if (edge.label) {
          const labelX = controlX
          const labelY = (start.y + end.y) / 2 - 8
          context.font = '600 10px Geist, Inter, sans-serif'
          const labelWidth = context.measureText(edge.label).width + 12
          context.fillStyle = '#0f1b2d'
          narrativeCanvasRoundRect(context, labelX - labelWidth / 2, labelY - 12, labelWidth, 18, 7)
          context.fill()
          context.fillStyle = tone.text
          context.textAlign = 'center'
          context.fillText(edge.label, labelX, labelY)
          context.textAlign = 'left'
        }
        context.restore()
      }
      edges.forEach(drawArrow)

      const drawSymbol = (node: NarrativeCanvasNode, tone: { stroke: string; text: string }) => {
        const centerX = node.x + 24
        const centerY = node.y + 42
        context.save()
        context.strokeStyle = tone.stroke
        context.fillStyle = tone.text
        context.lineWidth = 2
        if (node.kind === 'coordinator') {
          context.beginPath()
          for (let index = 0; index < 6; index += 1) {
            const angle = (Math.PI / 3) * index - Math.PI / 6
            const x = centerX + Math.cos(angle) * 13
            const y = centerY + Math.sin(angle) * 13
            if (index === 0) context.moveTo(x, y)
            else context.lineTo(x, y)
          }
          context.closePath()
          context.stroke()
          context.font = '700 12px Geist, Inter, sans-serif'
          context.textAlign = 'center'
          context.fillText('C', centerX, centerY + 4)
          context.fillStyle = tone.stroke
          ;[[-18, -14], [18, -14], [0, 20]].forEach(([x, y]) => { context.beginPath(); context.arc(centerX + x, centerY + y, 3, 0, Math.PI * 2); context.fill() })
          context.textAlign = 'left'
        } else if (node.kind === 'agent') {
          context.beginPath()
          context.arc(centerX, centerY - 5, 7, 0, Math.PI * 2)
          context.stroke()
          narrativeCanvasRoundRect(context, centerX - 11, centerY + 5, 22, 14, 7)
          context.stroke()
          context.beginPath()
          context.moveTo(centerX + 16, centerY - 14)
          context.lineTo(centerX + 16, centerY - 4)
          context.moveTo(centerX + 11, centerY - 9)
          context.lineTo(centerX + 21, centerY - 9)
          context.stroke()
        } else if (node.kind === 'skill') {
          narrativeCanvasRoundRect(context, centerX - 14, centerY - 14, 28, 28, 6)
          context.stroke()
          context.beginPath()
          context.moveTo(centerX - 7, centerY - 3)
          context.lineTo(centerX + 7, centerY - 3)
          context.moveTo(centerX - 7, centerY + 4)
          context.lineTo(centerX + 7, centerY + 4)
          context.stroke()
        } else {
          context.beginPath()
          context.arc(centerX, centerY, 13, 0, Math.PI * 2)
          context.stroke()
          context.fillStyle = tone.stroke
          context.beginPath()
          context.arc(centerX, centerY, 4, 0, Math.PI * 2)
          context.fill()
        }
        context.restore()
      }

      nodes.forEach((node) => {
        const tone = narrativeCanvasTone[node.tone]
        context.save()
        context.shadowColor = tone.stroke
        context.shadowBlur = 16
        context.fillStyle = tone.fill
        narrativeCanvasRoundRect(context, node.x, node.y, node.width, node.height, 12)
        context.fill()
        context.shadowBlur = 0
        context.strokeStyle = tone.stroke
        context.globalAlpha = 0.86
        context.lineWidth = 1.5
        context.stroke()
        context.globalAlpha = 1
        drawSymbol(node, tone)
        context.fillStyle = '#f8fafc'
        context.font = '700 12px Geist, Inter, sans-serif'
        narrativeCanvasWrappedText(context, node.label, node.x + 48, node.y + 30, node.width - 58, 14, 2)
        context.fillStyle = tone.text
        context.font = '500 10px Geist, Inter, sans-serif'
        narrativeCanvasWrappedText(context, node.detail, node.x + 48, node.y + 58, node.width - 58, 12, 2)
        context.restore()
      })
      context.restore()
    }
    const observer = new ResizeObserver(draw)
    observer.observe(parent)
    draw()
    return () => {
      disposed = true
      observer.disconnect()
    }
  }, [edges, nodeMap, nodes, process, view])

  React.useEffect(() => {
    const frame = window.requestAnimationFrame(fitToView)
    return () => window.cancelAnimationFrame(frame)
  }, [fitToView])

  const zoomAroundCenter = (factor: number) => {
    const canvas = canvasRef.current
    if (!canvas) return
    const centerX = canvas.clientWidth / 2
    const centerY = canvas.clientHeight / 2
    setView((current) => {
      const scale = Math.max(0.25, Math.min(1.6, current.scale * factor))
      const graphX = (centerX - current.offsetX) / current.scale
      const graphY = (centerY - current.offsetY) / current.scale
      return { scale, offsetX: centerX - graphX * scale, offsetY: centerY - graphY * scale }
    })
  }

  const handleWheel = (event: React.WheelEvent<HTMLCanvasElement>) => {
    event.preventDefault()
    const canvas = canvasRef.current
    if (!canvas) return
    const rect = canvas.getBoundingClientRect()
    const pointerX = event.clientX - rect.left
    const pointerY = event.clientY - rect.top
    setView((current) => {
      const scale = Math.max(0.25, Math.min(1.6, current.scale * (event.deltaY < 0 ? 1.1 : 0.9)))
      const graphX = (pointerX - current.offsetX) / current.scale
      const graphY = (pointerY - current.offsetY) / current.scale
      return { scale, offsetX: pointerX - graphX * scale, offsetY: pointerY - graphY * scale }
    })
  }

  const handlePointerDown = (event: React.PointerEvent<HTMLCanvasElement>) => {
    event.currentTarget.setPointerCapture(event.pointerId)
    dragRef.current = { x: event.clientX, y: event.clientY, offsetX: view.offsetX, offsetY: view.offsetY }
  }

  const handlePointerMove = (event: React.PointerEvent<HTMLCanvasElement>) => {
    const drag = dragRef.current
    if (!drag) return
    setView((current) => ({ ...current, offsetX: drag.offsetX + event.clientX - drag.x, offsetY: drag.offsetY + event.clientY - drag.y }))
  }

  const handlePointerUp = (event: React.PointerEvent<HTMLCanvasElement>) => {
    if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId)
    dragRef.current = null
  }

  const handleKeyDown = (event: React.KeyboardEvent<HTMLCanvasElement>) => {
    if (event.key === '+' || event.key === '=') {
      event.preventDefault()
      zoomAroundCenter(1.15)
    } else if (event.key === '-') {
      event.preventDefault()
      zoomAroundCenter(0.87)
    } else if (event.key.toLowerCase() === 'r') {
      event.preventDefault()
      fitToView()
    }
  }

  return (
    <section aria-labelledby="narrative-process-canvas-title" className="flex min-h-0 flex-1 flex-col text-foreground">
      <div className="sticky top-2 z-20 flex flex-wrap items-start justify-between gap-3 rounded-md bg-popover/95 px-2 py-2 shadow-sm backdrop-blur supports-[backdrop-filter]:bg-popover/85">
        <div>
          <p className="text-xs font-semibold uppercase tracking-wider text-sky-300">Interactive process canvas</p>
          <h2 id="narrative-process-canvas-title" className="mt-1 text-base font-semibold">Tab 1 Refine · coordinator-owned process</h2>
          <p className="mt-1 text-xs leading-5 text-muted-foreground">The coordinator schema supplies the real React, PHP, MySQL Memory RAG, bridge, analyst selection, checker, approval, conditional writer, tester, persistence, and terminal read-back stages.</p>
          <div className="mt-2 flex flex-wrap gap-1.5" aria-label="Coordinator process counts">
            <Badge variant="secondary">Coordinator: {process.coordinatorCalls}</Badge>
            <Badge variant="outline">Configured agents: {process.specialistCalls}</Badge>
            <Badge variant="outline">Steps: {process.steps.length}</Badge>
            <Badge variant="outline">Skills: {process.skills.length}</Badge>
            <Badge variant="outline">Schema fields: {process.responseSchema.length}</Badge>
          </div>
        </div>
        <div className="flex items-center gap-1" aria-label="Process canvas controls">
          <Button type="button" variant="outline" size="icon-sm" onClick={() => zoomAroundCenter(1.18)} aria-label="Zoom in process canvas" title="Zoom in">+</Button>
          <Button type="button" variant="outline" size="icon-sm" onClick={() => zoomAroundCenter(0.85)} aria-label="Zoom out process canvas" title="Zoom out">−</Button>
          <Button type="button" variant="outline" size="sm" onClick={fitToView}>Fit</Button>
          <Button type="button" variant="ghost" size="sm" onClick={() => setView({ scale: 0.58, offsetX: 18, offsetY: 24 })}>Reset</Button>
          <Badge variant="outline">{Math.round(view.scale * 100)}%</Badge>
        </div>
      </div>
      <div className="mt-3 min-h-0 min-w-0 flex-1 overflow-hidden rounded-md bg-gradient-to-br from-sky-950/30 via-background to-violet-950/30">
        <canvas
          ref={canvasRef}
          tabIndex={0}
          role="img"
          aria-label={`Zoomable and draggable coordinator-owned Tab 1 process flowchart with ${process.steps.length} steps, up to 3 selected analysts, checker, conditional implementation writer, tester, ${process.skills.length} skills, React, PHP, MySQL Memory RAG, visible Codex Chat, validated persistence, and React read-back.`}
          className="block h-full min-h-0 w-full cursor-grab touch-none outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset active:cursor-grabbing"
          onWheel={handleWheel}
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={handlePointerUp}
          onPointerCancel={handlePointerUp}
          onKeyDown={handleKeyDown}
          onDoubleClick={fitToView}
        />
      </div>
      <div className="mt-3 flex flex-wrap items-center gap-x-4 gap-y-2 text-[11px] text-muted-foreground" aria-label="Process canvas legend">
        <span className="inline-flex items-center gap-2"><span className="h-px w-6 bg-sky-400" aria-hidden="true" />Coordinator-owned runtime steps</span>
        <span className="inline-flex items-center gap-2"><span className="h-px w-6 bg-lime-400" aria-hidden="true" />{process.specialists[0]?.label || 'Assigned specialist'} · {process.skills.find((skill) => skill.id === process.specialists[0]?.skillId)?.label || 'assigned skill'}</span>
        <span className="inline-flex items-center gap-2"><span className="size-2 rounded-full bg-emerald-400" aria-hidden="true" />PHP/database verified read-back</span>
      </div>
    </section>
  )
}

function NarrativeDraftView() {
  const selectedPhase = phaseData?.selectedPhase ?? null
  const tasks = phaseData?.tasks ?? []
  const narrativeAgent = (Array.isArray(phaseData?.settings?.parallelAgents) ? phaseData.settings.parallelAgents : []).find((agent: Record<string, any>) => String(agent.skill || '') === 'narrative-cleanup')
  const narrativeAgentName = String(narrativeAgent?.name || 'Narrative Documentation Specialist')
  const narrativeSkillId = String(narrativeAgent?.skill || 'narrative-cleanup')
  const narrativeSkillLabel = String((Array.isArray(phaseData?.settings?.parallelSkills) ? phaseData.settings.parallelSkills : []).find((skill: Record<string, any>) => String(skill.id || '') === narrativeSkillId)?.label || 'Narrative Cleanup')
  const smartCoordinatorAgents = (Array.isArray(phaseData?.settings?.parallelAgents) ? phaseData.settings.parallelAgents : [])
    .filter((agent: Record<string, any>) => agent.active !== false)
  const generatedDraft = buildProjectPhaseDocumentationPrompt(selectedPhase, tasks)
  const persistedNarrativeRevision = phaseData?.narrativeRevision && typeof phaseData.narrativeRevision === 'object' && !Array.isArray(phaseData.narrativeRevision) ? phaseData.narrativeRevision : {}
  const persistedNarrativeChanges = Array.isArray(persistedNarrativeRevision.changeHistoryLog)
    ? persistedNarrativeRevision.changeHistoryLog.filter((change: unknown) => change && typeof change === 'object') as Array<NarrativeCopyeditChange>
    : []
  const hasPersistedNarrativeRevision = String(persistedNarrativeRevision.revisionKey || '').trim() !== ''
  const [editorValue, setEditorValue] = React.useState(() => phaseData?.narrativeDraft || generatedDraft)
  const [sectionValues, setSectionValues] = React.useState<NarrativeDraftSectionValues>(() => parseNarrativeDraftSections(phaseData?.narrativeDraft || generatedDraft))
  const [saveBusy, setSaveBusy] = React.useState(false)
  const [saveMessage, setSaveMessage] = React.useState('')
  const [narrativeAiOutput, setNarrativeAiOutput] = React.useState<Record<string, any>>(() => phaseData?.narrativeAiOutput || {})
  const [requirementsAnalysis, setRequirementsAnalysis] = React.useState<Record<string, any>>(() => phaseData?.requirementsAnalysis || {})
  const [architectureManifest, setArchitectureManifest] = React.useState<Record<string, any>>(() => phaseData?.architectureManifest || {})
  const [executionRoadmap, setExecutionRoadmap] = React.useState<Record<string, any>>(() => phaseData?.executionRoadmap || {})
  const [executionRoadmapProgress, setExecutionRoadmapProgress] = React.useState<Record<string, boolean>>(() => phaseData?.executionRoadmapProgress || {})
  const [executionRoadmapBusyTask, setExecutionRoadmapBusyTask] = React.useState('')
  const [activeTab, setActiveTab] = React.useState<NarrativeGrammarScope>('editor')
  const [aiConfirmationScope, setAiConfirmationScope] = React.useState<NarrativeGrammarScope | null>(null)
  const [grammarBusyScope, setGrammarBusyScope] = React.useState<NarrativeGrammarScope | ''>('')
  const [grammarMessage, setGrammarMessage] = React.useState('')
  const [hybridBusyStage, setHybridBusyStage] = React.useState<string>('')
  const [hybridResult, setHybridResult] = React.useState<{ stage: string; label: string; text: string; tokens: number } | null>(null)
  const [hybridNotice, setHybridNotice] = React.useState('')
  const [narrativeProcessOpen, setNarrativeProcessOpen] = React.useState(false)
  const [narrativeProcessTab, setNarrativeProcessTab] = React.useState<'canvas' | 'process'>('canvas')
  const [narrativeBridgeStatus, setNarrativeBridgeStatus] = React.useState<'checking' | 'ready' | 'needs-chat' | 'needs-setup' | 'offline'>('checking')
  const [narrativeBridgeHealth, setNarrativeBridgeHealth] = React.useState<Record<string, any>>({})
  const [narrativeBridgeCheckBusy, setNarrativeBridgeCheckBusy] = React.useState(false)
  const [narrativeBridgeRestartBusy, setNarrativeBridgeRestartBusy] = React.useState(false)
  const [editorPreviewValue, setEditorPreviewValue] = React.useState<string | null>(null)
  const [editorChangesList, setEditorChangesList] = React.useState<Array<NarrativeCopyeditChange>>(() => persistedNarrativeChanges)
  const [editorCheckCompleted, setEditorCheckCompleted] = React.useState(hasPersistedNarrativeRevision)
  const [editorRevisionSaved, setEditorRevisionSaved] = React.useState(hasPersistedNarrativeRevision && persistedNarrativeRevision.saveReady === true)
  const [requirementsChecklistBusyId, setRequirementsChecklistBusyId] = React.useState('')
  const [requirementsSelectionBusyId, setRequirementsSelectionBusyId] = React.useState('')
  const [requirementsGapBusyId, setRequirementsGapBusyId] = React.useState('')
  const [draftGuideOpen, setDraftGuideOpen] = React.useState(false)
  const [draftGuideCopyMessage, setDraftGuideCopyMessage] = React.useState('')
  const aiCompletionAudioContextRef = React.useRef<AudioContext | null>(null)
  const completedAiDingJobIdsRef = React.useRef<Set<string>>(new Set())
  const [, setGrammarRevision] = React.useState(0)
  const scrollToNarrativeQuickJump = React.useCallback((targetId: string, updateHash = true) => {
    const target = document.getElementById(targetId)
    if (!target) return false
    const scrollContainer = target.closest<HTMLElement>('[data-narrative-scroll-container]')
    if (scrollContainer) {
      const regionRect = scrollContainer.getBoundingClientRect()
      const targetRect = target.getBoundingClientRect()
      scrollContainer.scrollTo({ top: scrollContainer.scrollTop + targetRect.top - regionRect.top - 12, behavior: 'smooth' })
    } else {
      target.scrollIntoView({ behavior: 'smooth', block: 'start' })
    }
    target.focus({ preventScroll: true })
    if (updateHash) {
      const nextUrl = new URL(window.location.href)
      nextUrl.hash = targetId
      window.history.replaceState(window.history.state, '', `${nextUrl.pathname}${nextUrl.search}${nextUrl.hash}`)
    }
    return true
  }, [])
  const copyDraftGuide = React.useCallback(async () => {
    try {
      if (!navigator.clipboard?.writeText) throw new Error('Clipboard access is unavailable.')
      await navigator.clipboard.writeText(narrativeDraftGuideCopyText)
      setDraftGuideCopyMessage('Copied to clipboard.')
      window.setTimeout(() => setDraftGuideCopyMessage(''), 1800)
    } catch {
      setDraftGuideCopyMessage('Clipboard access is unavailable. Select the text manually.')
    }
  }, [])
  const phaseTitle = selectedPhase
    ? `Phase ${phaseField(selectedPhase, 'phase_number')}: ${phaseField(selectedPhase, 'phase_title', 'Untitled')}`
    : 'New Narrative Draft'
  const phaseSummary = phaseField(selectedPhase, 'phase_summary', 'Narrative planning starts here before Project Phases are created.')
  const selectedPhaseKey = phaseField(selectedPhase, 'phase_key')

  React.useEffect(() => {
    setEditorValue(phaseData?.narrativeDraft || generatedDraft)
    setSectionValues(parseNarrativeDraftSections(phaseData?.narrativeDraft || generatedDraft))
    setNarrativeAiOutput(phaseData?.narrativeAiOutput || {})
    setRequirementsAnalysis(phaseData?.requirementsAnalysis || {})
    setArchitectureManifest(phaseData?.architectureManifest || {})
    setExecutionRoadmap(phaseData?.executionRoadmap || {})
    setExecutionRoadmapProgress(phaseData?.executionRoadmapProgress || {})
    setExecutionRoadmapBusyTask('')
    setSaveMessage('')
    setAiConfirmationScope(null)
    setGrammarBusyScope('')
    setGrammarMessage('')
    setEditorPreviewValue(null)
    const savedRevision = phaseData?.narrativeRevision && typeof phaseData.narrativeRevision === 'object' && !Array.isArray(phaseData.narrativeRevision) ? phaseData.narrativeRevision : {}
    const savedChanges = Array.isArray(savedRevision.changeHistoryLog)
      ? savedRevision.changeHistoryLog.filter((change: unknown) => change && typeof change === 'object') as Array<NarrativeCopyeditChange>
      : []
    const hasSavedRevision = String(savedRevision.revisionKey || '').trim() !== ''
    setEditorChangesList(savedChanges)
    setEditorCheckCompleted(hasSavedRevision)
    setEditorRevisionSaved(hasSavedRevision && savedRevision.saveReady === true)
    setRequirementsChecklistBusyId('')
    setRequirementsSelectionBusyId('')
    setRequirementsGapBusyId('')
    completedAiDingJobIdsRef.current.clear()
  }, [generatedDraft, selectedPhaseKey])

  React.useEffect(() => {
    const targetId = window.location.hash.replace(/^#/, '')
    if (!narrativeQuickJumpTargets.some((target) => target.id === targetId)) return
    const frameId = window.requestAnimationFrame(() => {
      scrollToNarrativeQuickJump(targetId, false)
    })
    return () => window.cancelAnimationFrame(frameId)
  }, [scrollToNarrativeQuickJump])

  const checkNarrativeBridge = React.useCallback(async (quiet = false): Promise<boolean> => {
    if (!quiet) {
      setNarrativeBridgeCheckBusy(true)
      setNarrativeBridgeStatus('checking')
    }
    try {
      const response = await fetch(visualCodexBridgeRequestUrl('/keepalive'), { cache: 'no-store', keepalive: true })
      const result = await response.json()
      setNarrativeBridgeHealth(result && typeof result === 'object' ? result : {})
      const bridgeReady = response.ok
        && result?.ok === true
        && result?.code_ready === true
        && result?.context_ready === true
        && result?.companion_extension_installed === true
        && result?.orchestration_extension_installed === true
      if (!bridgeReady) {
        setNarrativeBridgeStatus('needs-setup')
        return false
      }
      const activeChatReady = result?.active_thread_ready === true
      setNarrativeBridgeStatus(activeChatReady ? 'ready' : 'needs-chat')
      return activeChatReady
    } catch {
      setNarrativeBridgeHealth({})
      setNarrativeBridgeStatus('offline')
      return false
    } finally {
      if (!quiet) setNarrativeBridgeCheckBusy(false)
    }
  }, [])

  const reconnectNarrativeBridge = React.useCallback(async () => {
    if (narrativeBridgeRestartBusy) return
    setNarrativeBridgeRestartBusy(true)
    setNarrativeBridgeStatus('checking')
    setGrammarMessage('Reloading VS Code and reconnecting Codex plus all AI agent extensions…')
    try {
      const response = await fetch(visualCodexBridgeRequestUrl('/restart'), { method: 'POST', headers: { 'Content-Type': 'application/json' } })
      const result = await response.json()
      if (!response.ok || result?.ok !== true) throw new Error(result?.message || 'The Codex bridge could not be restarted.')
      setGrammarMessage('VS Code reload requested. Reconnecting Codex and all AI agent extensions…')
      let connected = false
      for (let attempt = 0; attempt < 8; attempt += 1) {
        await new Promise((resolve) => window.setTimeout(resolve, attempt === 0 ? 2500 : 1000))
        connected = await checkNarrativeBridge(true)
        if (connected) break
      }
      if (!connected) {
        setGrammarMessage('VS Code reloaded, but Codex or an AI agent extension is still reconnecting. Try again in a few seconds.')
      } else {
        setGrammarMessage('Codex and all AI agent extensions are connected. The active Codex Chat status is shown above.')
      }
    } catch (error) {
      setNarrativeBridgeStatus('offline')
      setGrammarMessage(error instanceof Error ? error.message : 'Codex and AI agent reconnection failed.')
    } finally {
      setNarrativeBridgeRestartBusy(false)
    }
  }, [checkNarrativeBridge, narrativeBridgeRestartBusy])

  React.useEffect(() => {
    void checkNarrativeBridge()
    // The legacy bridge is checked only when this surface opens. The active
    // Phase Builder uses the authenticated realtime status stream instead of
    // keeping a five-second health poll alive.
  }, [checkNarrativeBridge])

  function armAiCompletionDing() {
    if (typeof window === 'undefined') return
    try {
      const AudioContextConstructor = window.AudioContext || (window as typeof window & { webkitAudioContext?: typeof AudioContext }).webkitAudioContext
      if (!AudioContextConstructor) return
      if (!aiCompletionAudioContextRef.current || aiCompletionAudioContextRef.current.state === 'closed') {
        aiCompletionAudioContextRef.current = new AudioContextConstructor()
      }
      if (aiCompletionAudioContextRef.current.state === 'suspended') {
        void aiCompletionAudioContextRef.current.resume().catch(() => undefined)
      }
    } catch {
      // Audio feedback is optional and must never block an AI action.
    }
  }

  function playAiCompletionDing(jobId: string) {
    if (jobId === '' || completedAiDingJobIdsRef.current.has(jobId)) return
    completedAiDingJobIdsRef.current.add(jobId)
    const audioContext = aiCompletionAudioContextRef.current
    if (!audioContext) return

    const play = () => {
      try {
        const startAt = audioContext.currentTime + 0.02
        ;[[880, 0], [1174.66, 0.12]].forEach(([frequency, delay]) => {
          const oscillator = audioContext.createOscillator()
          const gain = audioContext.createGain()
          const toneStart = startAt + delay
          const toneEnd = toneStart + 0.18
          oscillator.type = 'sine'
          oscillator.frequency.setValueAtTime(frequency, toneStart)
          gain.gain.setValueAtTime(0.0001, toneStart)
          gain.gain.exponentialRampToValueAtTime(0.08, toneStart + 0.015)
          gain.gain.exponentialRampToValueAtTime(0.0001, toneEnd)
          oscillator.connect(gain)
          gain.connect(audioContext.destination)
          oscillator.start(toneStart)
          oscillator.stop(toneEnd)
        })
      } catch {
        // Keep completion handling successful when sound output is unavailable.
      }
    }

    if (audioContext.state === 'suspended') {
      void audioContext.resume().then(play).catch(() => undefined)
    } else {
      play()
    }
  }

  async function waitForNarrativeCodexIdle(scopeLabel: string): Promise<void> {
    for (let attempt = 0; attempt < 30; attempt += 1) {
      const response = await fetch(visualCodexBridgeRequestUrl('/health'), { cache: 'no-store' })
      const health = await response.json()
      if (!response.ok || health?.ok !== true || health?.code_ready !== true || health?.companion_extension_installed !== true || health?.orchestration_extension_installed !== true) {
        throw new Error(String(health?.extension_probe_message || 'The VS Code Codex bridge has no supported direct-text send command. The implementation-wrapper fallback is disabled.'))
      }
      if (health.active_thread_ready !== true) {
        throw new Error(`Open an active Codex Chat thread in VS Code before sending ${scopeLabel}.`)
      }
      if (health.active_thread_busy !== true) return
      setGrammarMessage(`Codex Chat is busy. ${scopeLabel} is waiting for the active task to finish…`)
      await new Promise((resolve) => window.setTimeout(resolve, 2000))
    }
    throw new Error(`${scopeLabel} could not start because the active Codex Chat thread stayed busy for 60 seconds. Let the current task finish, then retry Refine.`)
  }

  async function beginMySqlAiTransaction(stageKey: string, operationKey: string, prompt: string): Promise<string> {
    const formData = new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', 'begin_phase_codex_transaction')
    formData.set('phase_key', selectedPhaseKey)
    formData.set('stage_key', stageKey)
    formData.set('operation_key', operationKey)
    formData.set('prompt', prompt)
    const response = await fetch('./', { method: 'POST', body: formData, headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' } })
    const result = await response.json()
    if (!response.ok || !(result.ok || result.success)) throw new Error(result.message || 'BuilderX could not queue the MySQL AI transaction.')
    const transactionKey = String(result.data?.transaction_key || '')
    if (transactionKey === '') throw new Error('BuilderX queued the AI transaction without returning its key.')
    return transactionKey
  }

  async function beginCoordinatorProcessReport(taskLabel: string, objective: string, mode: 'task' | 'smart-task' | 'test', transactionKey = ''): Promise<string> {
    const formData = new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', 'begin_phase_orchestration_report')
    formData.set('phase_key', selectedPhaseKey)
    formData.set('transaction_key', transactionKey)
    formData.set('mode', mode)
    formData.set('task_label', taskLabel)
    formData.set('objective', objective)
    formData.set('max_rounds', '3')
    const configuredSpecialistCount = mode === 'task'
      ? 1
      : Math.max(0, (phaseData?.settings?.parallelAgents || []).filter((agent: Record<string, any>) => agent.active !== false && String(agent.id || '') !== 'coordinator').length)
    formData.set('configured_specialist_count', String(configuredSpecialistCount))
    const response = await fetch('./', { method: 'POST', body: formData, headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' } })
    const result = await response.json()
    if (!response.ok || !(result.ok || result.success)) throw new Error(result.message || 'BuilderX could not start the coordinator process report.')
    const runKey = String(result.data?.run_key || '')
    if (runKey === '') throw new Error('BuilderX started the coordinator report without returning its key.')
    return runKey
  }

  async function completeCoordinatorProcessReport(runKey: string, result: Record<string, any>): Promise<Record<string, any> | null> {
    if (runKey === '') return null
    const formData = new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', 'complete_phase_orchestration_report')
    formData.set('run_key', runKey)
    formData.set('orchestration_result', JSON.stringify(result))
    const response = await fetch('./', { method: 'POST', body: formData, headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' } })
    const payload = await response.json()
    if (!response.ok || !(payload.ok || payload.success)) return null
    return payload.data?.report && typeof payload.data.report === 'object' ? payload.data.report : null
  }

  async function failCoordinatorProcessReport(runKey: string, reason: string, partialResult: Record<string, any> | null = null): Promise<void> {
    if (runKey === '') return
    const formData = new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', 'fail_phase_orchestration_report')
    formData.set('run_key', runKey)
    formData.set('failure_reason', reason)
    if (partialResult) formData.set('orchestration_result', JSON.stringify(partialResult))
    await fetch('./', { method: 'POST', body: formData, headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' } }).catch(() => undefined)
  }

  async function failMySqlAiTransaction(transactionKey: string, reason: string, bridgeRequestKey = ''): Promise<void> {
    if (transactionKey === '') return
    const formData = new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', 'fail_phase_codex_transaction')
    formData.set('transaction_key', transactionKey)
    formData.set('failure_reason', reason)
    formData.set('bridge_request_key', bridgeRequestKey)
    await fetch('./', { method: 'POST', body: formData, headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' } }).catch(() => undefined)
  }

  async function runHybridStageAction(item: { key: string; label: string; detail: string; memoryPurpose?: string; tab: string }) {
    if (hybridBusyStage !== '') return
    if (item.key !== 'narrative' && selectedPhaseKey.trim() === '') {
      const message = `Select an active phase before using ${item.label}.`
      setHybridNotice(message)
      setGrammarMessage(message)
      return
    }
    if (narrativeBridgeStatus !== 'ready') {
      const notice = narrativeBridgeStatus === 'needs-chat'
        ? 'Codex Chat is not ready. Open an active Codex Chat thread, then use Check bridge readiness.'
        : 'The Codex bridge is still preparing or unavailable. Check bridge readiness and try again.'
      setHybridNotice(notice)
      setGrammarMessage(notice)
      return
    }
    setHybridBusyStage(item.key)
    setHybridResult(null)
    setHybridNotice(`Preparing ${item.label}…`)
    setGrammarMessage(`Preparing ${item.label} with BuilderX memory…`)
    setActiveTab(item.tab as NarrativeGrammarScope)
    const stagePayload = item.key === 'narrative'
      ? { narrativeDraft: editorValue }
      : item.key === 'requirements'
        ? { requirementsAnalysis }
        : item.key === 'architecture'
          ? { architectureManifest }
          : { executionRoadmap }
    const formData = new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', 'prepare_narrative_hybrid_context')
    formData.set('phase_key', selectedPhaseKey)
    formData.set('stage', item.key)
    formData.set('stage_payload', JSON.stringify(stagePayload))
    formData.set('retrieval_query', `${item.label}. ${item.detail}\n${editorValue.slice(0, 12000)}`)
    let transactionKey = ''
    let orchestrationRunKey = ''
    try {
      const contextResponse = await fetch('./', { method: 'POST', body: formData, headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' } })
      const contextResult = await contextResponse.json()
      if (!(contextResult.ok || contextResult.success)) throw new Error(contextResult.message || 'BuilderX could not prepare hybrid memory context.')
      const hybrid = contextResult.data?.hybrid_context || {}
      const suppliedRequirementsSchema = hybrid.requirements_schema && typeof hybrid.requirements_schema === 'object'
        ? hybrid.requirements_schema
        : {}
      const requirementsSchema = JSON.stringify({
        ...requirementsAnalysisContractSchema(),
        ...suppliedRequirementsSchema,
        ...Object.fromEntries(requirementsAnalysisProductionCategories.map(({ key }) => [
          key,
          Array.isArray(suppliedRequirementsSchema[key]) ? suppliedRequirementsSchema[key] : requirementsAnalysisContractSchema()[key],
        ])),
      }, null, 2)
      const tabBlueprint = compactPromptSection(
        hybrid.tab_blueprint && typeof hybrid.tab_blueprint === 'object' ? hybrid.tab_blueprint : phaseData?.tabBlueprint || {},
        6000,
      )
      const reviewContractInstruction = item.key === 'requirements'
        ? `Return ONLY valid JSON matching this permanent, project-agnostic Requirements Analysis schema. Preserve every top-level key, keep IDs and sourceReferences stable, include every production-readiness category even when its array is empty, separate confirmed requirements from assumptions/open questions, and do not produce architecture, APIs, database migrations, or roadmap tasks. Treat architecture, migration, deployment, and rollback entries as verifiable product requirements and constraints only; do not design or execute them.\nCanonical schema:\n${requirementsSchema}`
        : 'Return ONLY valid JSON with correctedNarrativePreview, originalNarrativeSnapshot, saveReady, changeHistoryLog, preservedConstraints, ambiguities, openQuestions, and sourceReferences. This is Stage 1 only: do not produce requirements IDs, database tables, architecture, APIs, or roadmap tasks.'
      const prompt = [
        '# BuilderX Hybrid Memory Review',
        `Stage: ${item.label}`,
        item.detail,
        item.key === 'requirements' ? 'Convert the current narrative and retrieved memory into the canonical Requirements Analysis contract.' : 'Perform a bounded review using the supplied BuilderX memory/RAG context and current stage data.',
        'Do not open physical project files, do not ask for file permissions, and do not modify files or records for this review.',
        item.key === 'narrative' ? `This Tab 1 request is routed through the Smart Universal Coordinator. It selects only the required analyst(s), sends their evidence through independent checker and approval gates, and returns the exact contract after final verification. The ${narrativeSkillLabel} (${narrativeSkillId}) capability remains available for selection; do not assume every configured agent is called.` : '',
        item.key === 'narrative' ? '## Coordinator Workflow\nSmart Universal Coordinator selects only the required 1–3 analysts, then requires an independent checker, Coordinator approval, conditional code/database implementation, testing, final verification, and persistence/read-back.' : '',
        `## Permanent Tab 1 and Tab 2 Blueprint\n${tabBlueprint}`,
        reviewContractInstruction,
        item.key === 'narrative' ? 'For Narrative & Cleanup, correctedNarrativePreview must contain the complete corrected draft, and changeHistoryLog must be an array of objects with changeId, originalText, updatedText, category (Spelling, Grammar, or Punctuation), and reason.' : '',
        `## Current Narrative & Cleanup Draft\n--- BEGIN NARRATIVE DRAFT ---\n${editorValue}\n--- END NARRATIVE DRAFT ---`,
        item.key !== 'narrative' ? `## Current ${item.label} Data\n${compactPromptSection(stagePayload, 12000)}` : '',
        `## Retrieved BuilderX Memory/RAG Context\n${compactPromptSection(hybrid.context_text || '', 12000)}`,
      ].join('\n\n')
      transactionKey = await beginMySqlAiTransaction(item.key, 'hybrid_refine', prompt)
      const handoffData = new FormData()
      handoffData.set('csrf', phaseData?.csrf || '')
      handoffData.set('action', 'prepare_visual_codex_handoff')
      handoffData.set('handoff_mode', 'general')
      handoffData.set('builder_prompt', prompt)
      handoffData.set('annotation_snapshot', JSON.stringify({ source: 'narrative-stage-hybrid-action', stage: item.key, strategy: 'memory-rag', sources: hybrid.sources || [] }))
      const handoffResponse = await fetch('./', { method: 'POST', body: handoffData, headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' } })
      const handoffResult = await handoffResponse.json()
      if (!(handoffResult.ok || handoffResult.success)) throw new Error(handoffResult.message || 'BuilderX could not prepare the Codex Chat handoff.')
      const prepared = handoffResult.data?.visual_codex_handoff
      const handoff = codexHandoffFromPrepared(prepared, prompt)
      handoff.context = { ...handoff.context, mysql_transaction_key: transactionKey }
      await waitForNarrativeCodexIdle(item.label)
      let requestId = ''
      let reply = ''
      let coordinatorAgentTrace: Record<string, unknown> | null = null
      let orchestrationResult: Record<string, any> | null = null
      {
        orchestrationRunKey = await beginCoordinatorProcessReport(item.label, prompt, 'smart-task', transactionKey)
        setGrammarMessage(`Smart Universal Coordinator is analyzing ${item.label} and selecting only the required Tab 1 specialists…`)
        const coordinatorResponse = await fetch(`${visualCodexBridgeUrl}/orchestration-run`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
          body: JSON.stringify({
            workspace_root: phaseData?.projectRoot || '',
            parallel_agents: smartCoordinatorAgents,
            orchestration_mode: 'smart-task',
            task_level: item.key,
            task_label: item.label,
            transaction_key: transactionKey,
            orchestration_run_key: orchestrationRunKey,
            task_prompt: prompt,
          }),
        })
        const coordinatorResult = await coordinatorResponse.json()
        orchestrationResult = coordinatorResult && typeof coordinatorResult === 'object' ? coordinatorResult : null
        if (!(coordinatorResponse.ok && coordinatorResult?.ok === true)) {
          await failCoordinatorProcessReport(orchestrationRunKey, coordinatorResult?.message || `The Smart Universal Coordinator could not complete ${item.label}.`, coordinatorResult?.orchestration_report || null)
          throw new Error(coordinatorResult?.message || `The Smart Universal Coordinator could not complete ${item.label}.`)
        }
        requestId = typeof coordinatorResult?.request_id === 'string' ? coordinatorResult.request_id : ''
        reply = typeof coordinatorResult?.merged_response === 'string'
          ? coordinatorResult.merged_response.trim()
          : typeof coordinatorResult?.coordinator?.merge_response === 'string'
            ? coordinatorResult.coordinator.merge_response.trim()
            : ''
        if (requestId === '' || reply === '') throw new Error('The Coordinator response did not include a tracked specialist reply.')
        coordinatorAgentTrace = { request_id: requestId, coordinator: coordinatorResult.coordinator || null, specialists: coordinatorResult.specialists || [], merged_response: reply, task_level: item.key }
      }
      if (item.key === 'narrative') {
        const saveData = new FormData()
        saveData.set('csrf', phaseData?.csrf || '')
        saveData.set('action', 'save_phase_narrative_codex_reply')
        saveData.set('phase_key', selectedPhaseKey)
        saveData.set('transaction_key', transactionKey)
        saveData.set('narrative_draft', editorValue)
        saveData.set('codex_reply', reply)
        if (coordinatorAgentTrace) saveData.set('agent_trace', JSON.stringify(coordinatorAgentTrace))
        const saveResponse = await fetch('./', { method: 'POST', body: saveData, headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' } })
        const saveResult = await saveResponse.json()
        if (!(saveResult.ok || saveResult.success)) throw new Error(saveResult.message || 'BuilderX could not save the Narrative & Cleanup result.')
        const revision = saveResult.data?.narrative_revision || {}
        const corrected = String(saveResult.data?.narrative_draft || revision?.correctedNarrativePreview || '')
        if (corrected === '') throw new Error('BuilderX saved the Narrative & Cleanup response without returning the active draft.')
        if (corrected !== '') {
          setEditorValue(corrected)
          setSectionValues(parseNarrativeDraftSections(corrected))
          if (phaseData) phaseData.narrativeDraft = corrected
        }
        const changes = Array.isArray(revision.changeHistoryLog)
          ? revision.changeHistoryLog.filter((change: unknown) => change && typeof change === 'object') as Array<NarrativeCopyeditChange>
          : []
        setEditorChangesList(changes)
        setEditorCheckCompleted(true)
        setEditorRevisionSaved(revision.saveReady === true)
        setEditorPreviewValue(null)
        if (phaseData) phaseData.narrativeRevision = revision
        setGrammarRevision((revisionNumber) => revisionNumber + 1)
      } else if (item.key === 'requirements') {
        const saveData = new FormData()
        saveData.set('csrf', phaseData?.csrf || '')
        saveData.set('action', 'save_phase_codex_reply')
        saveData.set('phase_key', selectedPhaseKey)
        saveData.set('grammar_scope', 'phases')
        saveData.set('transaction_key', transactionKey)
        saveData.set('codex_reply', reply)
        const saveResponse = await fetch('./', { method: 'POST', body: saveData, headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' } })
        const saveResult = await saveResponse.json()
        if (!(saveResult.ok || saveResult.success)) throw new Error(saveResult.message || 'BuilderX could not save the Requirements Analysis contract.')
        const saved = saveResult.data?.requirements_analysis
        if (!saved || typeof saved !== 'object' || Array.isArray(saved)) throw new Error('BuilderX saved Requirements Analysis without returning the active contract.')
        setRequirementsAnalysis(saved)
        if (phaseData) phaseData.requirementsAnalysis = saved
      }
      if (orchestrationResult) {
        const report = await completeCoordinatorProcessReport(orchestrationRunKey, {
          ...orchestrationResult,
          persistence: {
            status: 'saved_and_read_back',
            phase_key: selectedPhaseKey,
            source_tab: item.label,
          },
        })
        if (report && phaseData) phaseData.orchestrationReports = [report, ...(phaseData.orchestrationReports || [])].slice(0, 10)
      }
      setHybridResult({ stage: item.key, label: item.label, text: reply, tokens: Number(hybrid.estimated_tokens || 0) })
      setHybridNotice(`${item.label} review completed, saved, and verified in the active draft.`)
      setGrammarMessage(`${item.label} review completed, saved, and verified in the active draft using ${Number(hybrid.estimated_tokens || 0).toLocaleString()} memory tokens.`)
    } catch (error) {
      const message = error instanceof Error ? error.message : `The ${item.label} hybrid action failed.`
      await failCoordinatorProcessReport(orchestrationRunKey, message)
      await failMySqlAiTransaction(transactionKey, message)
      setHybridNotice(message)
      setGrammarMessage(message)
    } finally {
      setHybridBusyStage('')
    }
  }

  async function runNarrativeCodexCheck(scope: NarrativeGrammarScope) {
    const scopeLabels: Record<NarrativeGrammarScope, string> = {
      editor: 'Narrative & Cleanup',
      phases: 'Requirements Analysis',
      flow: 'System Architecture & Build Manifest',
      build: 'Build Phases & Execution Roadmap',
    }
    const scopeLabel = scopeLabels[scope]
    if (scope !== 'editor' && selectedPhaseKey.trim() === '') {
      setGrammarMessage('Select an active phase before sending a Tab 1 Codex Chat request.')
      return
    }
    if (narrativeBridgeStatus !== 'ready') {
      setGrammarMessage(narrativeBridgeStatus === 'needs-chat' ? 'Open an active Codex Chat thread in VS Code before sending this request.' : 'The BuilderX Codex bridge is not ready. Check the bridge status above before sending this request.')
      return
    }
    const draft = editorValue.trim()
    const hasSelectedRequirement = Array.isArray(requirementsAnalysis?.functionalRequirements)
      && requirementsAnalysis.functionalRequirements.some((item: Record<string, any>) => item.isSelected !== false)
    const hasArchitecture = String(architectureManifest?.projectBlueprint?.title || '').trim() !== ''
    if (grammarBusyScope !== '' || draft === '' || (scope === 'flow' && !hasSelectedRequirement) || (scope === 'build' && !hasArchitecture)) return

    const architectureReplySchema = JSON.stringify({
      tab3ExecutionStatus: 'Success',
      projectBlueprint: {
        title: 'Technical blueprint title',
        summary: 'Architecture summary tied to the selected requirements',
        baseDirectory: phaseData?.projectRoot ? `${phaseData.projectRoot}/` : '/',
        architecturePattern: 'Existing BuilderX architecture pattern',
        payloadVariable: 'window.__BUILDERX_PHASE_DATA__',
      },
      systemInventory: {
        summary: 'Complete inventory summary',
        counts: { portals: 0, pages: 0, menus: 0, menuItems: 0, forms: 0, databaseTables: 0, webScreens: 0, androidScreens: 0 },
        portals: [{ name: 'Portal name', route: '/exact-route', audience: 'Authorized audience', description: 'Portal responsibility' }],
        pages: [{ name: 'Page or screen name', route: '/exact-route', portal: 'Owning portal', platform: 'Web', description: 'User-visible purpose' }],
        menus: [{ name: 'Menu name', portal: 'Owning portal', platform: 'Web', items: ['Visible menu item label'] }],
        forms: [{
          name: 'Form name', page: 'Owning page', dataEntity: 'Saved entity/table', platform: 'Web', description: 'Form purpose',
          fields: [{ name: 'field_name', label: 'Visible label', control: 'text', required: true, visibility: 'visible', description: 'Field purpose' }],
        }],
        databaseTables: [{
          name: 'table_name', purpose: 'Stored data responsibility',
          fields: [{ name: 'field_name', type: 'VARCHAR(255)', nullable: false, default: 'NULL or literal', key: 'NONE', description: 'Stored value purpose' }],
        }],
      },
      fileManifest: [{ path: 'project-relative file path', operation: 'Create', purpose: 'Exact responsibility', dependencies: ['project-relative dependency'] }],
      phpPageController: {
        targetPath: 'index.php or administrator/index.php',
        purpose: 'Controller responsibility',
        payloadVariable: 'window.__BUILDERX_PHASE_DATA__',
        code: 'Complete PHP controller source using foundation.php, bx_verify_csrf, and window.__BUILDERX_PHASE_DATA__',
      },
      databaseMigration: {
        targetPath: 'project-relative migration or foundation file',
        purpose: 'ADOdb schema responsibility',
        payloadVariable: '',
        code: 'Complete ADOdb-compatible PHP migration source containing CREATE TABLE and bx_db or ADOdb',
      },
      reactPayloadInterfaces: {
        targetPath: 'frontend/src/types/builderx-phase-data.ts',
        purpose: 'Type-safe BuilderX payload interfaces',
        payloadVariable: 'window.__BUILDERX_PHASE_DATA__',
        code: 'Complete TypeScript interface declarations including Window and __BUILDERX_PHASE_DATA__',
      },
      appIntegration: {
        targetPath: 'frontend/src/App.tsx',
        purpose: 'Conditional React feature integration',
        payloadVariable: 'window.__BUILDERX_PHASE_DATA__',
        code: 'Complete React integration snippet reading __BUILDERX_PHASE_DATA__ safely',
      },
      implementationChecklist: [{ checkId: 'ARCH-01', task: 'Sequential implementation or verification step', status: 'Pending' }],
      assumptionsOrRisks: [{ riskId: 'ARCH-RISK-01', issue: 'Unknown or unresolved project risk', mitigation: 'Safe decision or validation required' }],
    }, null, 2)

    const executionRoadmapReplySchema = JSON.stringify({
      schemaVersion: 'builderx.execution-roadmap.v3',
      contractType: 'builderx.execution-roadmap',
      source: { draftKey: 'current draft key', architectureHash: 'sha256 architecture hash' },
      phaseExecutionOverview: {
        projectTitle: 'Project title from the approved architecture, including Web + Android Kotlin Sync',
        strategy: 'Small, chronological implementation slices for Web, Android, and shared services',
      },
      phases: [{
        phaseId: 'PHASE-01',
        phaseTitle: 'Phase title',
        phaseDescription: 'Phase outcome and boundary',
        phaseType: 'vertical_slice',
        entryPoint: 'Entry condition',
        exitPoint: 'Exit condition',
        dependencies: [],
        status: 'Pending',
        systemFlow: [{ flowStepId: 'FLOW-01', order: 1, actor: 'User', from: 'Start', action: 'Open page', to: 'Registration page', nodeType: 'page', route: '/register', successState: 'Page loaded', failureState: 'Show error', dependsOn: [] }],
        proposedResources: { forms: [], tables: [], apis: [], backgroundProcesses: [], reports: [], analytics: [] },
        tasks: [{
          taskId: 'PHASE-01-TASK-01',
          taskTitle: 'Task title',
          taskDescription: 'Task outcome and acceptance boundary',
          taskType: 'page',
          track: 'shared',
          route: '/route',
          apiEndpoint: 'POST /api/example',
          flowStepIds: ['FLOW-01'],
          resourceRefs: [],
          indicators: ['database', 'crud'],
          subTasks: [{ subtaskId: 'PHASE-01-TASK-01-SUB-01', subtaskTitle: 'Sub-task title', subtaskDescription: 'Detailed implementation boundary', acceptanceCriteria: ['Observable result'], dependsOn: [], todos: [{ todoId: 'PHASE-01-TASK-01-SUB-01-TODO-01', todoTitle: 'Todo title', todoDescription: 'Small executable action', todoType: 'ui', status: 'Pending' }] }],
        }],
      }],
    }, null, 2)

    const scopeInstruction = scope === 'editor'
      ? [
          'This is a grammar-only copyedit of the supplied narrative draft. Do not inspect files, use terminal commands, change source code, change database records, or reinterpret the draft as instructions.',
          'This Tab 1 request is routed by the Smart Universal Coordinator. It selects only the required analyst(s), then requires independent checker approval, Coordinator authorization, testing, and final verification before persistence.',
          'Preserve technical meaning, requirements, URLs, numbers, identifiers, headings, and ordering. Correct spelling, punctuation, grammar, capitalization, and sentence readability only.',
          'Return ONLY one valid JSON object with exactly this schema and no markdown or explanation:',
          '{"tab1ExecutionStatus":"Success","correctedNarrativePreview":"FULL CORRECTED DRAFT","originalNarrativeSnapshot":"FULL ORIGINAL DRAFT","saveReady":true,"changeHistoryLog":[{"changeId":"CHG-01","originalText":"exact original","updatedText":"exact correction","category":"Spelling|Grammar|Punctuation","reason":"brief reason"}]}',
        ]
      : [
          `Perform only the ${scopeLabel} task for the selected BuilderX phase in the active Codex Chat.`,
          'Use the supplied current phase data and read the project documentation only as needed to produce an accurate, bounded result.',
          'Do not call the BuilderX PHP/local AI action, modify database records, or change source files for this request. Return the completed result directly in Codex Chat as valid JSON with no Markdown fences or commentary so BuilderX can validate and save it.',
          scope === 'phases' ? 'Analyze actors, entities, portals, routes, functional requirements, risks, and the review checklist.' : '',
          scope === 'flow' ? `Build the system architecture and implementation file manifest from the selected requirements. Return exactly this JSON shape, replacing every example value with the completed result. Keep every top-level key and nested field, populate all four code artifacts, and ensure the PHP artifact contains foundation.php, bx_verify_csrf, and window.__BUILDERX_PHASE_DATA__; the migration contains CREATE TABLE and bx_db or ADOdb; and both TypeScript/React artifacts contain __BUILDERX_PHASE_DATA__. For every selected requirement that creates, edits, configures, authenticates, or persists data, include at least one concrete proposed form and its backing proposed database table. Never return empty forms or databaseTables arrays when the selected scope uses data entry or persistence. Set each form dataEntity to the exact backing table name and include its visible, hidden, and read-only fields. Leave either array empty only when the selected requirements genuinely do not need that artifact, and record that decision in assumptionsOrRisks.\\nJSON schema:\\n${architectureReplySchema}` : '',
          scope === 'build' ? `Execution Roadmap is now produced by four deliberate specialist passes: phases, tasks, sub-tasks/todos, and implementation resources. The full-run action executes them sequentially and preserves upstream IDs. Do not generate a shallow broad plan. Describe page-by-page flows, forms, fields, APIs, proposed lower_snake_case tables, background processes, reports, analytics, permissions, states, and acceptance criteria. Return only valid JSON.\nFinal JSON schema:\n${executionRoadmapReplySchema}` : '',
        ].filter(Boolean)
    const currentScopeData = scope === 'phases'
      ? requirementsAnalysis
      : scope === 'flow'
        ? { requirementsAnalysis }
        : scope === 'build'
          ? { architectureManifest }
          : null
    const builderPrompt = [
      `# BuilderX ${scopeLabel} Codex Chat Request`,
      '',
      ...scopeInstruction,
      '',
      `Permanent Tab 1 and Tab 2 Blueprint with UX/UI contract:\n${compactPromptSection(phaseData?.tabBlueprint || {}, 7000)}`,
      '',
      `Narrative workspace: ${phaseField(selectedPhase, 'phase_code', 'DRAFT')} — ${phaseTitle}`,
      'Current Narrative & Cleanup draft:',
      '--- BEGIN NARRATIVE DRAFT ---',
      editorValue,
      '--- END NARRATIVE DRAFT ---',
      currentScopeData ? `${scopeLabel} data currently saved in BuilderX:\n${compactPromptSection(currentScopeData, 16000)}` : '',
    ].filter(Boolean).join('\n')
    const estimatedPromptTokens = Math.max(1, Math.ceil(builderPrompt.length / 4))
    const snapshot = {
      page_url: window.location.href,
      active_view: 'narrative-draft',
      phase_key: selectedPhaseKey,
      phase_code: phaseField(selectedPhase, 'phase_code'),
      phase_title: phaseTitle,
      grammar_scope: scope,
      delivery_target: 'vscode_active_codex_chat',
    }

    setActiveTab(scope)
    setGrammarBusyScope(scope)
    if (scope === 'editor') setEditorPreviewValue(null)
    setGrammarMessage(`Preparing ${scopeLabel} for Codex Chat (~${estimatedPromptTokens.toLocaleString()} tokens)…`)
    let transactionKey = ''
    let orchestrationRunKey = ''
    let coordinatorAgentTrace: Record<string, unknown> | null = null
    try {
      transactionKey = await beginMySqlAiTransaction(scope === 'editor' ? 'narrative' : scope, 'codex_chat_review', builderPrompt)
      orchestrationRunKey = await beginCoordinatorProcessReport(scopeLabel, builderPrompt, 'smart-task', transactionKey)
      const contextForm = new FormData()
      contextForm.set('action', 'prepare_visual_codex_handoff')
      contextForm.set('handoff_mode', 'general')
      contextForm.set('csrf', phaseData?.csrf || '')
      contextForm.set('builder_prompt', builderPrompt)
      contextForm.set('annotation_snapshot', JSON.stringify(snapshot))
      const contextResponse = await fetch('./', {
        method: 'POST',
        body: contextForm,
        headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' },
      })
      const contextResult = await contextResponse.json()
      if (!contextResponse.ok || contextResult?.ok !== true) throw new Error(contextResult?.message || 'BuilderX could not prepare the Codex Chat request.')
      const handoff = contextResult?.visual_codex_handoff ?? contextResult?.data?.visual_codex_handoff
      const ideCommand = typeof handoff?.ide_command === 'string' ? handoff.ide_command : ''
      if (ideCommand === '') throw new Error('BuilderX prepared the request but did not return the Codex Chat command.')

      let requestId = ''
      let codexReply = ''
      let orchestrationResult: Record<string, any> | null = null
      {
        setGrammarMessage(`Smart Universal Coordinator is analyzing ${scopeLabel} and selecting only the required Tab 1 specialists…`)
        const coordinatorResponse = await fetch(`${visualCodexBridgeUrl}/orchestration-run`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
          body: JSON.stringify({
            workspace_root: phaseData?.projectRoot || '',
            parallel_agents: smartCoordinatorAgents,
            orchestration_mode: 'smart-task',
            task_level: scope === 'editor' ? 'narrative' : scope,
            task_label: scopeLabel,
            transaction_key: transactionKey,
            orchestration_run_key: orchestrationRunKey,
            task_prompt: builderPrompt,
          }),
        })
        const coordinatorResult = await coordinatorResponse.json()
        orchestrationResult = coordinatorResult && typeof coordinatorResult === 'object' ? coordinatorResult : null
        if (!coordinatorResponse.ok || coordinatorResult?.ok !== true) {
          await failCoordinatorProcessReport(orchestrationRunKey, coordinatorResult?.message || `The Smart Universal Coordinator could not complete ${scopeLabel}.`, coordinatorResult?.orchestration_report || null)
          throw new Error(coordinatorResult?.message || `The Smart Universal Coordinator could not complete ${scopeLabel}.`)
        }
        coordinatorAgentTrace = {
          request_id: coordinatorResult?.request_id || '',
          coordinator: coordinatorResult?.coordinator || { role: 'Narrative Coordinator' },
          specialists: coordinatorResult?.specialists || [],
          merged_response: typeof coordinatorResult?.merged_response === 'string' ? coordinatorResult.merged_response : coordinatorResult?.coordinator?.merge_response || '',
        }
        requestId = typeof coordinatorResult?.request_id === 'string' ? coordinatorResult.request_id : ''
        codexReply = typeof coordinatorResult?.merged_response === 'string'
          ? coordinatorResult.merged_response.trim()
          : typeof coordinatorResult?.coordinator?.merge_response === 'string'
            ? coordinatorResult.coordinator.merge_response.trim()
            : ''
        if (requestId === '' || codexReply.trim() === '') throw new Error('The Coordinator completed routing without returning the specialist response.')
      }
      if (scope !== 'editor') {
        const saveForm = new FormData()
        saveForm.set('csrf', phaseData?.csrf || '')
        saveForm.set('action', 'save_phase_codex_reply')
        saveForm.set('phase_key', selectedPhaseKey)
        saveForm.set('grammar_scope', scope)
        saveForm.set('transaction_key', transactionKey)
        saveForm.set('codex_reply', codexReply)
        const saveResponse = await fetch('./', {
          method: 'POST',
          body: saveForm,
          headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' },
        })
        const saveResult = await saveResponse.json()
        if (!saveResponse.ok || !(saveResult.ok || saveResult.success)) {
          throw new Error(saveResult.message || `${scopeLabel} completed, but BuilderX could not save the result.`)
        }
        const savedData = saveResult.data || {}
        if (scope === 'phases' && savedData.requirements_analysis && typeof savedData.requirements_analysis === 'object') {
          setRequirementsAnalysis(savedData.requirements_analysis)
          if (phaseData) phaseData.requirementsAnalysis = savedData.requirements_analysis
        }
        if (scope === 'flow' && savedData.architecture_manifest && typeof savedData.architecture_manifest === 'object') {
          setArchitectureManifest(savedData.architecture_manifest)
          if (phaseData) phaseData.architectureManifest = savedData.architecture_manifest
        }
        if (scope === 'build' && savedData.execution_roadmap && typeof savedData.execution_roadmap === 'object') {
          setExecutionRoadmap(savedData.execution_roadmap)
          if (phaseData) phaseData.executionRoadmap = savedData.execution_roadmap
        }
        if (orchestrationResult) {
          const report = await completeCoordinatorProcessReport(orchestrationRunKey, {
            ...orchestrationResult,
            persistence: { status: 'saved_and_read_back', phase_key: selectedPhaseKey, source_tab: scopeLabel },
          })
          if (report && phaseData) phaseData.orchestrationReports = [report, ...(phaseData.orchestrationReports || [])].slice(0, 10)
        }
        playAiCompletionDing(requestId)
        setGrammarMessage(saveResult.message || `${scopeLabel} completed in Codex Chat and was saved to BuilderX.`)
        return
      }
      setGrammarMessage('Codex Chat returned the copyedit. Saving and verifying the active draft…')
      const saveForm = new FormData()
      saveForm.set('csrf', phaseData?.csrf || '')
      saveForm.set('action', 'save_phase_narrative_codex_reply')
      saveForm.set('phase_key', selectedPhaseKey)
      saveForm.set('transaction_key', transactionKey)
      saveForm.set('narrative_draft', editorValue)
      saveForm.set('codex_reply', codexReply)
      saveForm.set('agent_trace', scope === 'editor' ? JSON.stringify(coordinatorAgentTrace || {
        request_id: requestId,
        coordinator: { role: 'Narrative Coordinator' },
        specialist: { role: 'Narrative Documentation Specialist' },
      }) : '')
      const saveResponse = await fetch('./', {
        method: 'POST',
        body: saveForm,
        headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' },
      })
      const saveResult = await saveResponse.json()
      if (!saveResponse.ok || !(saveResult.ok || saveResult.success)) throw new Error(saveResult.message || 'BuilderX could not save the Codex copyedit preview.')
      const revision = saveResult.data?.narrative_revision || saveResult.data || {}
      const previewValue = String(revision.correctedNarrativePreview || '')
      if (previewValue === '') throw new Error('BuilderX received an empty corrected narrative preview.')
      const changes = Array.isArray(revision.changeHistoryLog) ? revision.changeHistoryLog.filter((change: unknown) => change && typeof change === 'object') as Array<NarrativeCopyeditChange> : []
      setEditorValue(previewValue)
      setSectionValues(parseNarrativeDraftSections(previewValue))
      setEditorPreviewValue(null)
      setEditorChangesList(changes)
      setEditorCheckCompleted(true)
      setEditorRevisionSaved(revision.saveReady === true)
      const currentPhaseData = phaseData
      if (currentPhaseData) {
        currentPhaseData.narrativeDraft = previewValue
        currentPhaseData.narrativeRevision = revision
      }
      playAiCompletionDing(requestId)
      const changedCount = changes.length
      if (orchestrationResult) {
        const report = await completeCoordinatorProcessReport(orchestrationRunKey, {
          ...orchestrationResult,
          persistence: {
            status: 'saved_and_read_back',
            phase_key: selectedPhaseKey,
            source_tab: 'Narrative & Cleanup',
            revision_key: String(revision?.revisionKey || ''),
            narrative_draft_hash: String(saveResult.data?.narrative_draft_hash || ''),
          },
        })
        if (report && phaseData) phaseData.orchestrationReports = [report, ...(phaseData.orchestrationReports || [])].slice(0, 10)
      }
      setGrammarMessage(`${saveResult.message || 'Narrative & Cleanup completed in Codex Chat and the corrected active draft was saved.'} ${changedCount} ${changedCount === 1 ? 'text item was' : 'text items were'} corrected.`)
      setGrammarRevision((revisionNumber) => revisionNumber + 1)
    } catch (error) {
      const message = error instanceof Error ? error.message : 'The Codex Chat copyedit could not be completed.'
      await failCoordinatorProcessReport(orchestrationRunKey, message)
      await failMySqlAiTransaction(transactionKey, message)
      setGrammarMessage(message)
    } finally {
      setGrammarBusyScope('')
    }
  }

  async function runRequirementsAnalysis() {
    await runNarrativeCodexCheck('phases')
  }

  async function runArchitectureManifest() {
    await runNarrativeCodexCheck('flow')
  }

  async function runExecutionRoadmap() {
    await runNarrativeCodexCheck('build')
  }

  async function updateExecutionRoadmapTask(phaseId: string, taskId: string, subtaskId: string, todoId: string, completed: boolean, legacyTrack = '', legacyIndex = -1) {
    const taskKey = legacyTrack !== '' ? `${phaseId}:${legacyTrack}:${legacyIndex}` : todoId !== '' ? `${phaseId}:${taskId}:${subtaskId}:${todoId}` : subtaskId !== '' ? `${phaseId}:${taskId}:${subtaskId}` : `${phaseId}:${taskId}`
    if (executionRoadmapBusyTask !== '') return
    const previousProgress = executionRoadmapProgress
    const optimisticProgress = { ...executionRoadmapProgress }
    if (completed) optimisticProgress[taskKey] = true
    else delete optimisticProgress[taskKey]
    setExecutionRoadmapProgress(optimisticProgress)
    setExecutionRoadmapBusyTask(taskKey)
    const formData = new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', 'update_phase_execution_roadmap_task')
    formData.set('phase_key', selectedPhaseKey)
    formData.set('roadmap_phase_id', phaseId)
    if (legacyTrack !== '') {
      formData.set('track', legacyTrack)
      formData.set('task_index', String(legacyIndex))
    } else {
      formData.set('task_id', taskId)
      if (subtaskId !== '') formData.set('subtask_id', subtaskId)
      if (todoId !== '') formData.set('todo_id', todoId)
    }
    formData.set('completed', completed ? 'true' : 'false')
    try {
      const response = await fetch('./', {
        method: 'POST',
        body: formData,
        headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' },
      })
      const result = await response.json()
      if (!(result.ok || result.success)) {
        setExecutionRoadmapProgress(previousProgress)
        setGrammarMessage(result.message || 'The roadmap task could not be updated.')
        return
      }
      const roadmap = result.data?.execution_roadmap
      const progress = result.data?.execution_roadmap_progress
      if (roadmap && typeof roadmap === 'object' && !Array.isArray(roadmap)) {
        setExecutionRoadmap(roadmap)
        if (phaseData) phaseData.executionRoadmap = roadmap
      }
      if (progress && typeof progress === 'object' && !Array.isArray(progress)) {
        setExecutionRoadmapProgress(progress)
        if (phaseData) phaseData.executionRoadmapProgress = progress
      }
      setGrammarMessage(`${phaseId} ${subtaskId !== '' ? 'sub-task' : 'task'} updated.`)
    } catch (error) {
      setExecutionRoadmapProgress(previousProgress)
      setGrammarMessage(error instanceof Error ? error.message : 'The roadmap task could not be updated.')
    } finally {
      setExecutionRoadmapBusyTask('')
    }
  }

  async function updateRequirementsChecklist(checkId: string, completed: boolean) {
    if (requirementsChecklistBusyId !== '') return
    const previous = requirementsAnalysis
    const optimistic = {
      ...requirementsAnalysis,
      reviewChecklist: (Array.isArray(requirementsAnalysis.reviewChecklist) ? requirementsAnalysis.reviewChecklist : []).map((item: Record<string, any>) => String(item.checkId) === checkId ? { ...item, status: completed ? 'Completed' : 'Pending' } : item),
    }
    setRequirementsAnalysis(optimistic)
    setRequirementsChecklistBusyId(checkId)
    const formData = new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', 'update_phase_requirements_checklist')
    formData.set('phase_key', selectedPhaseKey)
    formData.set('check_id', checkId)
    formData.set('status', completed ? 'Completed' : 'Pending')
    try {
      const response = await fetch('./', {
        method: 'POST',
        body: formData,
        headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' },
      })
      const result = await response.json()
      if (!(result.ok || result.success)) {
        setRequirementsAnalysis(previous)
        setGrammarMessage(result.message || 'The checklist item could not be updated.')
        return
      }
      const saved = result.data?.requirements_analysis
      if (saved && typeof saved === 'object' && !Array.isArray(saved)) {
        setRequirementsAnalysis(saved)
        if (phaseData) phaseData.requirementsAnalysis = saved
      }
      setGrammarMessage('Review checklist updated.')
    } catch (error) {
      setRequirementsAnalysis(previous)
      setGrammarMessage(error instanceof Error ? error.message : 'The checklist item could not be updated.')
    } finally {
      setRequirementsChecklistBusyId('')
    }
  }

  async function updateRequirementsSelection(itemType: 'actor' | 'entity' | 'requirement', itemId: string, selected: boolean) {
    if (requirementsSelectionBusyId !== '') return
    const collectionName = itemType === 'actor' ? 'actors' : itemType === 'entity' ? 'entities' : 'functionalRequirements'
    const idField = itemType === 'actor' ? 'actorId' : itemType === 'entity' ? 'entityId' : 'requirementId'
    const previous = requirementsAnalysis
    const optimistic = {
      ...requirementsAnalysis,
      [collectionName]: (Array.isArray(requirementsAnalysis[collectionName]) ? requirementsAnalysis[collectionName] : []).map((item: Record<string, any>) => String(item[idField]) === itemId ? { ...item, isSelected: selected } : item),
    }
    const busyId = `${itemType}:${itemId}`
    setRequirementsAnalysis(optimistic)
    setRequirementsSelectionBusyId(busyId)
    const formData = new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', 'update_phase_requirements_selection')
    formData.set('phase_key', selectedPhaseKey)
    formData.set('item_type', itemType)
    formData.set('item_id', itemId)
    formData.set('is_selected', selected ? 'true' : 'false')
    try {
      const response = await fetch('./', {
        method: 'POST',
        body: formData,
        headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' },
      })
      const result = await response.json()
      if (!(result.ok || result.success)) {
        setRequirementsAnalysis(previous)
        setGrammarMessage(result.message || 'The requirements selection could not be updated.')
        return
      }
      const saved = result.data?.requirements_analysis
      if (saved && typeof saved === 'object' && !Array.isArray(saved)) {
        setRequirementsAnalysis(saved)
        if (phaseData) phaseData.requirementsAnalysis = saved
      }
      setGrammarMessage(`${itemId} ${selected ? 'included in' : 'excluded from'} the approved project scope.`)
    } catch (error) {
      setRequirementsAnalysis(previous)
      setGrammarMessage(error instanceof Error ? error.message : 'The requirements selection could not be updated.')
    } finally {
      setRequirementsSelectionBusyId('')
    }
  }

  async function applyRequirementsGapToStory(gapId: string, instruction: string) {
    if (requirementsGapBusyId !== '') return
    setRequirementsGapBusyId(gapId)
    setGrammarMessage(`Applying ${gapId} to Narrative & Cleanup...`)
    const formData = new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', 'apply_phase_requirements_gap_to_story')
    formData.set('phase_key', selectedPhaseKey)
    formData.set('gap_id', gapId)
    formData.set('custom_instruction', instruction)
    formData.set('narrative_draft', displayedEditorValue)
    try {
      const response = await fetch('./', {
        method: 'POST',
        body: formData,
        headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' },
      })
      const result = await response.json()
      if (!(result.ok || result.success)) {
        setGrammarMessage(result.message || `${gapId} could not be applied to the story.`)
        return
      }
      const updatedNarrative = String(result.data?.narrative_draft || '')
      const updatedAnalysis = result.data?.requirements_analysis
      if (updatedNarrative !== '') {
        setEditorValue(updatedNarrative)
        setEditorPreviewValue(null)
        setSaveMessage(`${gapId} clarification saved to the story.`)
        if (phaseData) phaseData.narrativeDraft = updatedNarrative
      }
      if (updatedAnalysis && typeof updatedAnalysis === 'object' && !Array.isArray(updatedAnalysis)) {
        setRequirementsAnalysis(updatedAnalysis)
        if (phaseData) phaseData.requirementsAnalysis = updatedAnalysis
      }
      setGrammarMessage(result.message || `${gapId} was applied to Narrative & Cleanup.`)
    } catch (error) {
      setGrammarMessage(error instanceof Error ? error.message : `${gapId} could not be applied to the story.`)
    } finally {
      setRequirementsGapBusyId('')
    }
  }

  async function saveNarrativeDraft() {
    if (saveBusy) return
    const draftToSave = editorPreviewValue ?? composeNarrativeDraftSections(sectionValues)
    const savingCorrectedPreview = editorPreviewValue !== null
    const formData = new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', 'save_phase_narrative_draft')
    formData.set('phase_key', selectedPhaseKey)
    formData.set('narrative_draft', draftToSave)
    setSaveBusy(true)
    setSaveMessage('Saving draft...')
    try {
      const response = await fetch('./', {
        method: 'POST',
        body: formData,
        headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' },
      })
      const result = await response.json()
      if (!(result.ok || result.success)) {
        setSaveMessage(result.message || 'Draft save failed.')
        return
      }
      setEditorValue(draftToSave)
      setSectionValues(parseNarrativeDraftSections(draftToSave))
      if (phaseData) phaseData.narrativeDraft = draftToSave
      if (savingCorrectedPreview) {
        setEditorPreviewValue(null)
        setGrammarMessage('The corrected preview is now the saved draft. Its original snapshot and change history remain permanently logged.')
      }
      setSaveMessage(savingCorrectedPreview ? 'Corrected draft saved.' : 'Draft saved.')
    } catch (error) {
      setSaveMessage(error instanceof Error ? error.message : 'Draft save failed.')
    } finally {
      setSaveBusy(false)
    }
  }

  const narrativeStory = narrativeAiOutput.story && typeof narrativeAiOutput.story === 'object' ? narrativeAiOutput.story : null
  const systemFlowCandidate = narrativeAiOutput.system_flow && typeof narrativeAiOutput.system_flow === 'object' ? narrativeAiOutput.system_flow : null
  const systemFlow = systemFlowCandidate && Object.keys(systemFlowCandidate).length > 0 ? systemFlowCandidate : null
  const systemJourney = Array.isArray(systemFlow?.journey) ? systemFlow.journey : []
  const systemPages = Array.isArray(systemFlow?.pages) ? systemFlow.pages : []
  const systemMenus = Array.isArray(systemFlow?.menus) ? systemFlow.menus : []
  const systemDatabases = Array.isArray(systemFlow?.databases) ? systemFlow.databases : []
  const systemForms = Array.isArray(systemFlow?.forms) ? systemFlow.forms : []
  const buildPhases = Array.isArray(systemFlow?.build_phases) ? systemFlow.build_phases : []
  const aiPhaseRows = Array.isArray(narrativeAiOutput.phases) ? narrativeAiOutput.phases.map((phase: Record<string, any>, index: number) => ({
    code: `PHASE-${index + 1}`,
    title: String(phase.title || `Phase ${index + 1}`),
    status: 'DRAFT',
    details: String(phase.narrative || 'No phase story saved.'),
    checklist: [],
    notes: [],
    subphases: Array.isArray(phase.subphases) ? phase.subphases : [],
  })) : []
  const phaseRows = aiPhaseRows.length > 0 ? aiPhaseRows : tasks.map((task) => ({
    code: phaseField(task, 'task_code', 'Task'),
    title: phaseField(task, 'task_title', 'Untitled task'),
    status: phaseField(task, 'task_status', phaseField(task, 'status', 'PENDING')),
    details: phaseField(task, 'task_details', phaseField(task, 'task_scope', 'No task details saved.')),
    checklist: Array.isArray(task.checklist) ? task.checklist : [],
    notes: Array.isArray(task.notes) ? task.notes : [],
    subphases: [],
  }))
  const draftFlowRows = Array.isArray(narrativeAiOutput.flow) && narrativeAiOutput.flow.length > 0
    ? narrativeAiOutput.flow.map((item: Record<string, any>, index: number) => ({
      code: `FLOW-${index + 1}`,
      title: String(item.phase_title || `Phase ${index + 1}`),
      status: 'DRAFT',
      details: String(item.narrative || 'No transition story saved.'),
      checklist: [],
      notes: [],
      subphaseTitles: Array.isArray(item.subphase_titles) ? item.subphase_titles.map((title: unknown) => String(title)) : [],
    }))
    : phaseRows.map((row) => ({ ...row, subphaseTitles: row.subphases.map((subphase: Record<string, any>) => String(subphase.title || 'Subphase')) }))
  const displayedEditorValue = editorPreviewValue ?? editorValue

  const aiConfirmationDetails: Record<NarrativeGrammarScope, { tab: string; title: string; description: string }> = {
    editor: {
      tab: 'Narrative & Cleanup',
      title: 'Run Narrative & Cleanup AI?',
      description: 'BuilderX will send the bounded Narrative & Cleanup request to Codex Chat, then save the validated reply to BuilderX.',
    },
    phases: {
      tab: 'Requirements Analysis',
      title: 'Run Requirements Analysis AI?',
      description: 'BuilderX will send Requirements Analysis to Codex Chat, then save the validated JSON reply to the selected phase.',
    },
    flow: {
      tab: 'System Architecture & Build Manifest',
      title: 'Run System Architecture AI?',
      description: 'BuilderX will send the architecture request to Codex Chat, then save the validated JSON manifest to this tab.',
    },
    build: {
      tab: 'Build Phases & Execution Roadmap',
      title: 'Run Execution Roadmap AI?',
      description: 'BuilderX will send the execution roadmap request to Codex Chat, then save the validated JSON reply to this tab.',
    },
  }

  function confirmTabAiAction() {
    const scope = aiConfirmationScope
    if (!scope) return
    setAiConfirmationScope(null)
    armAiCompletionDing()
    if (scope === 'phases') void runRequirementsAnalysis()
    else if (scope === 'flow') void runArchitectureManifest()
    else if (scope === 'build') void runExecutionRoadmap()
    else void runNarrativeCodexCheck(scope)
  }

  const grammarTabControl = (scope: NarrativeGrammarScope, label: string, icon: React.ReactNode) => {
    return <TabsTrigger value={scope} className="flex-none">{icon}{label}</TabsTrigger>
  }

  const narrativeQuickJumpLink = (target: (typeof narrativeQuickJumpTargets)[number]) => (
    <a
      key={target.id}
      href={`#${target.id}`}
      className={buttonClassName({ variant: 'outline', size: 'sm' })}
      onClick={(event) => {
        if (scrollToNarrativeQuickJump(target.id)) event.preventDefault()
      }}
    >
      {target.label}
    </a>
  )

  const narrativeBridgeMissingParts = [
    narrativeBridgeHealth.code_ready === true ? '' : 'Codex Chat bridge',
    narrativeBridgeHealth.context_ready === true ? '' : 'workspace context',
    narrativeBridgeHealth.companion_extension_installed === true ? '' : 'VS Code companion extension',
    narrativeBridgeHealth.orchestration_extension_installed === true ? '' : 'AI agent orchestration extension',
  ].filter(Boolean)
  const narrativeBridgeStatusLabel = narrativeBridgeStatus === 'ready'
    ? 'Bridge Ready'
    : narrativeBridgeStatus === 'needs-chat'
      ? 'Open Codex Chat'
      : narrativeBridgeStatus === 'needs-setup'
        ? 'Bridge Needs Setup'
        : narrativeBridgeStatus === 'offline'
          ? 'Bridge Offline'
          : 'Checking Bridge'
  const narrativeBridgeStatusDetail = narrativeBridgeStatus === 'ready'
    ? narrativeBridgeHealth.active_thread_busy === true ? 'Codex, workspace context, companion extension, and AI agent orchestration are connected. Active Codex Chat is busy; new requests will wait.' : narrativeBridgeHealth.legacy_wrapper_available === true && narrativeBridgeHealth.direct_text_send_ready !== true ? 'Bridge is ready in legacy implementation-wrapper mode. Requests will include Codex’s implementation wrapper.' : 'Codex, workspace context, companion extension, AI agent orchestration, and active Codex Chat are ready.'
    : narrativeBridgeStatus === 'needs-chat'
      ? 'Bridge is online, but no active Codex Chat thread was detected in VS Code.'
      : narrativeBridgeStatus === 'needs-setup'
        ? `Bridge responded, but ${narrativeBridgeMissingParts.join(', ') || 'a required readiness check'} is unavailable.`
        : narrativeBridgeStatus === 'offline'
          ? 'No response from http://127.0.0.1:43127/health.'
          : 'Checking the local bridge readiness endpoint.'
  const narrativeBridgeStatusClass = narrativeBridgeStatus === 'ready'
    ? 'border-emerald-500/50 text-emerald-600 dark:text-emerald-300'
    : narrativeBridgeStatus === 'needs-chat'
      ? 'border-amber-500/50 text-amber-600 dark:text-amber-300'
      : narrativeBridgeStatus === 'offline' || narrativeBridgeStatus === 'needs-setup'
        ? 'border-destructive/50 text-destructive'
        : 'border-blue-500/50 text-blue-600 dark:text-blue-300'

  const stageStatus = (stage: 'narrative' | 'requirements' | 'architecture' | 'roadmap') => {
    if (stage === 'narrative') return editorValue.trim() !== ''
    if (stage === 'requirements') return String(requirementsAnalysis?.projectAnalysis?.title || '').trim() !== '' && Array.isArray(requirementsAnalysis?.functionalRequirements) && requirementsAnalysis.functionalRequirements.length > 0
    if (stage === 'architecture') return String(architectureManifest?.projectBlueprint?.title || '').trim() !== '' && Array.isArray(architectureManifest?.fileManifest) && architectureManifest.fileManifest.length > 0
    return Array.isArray(executionRoadmap?.phases) && executionRoadmap.phases.length > 0
  }

  const stageReadyForMemory = (stage: 'narrative' | 'requirements' | 'architecture' | 'roadmap') => selectedPhaseKey.trim() !== '' && (stage === 'requirements'
    ? editorValue.trim() !== ''
    : stage === 'architecture'
      ? stageStatus('requirements')
      : stage === 'roadmap'
        ? stageStatus('architecture')
        : stageStatus(stage))

  const stageActionLabel = (stage: 'narrative' | 'requirements' | 'architecture' | 'roadmap') => stage === 'narrative'
    ? 'Refine'
    : stage === 'requirements'
      ? 'Generate Requirements'
      : stage === 'architecture'
        ? 'Build Architecture'
        : 'Build Roadmap'

  const stageItems = [
    { key: 'narrative' as const, label: 'Narrative & Cleanup', detail: 'Review the story, correct grammar, confirm scope, and save the final narrative.', memoryPurpose: 'Correct and review the project narrative using MySQL project memory and optional phase RAG.', tab: 'editor' },
    { key: 'requirements' as const, label: 'Requirements Analysis', detail: 'Extract users, roles, entities, requirements, risks, and open questions. Review and select the requirements that belong in the project.', memoryPurpose: 'Extract and review requirements, actors, risks, and open questions from the narrative.', tab: 'phases' },
    { key: 'architecture' as const, label: 'System Architecture', detail: 'Define portals, routes, pages, menus, forms, database tables, security rules, APIs, files, and implementation responsibilities.', memoryPurpose: 'Turn approved requirements into an implementation-ready architecture and file plan.', tab: 'flow' },
    { key: 'roadmap' as const, label: 'Execution Roadmap', detail: 'Convert the approved architecture into chronological Web and Android milestones with checkable tasks, testing, and rollback steps.', memoryPurpose: 'Turn the approved architecture into ordered Web and Android milestones and tasks.', tab: 'build' },
  ]
  const tabBlueprint = phaseData?.tabBlueprint && typeof phaseData.tabBlueprint === 'object' ? phaseData.tabBlueprint : {}
  const blueprintStages = Array.isArray(tabBlueprint.sequence) ? tabBlueprint.sequence : []
  const blueprintUxUi = tabBlueprint.uxUi && typeof tabBlueprint.uxUi === 'object' && !Array.isArray(tabBlueprint.uxUi) ? tabBlueprint.uxUi : {}
  const blueprintSharedUxUi = ['sharedLayout', 'accessibility', 'responsive', 'visualLanguage']
    .map((key) => ({ key, value: blueprintUxUi[key] }))
    .filter((item) => narrativeBlueprintValueText(item.value) !== '')
  const narrativeCoordinatorProcess = React.useMemo(() => buildNarrativeCoordinatorProcessSchema(
    narrativeAgentName,
    narrativeSkillId,
    narrativeSkillLabel,
    Array.isArray(phaseData?.settings?.parallelAgents) ? phaseData.settings.parallelAgents : [],
    Array.isArray(phaseData?.settings?.parallelSkills) ? phaseData.settings.parallelSkills : [],
  ), [narrativeAgentName, narrativeSkillId, narrativeSkillLabel])

  return (
    <Card className="flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden border-border/80 shadow-sm">
      <div className="grid min-h-0 min-w-0 flex-1 grid-cols-1 gap-0 lg:grid-cols-[minmax(0,1fr)_280px]">
      <Tabs value={activeTab} onValueChange={(value) => setActiveTab(value as NarrativeGrammarScope)} className="flex min-h-0 min-w-0 flex-col gap-0">
        <div className="flex shrink-0 flex-wrap items-center gap-2 border-b px-4 py-1">
          <TabsList className="flex h-auto min-w-0 flex-1 flex-wrap justify-start">
            {grammarTabControl('editor', 'Narrative & Cleanup', <Pencil />)}
            {grammarTabControl('phases', 'Requirements Analysis', <ClipboardList />)}
            {grammarTabControl('flow', 'System Architecture & Build Manifest', <Workflow />)}
            {grammarTabControl('build', 'Build Phases & Execution Roadmap', <TerminalSquare />)}
          </TabsList>
          <div className="flex shrink-0 items-center gap-0 border-l border-border pl-2" role="status" aria-live="polite">
            <Tooltip>
              <TooltipTrigger
                render={(
                  <Button
                    type="button"
                    variant="outline"
                    size="icon-xs"
                    className={cn('rounded-md', narrativeBridgeStatusClass)}
                    aria-label="Reconnect Codex and all AI agents"
                    title={`${narrativeBridgeStatusLabel}: ${narrativeBridgeStatusDetail}. Reload VS Code and reconnect Codex and all AI agents.`}
                    onClick={() => void reconnectNarrativeBridge()}
                    disabled={narrativeBridgeRestartBusy || narrativeBridgeCheckBusy}
                  />
                )}
              >
                {narrativeBridgeRestartBusy || narrativeBridgeStatus === 'checking' ? <LoaderCircle className="animate-spin" /> : <RotateCcw />}
              </TooltipTrigger>
              <TooltipContent>{narrativeBridgeStatusLabel}: {narrativeBridgeStatusDetail}. Reconnect Codex and all AI agents.</TooltipContent>
            </Tooltip>
            <span className="sr-only">{narrativeBridgeStatusLabel}. {narrativeBridgeStatusDetail}</span>
          </div>
        </div>
        {grammarMessage ? <div role="status" aria-live="polite" className="shrink-0 border-b bg-muted/30 px-4 py-2 text-xs text-muted-foreground">{grammarMessage}</div> : null}
        {phaseData?.aiTransaction?.status === 'FAILED' ? <div role="alert" aria-live="assertive" className="shrink-0 border-b border-destructive/30 bg-destructive/5 px-4 py-2 text-xs text-destructive">Last MySQL AI transaction failed: {String(phaseData.aiTransaction.failure_reason || 'Unknown failure reason.')}</div> : null}
        <div className="min-h-0 min-w-0 flex-1 overflow-hidden">
        <TabsContent value="editor" data-narrative-scroll-container="true" className="m-0 h-full min-h-0 overflow-y-auto p-4">
          <div className="grid min-w-0 gap-5">
            <section id="narrative-overview" tabIndex={-1} className="scroll-mt-24 rounded-lg bg-gradient-to-br from-sky-500/10 via-background to-background p-4 sm:p-5">
              <div className="flex flex-wrap items-start justify-between gap-3">
                <div className="min-w-0 max-w-4xl">
                  <p className="text-xs font-semibold uppercase tracking-wider text-sky-700 dark:text-sky-300">Narrative &amp; Cleanup</p>
                  <h2 className="mt-1 break-words text-xl font-semibold tracking-tight">{phaseTitle}</h2>
                  <p className="mt-2 text-sm leading-6 text-muted-foreground">{phaseSummary}</p>
                </div>
                <div className="flex flex-wrap items-center gap-2">
                  <Badge variant="outline">Stage 1 / 4</Badge>
                  <Badge variant="outline" className="border-sky-500/40 text-sky-700 dark:text-sky-300">Coordinator → {narrativeAgentName}</Badge>
                  {editorRevisionSaved ? <Badge className="bg-emerald-600 text-white hover:bg-emerald-600"><CheckCircle2 />Saved</Badge> : <Badge variant="outline">Draft</Badge>}
                  {editorCheckCompleted ? <Badge variant="outline" className="border-violet-500/30 text-violet-700 dark:text-violet-300">Reviewed</Badge> : null}
                  <Badge variant="outline">{displayedEditorValue.length.toLocaleString()} Characters</Badge>
                </div>
              </div>
            </section>

            <nav aria-label="Narrative quick jumps" className="sticky -top-4 z-20 flex self-start flex-wrap items-center gap-2 rounded-lg bg-background/95 p-3 shadow-sm backdrop-blur supports-[backdrop-filter]:bg-background/85"><span className="mr-1 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">Quick jump</span>{narrativeQuickJumpTargets.map(narrativeQuickJumpLink)}<Button type="button" variant="outline" size="sm" onClick={() => { setDraftGuideCopyMessage(''); setDraftGuideOpen(true) }} title="Open the Long draft guide"><BookOpen data-icon="inline-start" />Draft Guide</Button></nav>

            <div id="narrative-editor-scroll-region" className="grid min-w-0 gap-4" aria-label="Narrative draft sections">
              {editorPreviewValue !== null ? <section role="note" className="scroll-mt-24 rounded-lg bg-sky-500/5 p-4"><div className="flex flex-wrap items-center justify-between gap-2"><span className="flex items-center gap-2 text-sm font-medium text-sky-700 dark:text-sky-200"><Eye className="size-4" />Corrected preview</span><Button type="button" variant="outline" size="sm" onClick={() => { setEditorPreviewValue(null); setGrammarMessage('Preview closed. The original draft remains unchanged; the latest correction history remains visible below.') }}><RotateCcw />Return to Original</Button></div><p className="mt-1 text-xs text-muted-foreground">The raw draft is unchanged{editorRevisionSaved ? ' and this revision is permanently logged.' : '.'}</p><Textarea id="narrative-editor" value={displayedEditorValue} readOnly disabled={saveBusy} className="mt-3 min-h-64 max-h-[70vh] resize-y overflow-y-auto border-sky-500/30 bg-background font-mono text-sm leading-6" aria-label="Corrected narrative preview" /></section> : null}
              {editorPreviewValue === null ? narrativeDraftSections.map((section) => { const sectionSlug = narrativeSectionSlug(section); return <section id={`narrative-section-group-${sectionSlug}`} tabIndex={-1} key={section} className="scroll-mt-24 rounded-lg p-4"><div className="flex flex-wrap items-center justify-between gap-2"><div><h2 className="flex items-center gap-2 font-semibold"><FileText className="size-4 text-sky-600 dark:text-sky-300" />{section}</h2><p className="mt-1 text-xs text-muted-foreground">Edit the approved source narrative for this section.</p></div><Badge variant="outline">{sectionValues[section].length.toLocaleString()} Characters</Badge></div><Label htmlFor={`narrative-section-${sectionSlug}`} className="sr-only">{section}</Label><Textarea id={`narrative-section-${sectionSlug}`} value={sectionValues[section]} onChange={(event) => { const next = { ...sectionValues, [section]: event.target.value }; setSectionValues(next); setEditorValue(composeNarrativeDraftSections(next)); setSaveMessage('') }} disabled={saveBusy} className="mt-3 min-h-28 resize-y bg-muted/20 font-mono text-sm leading-6" placeholder={`Write ${section.toLowerCase()} here...`} /></section> }) : null}
              <section id="narrative-change-log" tabIndex={-1} aria-labelledby="narrative-change-log-title" className="scroll-mt-24 rounded-lg p-4"><div className="flex flex-wrap items-center justify-between gap-2"><div><h2 id="narrative-change-log-title" className="flex items-center gap-2 font-semibold"><Database className="size-4 text-violet-600 dark:text-violet-300" />Change History Log</h2><p className="mt-1 text-xs text-muted-foreground">Corrections returned by the Narrative &amp; Cleanup review.</p></div><div className="flex items-center gap-2">{editorRevisionSaved ? <Badge className="bg-emerald-600 text-white hover:bg-emerald-600"><Database />Saved</Badge> : grammarBusyScope === 'editor' ? <Badge variant="secondary">Running</Badge> : !editorCheckCompleted ? <Badge variant="secondary">Not run yet</Badge> : null}<Badge variant="outline">{editorChangesList.length} {editorChangesList.length === 1 ? 'Change' : 'Changes'}</Badge></div></div>{editorChangesList.length === 0 ? <p className="mt-3 flex items-center gap-2 rounded-md bg-muted/20 p-3 text-xs text-muted-foreground"><CheckCircle2 className={cn('size-4', editorCheckCompleted ? 'text-emerald-600 dark:text-emerald-300' : 'text-muted-foreground')} />{grammarBusyScope === 'editor' ? 'Narrative & Cleanup AI is running and will update this history when complete.' : editorCheckCompleted ? 'No spelling, grammar, or punctuation corrections were needed.' : 'Run the Narrative & Cleanup AI to generate an itemized correction history.'}</p> : <ol className="mt-3 grid gap-2">{editorChangesList.map((change, index) => <li key={change.changeId || `CHG-${index + 1}`} className="rounded-md bg-muted/20 p-3"><div className="flex flex-wrap items-center gap-2 text-xs"><Badge variant="secondary">{change.category}</Badge><span className="font-mono text-[10px] text-muted-foreground">{change.changeId || `CHG-${String(index + 1).padStart(2, '0')}`}</span><del className="break-words text-muted-foreground decoration-destructive/70">{change.originalText}</del><ChevronRight className="size-3.5 shrink-0 text-muted-foreground" aria-hidden="true" /><ins className="break-words font-medium text-foreground no-underline">{change.updatedText}</ins></div><p className="mt-1 text-xs leading-5 text-muted-foreground">{change.reason}</p></li>)}</ol>}</section>
            </div>
            <div id="narrative-draft-actions" className="sticky bottom-0 z-20 flex shrink-0 flex-wrap items-center justify-between gap-3 border-t bg-background/95 px-1 pt-3 pb-1 backdrop-blur"><span className="text-xs text-muted-foreground">{displayedEditorValue.length.toLocaleString()} characters{editorPreviewValue !== null ? ' · corrected preview ready to save' : ''}</span><div className="flex flex-wrap items-center gap-2"><span className="text-xs text-muted-foreground">{saveMessage}</span><Button type="button" variant="outline" onClick={() => navigator.clipboard?.writeText(displayedEditorValue)} disabled={displayedEditorValue === ''}><Copy />{editorPreviewValue !== null ? 'Copy Preview' : 'Copy Draft'}</Button><Button type="button" title={editorPreviewValue !== null ? 'Save the corrected preview as the active draft' : 'Save draft'} onClick={() => void saveNarrativeDraft()} disabled={saveBusy}>{saveBusy ? <LoaderCircle className="animate-spin" /> : <Save />}{saveBusy ? 'Saving' : editorPreviewValue !== null ? 'Save Corrected Draft' : 'Save Draft'}</Button></div></div>
          </div>
        </TabsContent>
        <TabsContent value="phases" className="m-0 h-full min-h-0 overflow-y-auto p-4">
          <RequirementsAnalysisTab analysis={requirementsAnalysis} checklistBusyId={requirementsChecklistBusyId} selectionBusyId={requirementsSelectionBusyId} gapBusyId={requirementsGapBusyId} onChecklistChange={(checkId, completed) => void updateRequirementsChecklist(checkId, completed)} onSelectionChange={(itemType, itemId, selected) => void updateRequirementsSelection(itemType, itemId, selected)} onApplyGap={(gapId, instruction) => void applyRequirementsGapToStory(gapId, instruction)} />
        </TabsContent>
        <TabsContent value="build" className="m-0 h-full min-h-0 overflow-y-auto p-4">
<ExecutionRoadmapTab phaseKey={selectedPhaseKey} roadmap={executionRoadmap} progress={executionRoadmapProgress} busyTaskKey={executionRoadmapBusyTask} onTaskChange={(phaseId, taskId, subtaskId, todoId, completed, legacyTrack, legacyIndex) => void updateExecutionRoadmapTask(phaseId, taskId, subtaskId, todoId, completed, legacyTrack, legacyIndex)} />
        </TabsContent>
        <TabsContent value="flow" className="m-0 h-full min-h-0 overflow-y-auto p-4">
          <ArchitectureManifestTab manifest={architectureManifest} />
          <div className="hidden" aria-hidden="true">
          {systemFlow && buildPhases.length > 0 ? <section className="mb-4 border-b pb-4"><div className="flex flex-wrap items-center justify-between gap-2"><p className="text-xs font-semibold uppercase text-muted-foreground">Step-by-step Build Phases</p><Badge variant="outline">{buildPhases.length} Steps</Badge></div><p className="mt-2 text-sm text-muted-foreground">Each phase is planned as an independently reviewable unit. Only explicit prerequisites block a step.</p><div className="mt-3 grid gap-0">{buildPhases.map((phase: Record<string, any>, index: number) => <div key={`build-phase-${index}`} className="border-b py-4 last:border-b-0"><div className="flex flex-wrap items-start justify-between gap-2"><div className="flex min-w-0 gap-3"><span className="grid size-7 shrink-0 place-items-center rounded-full border text-xs">{Number(phase.step || index + 1)}</span><div className="min-w-0"><p className="font-medium">{String(phase.title || `Build Phase ${index + 1}`)}</p><p className="mt-1 text-sm text-muted-foreground">{String(phase.goal || '')}</p></div></div><Badge variant="outline">Build Step {Number(phase.step || index + 1)}</Badge></div>{Array.isArray(phase.scope) && phase.scope.length > 0 ? <p className="mt-2 text-xs text-muted-foreground">Scope: {phase.scope.map((item: unknown) => String(item)).join(' · ')}</p> : null}{Array.isArray(phase.prerequisites) && phase.prerequisites.length > 0 ? <p className="mt-2 text-xs text-amber-600 dark:text-amber-300">Prerequisites: {phase.prerequisites.map((item: unknown) => String(item)).join(' · ')}</p> : <p className="mt-2 text-xs text-emerald-600 dark:text-emerald-300">No blocking prerequisite beyond the shared project brief.</p>}{Array.isArray(phase.outputs) && phase.outputs.length > 0 ? <p className="mt-2 text-xs text-muted-foreground">Output: {phase.outputs.map((item: unknown) => String(item)).join(' · ')}</p> : null}<p className="mt-2 text-xs text-muted-foreground">{String(phase.independence_note || '')}</p></div>)}</div></section> : null}
          {systemFlow ? <div className="grid min-w-0 gap-0"><section className="border-b pb-4"><p className="text-xs uppercase tracking-wider text-muted-foreground">System Flow</p><h2 className="mt-1 text-base font-semibold">Pages, menus, data, and forms</h2><p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-muted-foreground">{String(systemFlow.overview || 'System flow generated from the project prompt.')}</p></section>{systemJourney.length > 0 ? <section className="border-b py-4"><p className="text-xs font-semibold uppercase text-muted-foreground">User Journey</p><div className="mt-3 grid gap-3">{systemJourney.map((step: Record<string, any>, index: number) => <div key={`journey-${index}`} className="flex min-w-0 gap-3"><span className="grid size-6 shrink-0 place-items-center rounded-full border text-xs">{index + 1}</span><div className="min-w-0"><p className="font-medium">{String(step.title || `Step ${index + 1}`)}</p><p className="text-sm text-muted-foreground">{String(step.description || '')}</p>{step.next ? <p className="mt-1 text-xs text-muted-foreground">Next: {String(step.next)}</p> : null}</div></div>)}</div></section> : null}{systemPages.length > 0 ? <section className="border-b py-4"><p className="text-xs font-semibold uppercase text-muted-foreground">Pages / Screens</p><div className="mt-3 grid gap-3">{systemPages.map((page: Record<string, any>, index: number) => <div key={`page-${index}`} className="border-b pb-3 last:border-b-0"><div className="flex flex-wrap items-center justify-between gap-2"><p className="font-medium">{String(page.name || `Page ${index + 1}`)}</p><Badge variant="outline">{String(page.menu || 'Unassigned menu')}</Badge></div><p className="mt-1 text-sm text-muted-foreground">{String(page.purpose || '')}</p>{Array.isArray(page.actions) && page.actions.length > 0 ? <p className="mt-2 text-xs text-muted-foreground">Actions: {page.actions.map((action: unknown) => String(action)).join(' · ')}</p> : null}</div>)}</div></section> : null}{systemMenus.length > 0 ? <section className="border-b py-4"><p className="text-xs font-semibold uppercase text-muted-foreground">Navigation Menus</p><div className="mt-3 grid gap-3">{systemMenus.map((menu: Record<string, any>, index: number) => <div key={`menu-${index}`}><p className="font-medium">{String(menu.name || `Menu ${index + 1}`)}</p><p className="mt-1 text-sm text-muted-foreground">{Array.isArray(menu.items) ? menu.items.map((item: unknown) => narrativeFlowMenuItemText(item)).join(' · ') : ''}</p></div>)}</div></section> : null}{systemDatabases.length > 0 ? <section className="border-b py-4"><p className="text-xs font-semibold uppercase text-muted-foreground">Database and Tables</p><div className="mt-3 grid gap-4">{systemDatabases.map((database: Record<string, any>, databaseIndex: number) => <div key={`database-${databaseIndex}`}><p className="font-medium">{String(database.name || `Database ${databaseIndex + 1}`)}</p><p className="mt-1 text-sm text-muted-foreground">{String(database.purpose || '')}</p><div className="mt-2 grid gap-3 border-l pl-3">{(Array.isArray(database.tables) ? database.tables : []).map((table: Record<string, any>, tableIndex: number) => <div key={`table-${databaseIndex}-${tableIndex}`}><p className="text-sm font-medium">{String(table.name || `Table ${tableIndex + 1}`)}</p><p className="text-xs text-muted-foreground">{String(table.purpose || '')}</p>{Array.isArray(table.fields) && table.fields.length > 0 ? <p className="mt-1 font-mono text-xs text-muted-foreground">Fields: {table.fields.map((field: unknown) => narrativeFlowFieldText(field)).join(' · ')}</p> : null}</div>)}</div></div>)}</div></section> : null}{systemForms.length > 0 ? <section className="py-4"><p className="text-xs font-semibold uppercase text-muted-foreground">Forms</p><div className="mt-3 grid gap-3">{systemForms.map((form: Record<string, any>, index: number) => <div key={`form-${index}`} className="border-b pb-3 last:border-b-0"><div className="flex flex-wrap items-center justify-between gap-2"><p className="font-medium">{String(form.name || `Form ${index + 1}`)}</p><Badge variant="outline">{String(form.page || 'Unassigned page')}</Badge></div><p className="mt-1 text-sm text-muted-foreground">{String(form.purpose || '')}</p><p className="mt-1 text-xs text-muted-foreground">Table: {String(form.table || 'Not assigned')}</p>{Array.isArray(form.fields) && form.fields.length > 0 ? <p className="mt-1 font-mono text-xs text-muted-foreground">Fields: {form.fields.map((field: unknown) => narrativeFlowFieldText(field)).join(' · ')}</p> : null}</div>)}</div></section> : null}</div> : <div className="grid min-w-0 gap-3"><div className="border-b pb-4"><p className="text-xs uppercase tracking-wider text-muted-foreground">Draft Flow</p><p className="mt-2 text-sm leading-6 text-muted-foreground">No generated system flow is saved. The current phase sequence is shown below.</p></div><div className="grid gap-0"><div className="border-b border-sky-500/40 py-4"><p className="text-xs uppercase text-sky-600 dark:text-sky-300">Beginning</p><p className="mt-1 font-semibold">{String(narrativeStory?.title || phaseTitle)}</p><p className="mt-1 text-sm text-muted-foreground">{String(narrativeStory?.summary || phaseSummary)}</p></div>{draftFlowRows.map((flow, index) => <React.Fragment key={`flow-${flow.code}-${index}`}><div className="mx-auto h-5 w-px bg-border" aria-hidden="true" /><div className="border-b py-4 last:border-b-0"><div className="flex flex-wrap items-center justify-between gap-2"><div><p className="font-mono text-xs text-sky-600 dark:text-sky-300">{flow.code}</p><p className="mt-1 font-semibold">{flow.title}</p></div><Badge variant="outline">{flow.status}</Badge></div><p className="mt-2 text-sm text-muted-foreground">{flow.details}</p>{flow.subphaseTitles.length > 0 ? <p className="mt-2 text-xs text-muted-foreground">Next: {flow.subphaseTitles.join(' · ')}</p> : null}</div></React.Fragment>)}</div></div>}
          </div>
        </TabsContent>
          </div>
      </Tabs>
      <aside aria-labelledby="narrative-stage-status-title" className="min-h-0 min-w-0 overflow-y-auto border-t px-4 pb-4 pt-4 lg:border-l lg:border-t-0 lg:pl-4 lg:pt-4">
        <div className="flex items-start justify-between gap-2"><div><h2 id="narrative-stage-status-title" className="font-semibold">Narrative Draft Manager</h2><p className="mt-1 text-xs leading-5 text-muted-foreground">Track each planning stage before moving to the next step.</p></div><Badge variant="outline">{stageItems.filter((item) => stageStatus(item.key)).length} / {stageItems.length}</Badge></div>
        {String(tabBlueprint.goal || '').trim() !== '' ? <details className="mt-4 rounded-md border border-sky-500/30 bg-sky-500/5 p-3"><summary className="cursor-pointer text-xs font-semibold text-sky-800 dark:text-sky-200">Permanent Tab 1 → Tab 2 blueprint</summary><p className="mt-2 text-xs leading-5 text-muted-foreground">{String(tabBlueprint.goal)}</p><div className="mt-3 grid gap-2">{blueprintStages.slice(0, 2).map((stage: Record<string, any>) => { const stageUxUi = stage.uxUi && typeof stage.uxUi === 'object' && !Array.isArray(stage.uxUi) ? stage.uxUi : {}; return <article key={String(stage.tabKey || stage.step)} className="border-l-2 border-sky-500/40 pl-3"><p className="text-xs font-semibold text-foreground">{String(stage.step || '')}. {String(stage.label || '')}</p><p className="mt-1 text-[11px] leading-4 text-muted-foreground">{String(stage.purpose || '')}</p><p className="mt-1 text-[11px] leading-4 text-sky-700 dark:text-sky-300">Output: {Array.isArray(stage.outputs) ? stage.outputs.slice(0, 4).map((item: unknown) => String(item)).join(' · ') : ''}</p>{narrativeBlueprintValueText(stageUxUi.layout) ? <p className="mt-2 text-[11px] leading-4 text-muted-foreground"><span className="font-medium text-foreground">UX/UI:</span> {narrativeBlueprintValueText(stageUxUi.layout)}</p> : null}{narrativeBlueprintValueText(stageUxUi.primaryActions) ? <p className="mt-1 text-[11px] leading-4 text-muted-foreground"><span className="font-medium text-foreground">Actions:</span> {narrativeBlueprintValueText(stageUxUi.primaryActions)}</p> : null}</article> })}</div>{blueprintSharedUxUi.length > 0 ? <div className="mt-3 border-t border-sky-500/20 pt-3"><p className="text-[11px] font-semibold text-sky-800 dark:text-sky-200">Shared UX / UI</p>{blueprintSharedUxUi.map(({ key, value }) => <p key={key} className="mt-1 text-[11px] leading-4 text-muted-foreground"><span className="font-medium text-foreground">{key.replace(/([A-Z])/g, ' $1')}:</span> {narrativeBlueprintValueText(value)}</p>)}</div> : null}<p className="mt-3 text-[11px] leading-4 text-amber-700 dark:text-amber-300">Tab 1 is protected source intent. Tab 2 structures it into stable, traceable requirements; assumptions and open questions stay separate.</p></details> : null}
        <ol className="mt-4 grid gap-3">
          {stageItems.map((item, index) => {
            const complete = stageStatus(item.key)
            const stageScope = item.key === 'architecture' ? 'flow' : item.key === 'roadmap' ? 'build' : ''
            const stageBusy = stageScope !== '' ? grammarBusyScope === stageScope : hybridBusyStage === item.key
            const stageAction = stageScope !== '' ? () => void runNarrativeCodexCheck(stageScope) : () => void runHybridStageAction(item)
            return <li key={item.key} className={cn('border-b py-3 last:border-b-0', complete && 'text-emerald-700 dark:text-emerald-300')}><div className="flex items-start gap-3"><span className={cn('grid size-6 shrink-0 place-items-center rounded-full border text-[11px]', complete && 'border-emerald-500 bg-emerald-500 text-white')}>{complete ? <CheckCircle2 className="size-4" /> : index + 1}</span><div className="min-w-0">{item.key === 'narrative' ? <button type="button" className="flex items-center gap-1 text-left text-sm font-medium text-foreground underline decoration-dotted underline-offset-4 hover:text-sky-700 dark:hover:text-sky-300" onClick={() => { setNarrativeProcessTab('process'); setNarrativeProcessOpen(true) }} title="Show the Tab 1 AI process"><Sparkles className="size-3.5 text-sky-600 dark:text-sky-300" />{item.label}</button> : <p className="text-sm font-medium text-foreground">{item.label}</p>}<p className="mt-1 text-xs leading-5 text-muted-foreground">{item.detail}</p><p className="mt-1 text-[11px] leading-4 text-sky-700 dark:text-sky-300"><span className="font-medium">Memory purpose:</span> {item.memoryPurpose}</p><div className="mt-2 flex flex-wrap items-center gap-2"><button type="button" className="text-xs font-medium text-sky-700 underline-offset-4 hover:underline dark:text-sky-300" onClick={() => setActiveTab(item.tab as NarrativeGrammarScope)}>Open stage</button><Button type="button" variant="outline" size="sm" className="h-7 px-2 text-[11px]" onClick={stageAction} disabled={hybridBusyStage !== '' || grammarBusyScope !== '' || (item.key !== 'narrative' && (!stageReadyForMemory(item.key) || narrativeBridgeStatus !== 'ready'))} aria-label={`${stageActionLabel(item.key)}: ${item.memoryPurpose}`} title={item.key === 'narrative' ? 'Send Narrative & Cleanup to Codex Chat.' : narrativeBridgeStatus !== 'ready' ? 'Bridge is not ready. Restart or check the bridge connection first.' : !stageReadyForMemory(item.key) ? item.key === 'requirements' ? 'Save a Narrative & Cleanup draft before generating requirements.' : item.key === 'architecture' ? 'Complete Requirements Analysis before building architecture.' : 'Complete System Architecture before building the roadmap.' : item.memoryPurpose}>{stageBusy ? <LoaderCircle className="animate-spin" /> : item.key === 'narrative' ? <RotateCcw /> : item.key === 'requirements' ? <ClipboardList /> : item.key === 'architecture' ? <Workflow /> : <TerminalSquare />}{stageActionLabel(item.key)}</Button></div></div></div></li>
          })}
        </ol>
        {hybridResult ? <section aria-live="polite" className="mt-4 border-t pt-3"><div className="flex items-center justify-between gap-2"><h3 className="text-sm font-semibold">{hybridResult.label} AI review</h3><Badge variant="outline">{hybridResult.tokens.toLocaleString()} memory tokens</Badge></div><p className="mt-2 max-h-72 overflow-y-auto whitespace-pre-wrap text-xs leading-5 text-muted-foreground">{hybridResult.text}</p></section> : null}
        {hybridNotice ? <p role="status" aria-live="polite" className="mt-3 border-y border-amber-500/40 py-2 text-xs leading-5 text-amber-700 dark:text-amber-300">{hybridNotice}</p> : null}
        <div className="mt-4 rounded-md bg-muted/40 p-3 text-xs leading-5 text-muted-foreground"><strong className="text-foreground">Next step:</strong> {stageStatus('narrative') && !stageStatus('requirements') ? 'Run Requirements Analysis.' : stageStatus('requirements') && !stageStatus('architecture') ? 'Run System Architecture & Build Manifest.' : stageStatus('architecture') && !stageStatus('roadmap') ? 'Run Build Phases & Execution Roadmap.' : stageStatus('roadmap') ? 'Review the complete contract, resolve open questions, then approve it before generating or changing source code.' : 'Write and save the Narrative & Cleanup draft.'}</div>
      </aside>
      </div>
      <Dialog open={narrativeProcessOpen} onOpenChange={setNarrativeProcessOpen}>
        <DialogContent showCloseButton={false} className={cn(dialogSizeClass('XL'), 'flex h-[calc(100dvh-2rem)] max-h-[calc(100dvh-2rem)] min-h-0 flex-col gap-0 overflow-hidden bg-popover p-0')}>
          <DialogHeader className="sticky top-0 z-30 shrink-0 overflow-hidden border-b bg-popover px-4 py-3 pr-12 shadow-sm sm:px-6 sm:py-3.5 sm:pr-14">
            <DialogClose render={<Button type="button" variant="ghost" size="icon-sm" className="absolute top-3 right-3 rounded-full border-0 bg-transparent p-0 text-muted-foreground shadow-none hover:bg-muted/60 hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring" aria-label="Close Narrative refinement backend flow" title="Close Narrative refinement backend flow" />}>
              <X />
            </DialogClose>
            <div className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1 overflow-hidden pr-1">
              <DialogTitle className="flex min-w-0 flex-1 items-center gap-2 truncate text-lg"><Workflow className="size-5 shrink-0 text-sky-600 dark:text-sky-300" /><span className="truncate">Narrative refinement backend flow</span></DialogTitle>
              <Badge variant="secondary" className="shrink-0">Gated execution</Badge>
              <Badge variant="outline" className="shrink-0">{narrativeCoordinatorProcess.steps.length} coordinator steps · {narrativeCoordinatorProcess.specialistCalls} analysis agents available</Badge>
            </div>
            <section aria-labelledby="narrative-process-route-title" className="mt-2 min-w-0 text-left">
              <div className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1">
                <p id="narrative-process-route-title" className="shrink-0 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">Request route</p>
                <ol className="flex min-w-0 flex-1 flex-nowrap items-center gap-1.5 overflow-x-auto pb-0 text-[11px]" aria-label="Narrative refinement process owners">
                {['Browser', 'PHP', 'MySQL RAG', 'PHP + MySQL', 'Bridge', 'Coordinator plan', 'Required analyst(s)', 'Checker', 'Coordinator approval', 'Code/DB writer if needed', 'Tester', 'Final Coordinator', 'PHP + MySQL read-back', 'Browser'].map((owner, index, owners) => <React.Fragment key={`${owner}-${index}`}><li className="shrink-0"><Badge variant={index === 0 || index === owners.length - 1 ? 'secondary' : 'outline'}>{owner}</Badge></li>{index < owners.length - 1 ? <li aria-hidden="true" className="shrink-0 text-muted-foreground">→</li> : null}</React.Fragment>)}
                </ol>
                <Badge variant="outline" className="shrink-0">Visible Codex Chat · coordinator route</Badge>
              </div>
            </section>
          </DialogHeader>
          <div className={cn('min-h-0 flex-1 bg-gradient-to-br from-sky-500/5 via-background to-violet-500/5', narrativeProcessTab === 'canvas' ? 'overflow-hidden' : 'overflow-y-auto')}>
            <div className={cn('grid gap-6 px-6 py-6', narrativeProcessTab === 'canvas' ? 'h-full min-h-0 grid-cols-1' : 'grid-cols-1 lg:grid-cols-[minmax(0,1fr)_15rem]')}>
              <main className={cn('min-w-0', narrativeProcessTab === 'canvas' ? 'flex min-h-0 flex-col' : 'space-y-5')} aria-label="Narrative refinement process">
                <Tabs value={narrativeProcessTab} onValueChange={(value) => setNarrativeProcessTab(value as 'canvas' | 'process')} className={cn('min-w-0', narrativeProcessTab === 'canvas' && 'flex min-h-0 flex-1 flex-col')}>
                  <TabsList className="sticky top-2 z-20 flex h-auto w-full shrink-0 flex-wrap justify-start gap-1 rounded-lg border bg-popover/95 p-1 shadow-sm backdrop-blur supports-[backdrop-filter]:bg-popover/85">
                    <TabsTrigger value="canvas" className="flex-1 justify-start sm:flex-none"><Workflow />Interactive process canvas</TabsTrigger>
                    <TabsTrigger value="process" className="flex-1 justify-start sm:flex-none"><Activity />Actual AI process: Refine to verified read-back</TabsTrigger>
                  </TabsList>
                  <TabsContent value="canvas" className="mt-4 flex min-h-0 min-w-0 flex-1 flex-col">
                    <NarrativeProcessCanvas process={narrativeCoordinatorProcess} />
                  </TabsContent>
                  <TabsContent value="process" className="mt-4 min-w-0">
                    <section aria-labelledby="narrative-process-stages-title">
                      <div className="mb-3 flex flex-wrap items-end justify-between gap-2">
                        <div>
                          <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Lifecycle</p>
                          <h2 id="narrative-process-stages-title" className="mt-1 text-base font-semibold">Actual AI process: Refine to verified read-back</h2>
                        </div>
                        <p className="text-xs text-muted-foreground">Failures stop before the prior draft is replaced.</p>
                      </div>
                      <ol className="grid gap-3">
                    {[
                      ['1. React browser action', 'The user clicks the visible Tab 1 Refine button. React runs runHybridStageAction(), captures editorValue, and sends prepare_narrative_hybrid_context for the project-level Narrative & Cleanup scope. A phase is optional.', MessageCircle, 'border-sky-500/40 bg-sky-500/5'],
                      ['2. PHP request validation', 'phases/index.php accepts the supported Tab 1 stage, validates the stage payload size, normalizes the retrieval query, and prepares bounded MySQL-backed context. It accepts either the project-level scope or an optional phase scope.', Settings, 'border-violet-500/40 bg-violet-500/5'],
                      ['3. Memory RAG retrieval', 'aiMemoryBuildTab1DatabaseContext() loads project-level MySQL context and bounded general RAG results, adding phase context only when one exists. The response includes context text, sources, estimated tokens, policy, the stage payload hash, and the Tab 1/Tab 2 blueprint.', BookOpen, 'border-indigo-500/40 bg-indigo-500/5'],
                      ['4. React AI prompt assembly', 'React combines the current narrative, stage data, permanent blueprint, and returned Memory RAG context. It requests only the Stage 1 JSON contract: correctedNarrativePreview, originalNarrativeSnapshot, saveReady, changeHistoryLog, preservedConstraints, ambiguities, openQuestions, and sourceReferences.', Pencil, 'border-cyan-500/40 bg-cyan-500/5'],
                      ['5. PHP handoff materialization', 'React sends the bounded handoff request. PHP writes the generated user context, applies the project AI configuration, removes stale visual-only context, and returns the handoff metadata.', Workflow, 'border-amber-500/40 bg-amber-500/5'],
                      ['6. Bridge readiness gate', 'React checks the local User IDE bridge for the launcher, an active AI Chat thread, the companion extension, and a non-busy active thread. If AI Chat is busy, the request waits; if AI Chat is unavailable, the lifecycle stops.', Activity, 'border-orange-500/40 bg-orange-500/5'],
                      ['7. Smart Coordinator planning and selection', `The Smart Universal Coordinator receives the bounded task, identifies the task level and execution mode, and selects only the required 1–3 analysis agents. It never dispatches the full catalog by default.`, Workflow, 'border-amber-500/40 bg-amber-500/5'],
                      ['8. Selected analysis agents', 'The selected analysts apply only their assigned skills and return scoped evidence through visible Codex Chat. They do not edit files, execute SQL, or modify local state during analysis.', Sparkles, 'border-lime-500/40 bg-lime-500/5'],
                      ['9. Independent contract and safety check', 'The Contract & Safety Checker validates scope, response contracts, permissions, risks, and acceptance checks. A failed checker gate stops the run before any implementation.', ShieldCheck, 'border-violet-500/40 bg-violet-500/5'],
                      ['10. Coordinator approval gate', 'The Coordinator reviews the checker and analyst evidence. It either approves a review-only result or authorizes exactly one Code Implementation Agent or Database Implementation Agent with an explicit scope.', Workflow, 'border-amber-500/40 bg-amber-500/5'],
                      ['11. Approved implementation owner', 'When execution_mode=implement, the authorized writer changes only the approved source files or applies a reversible, auditable database migration/transaction. Every changed path and database action must be reported.', TerminalSquare, 'border-orange-500/40 bg-orange-500/5'],
                      ['12. Independent testing', 'The Test & Validation Agent runs focused non-destructive checks, verifies the acceptance criteria, reports regressions, and must return release_ready=true. A failed test gate prevents completion.', TestTube2, 'border-lime-500/40 bg-lime-500/5'],
                      ['13. Final Coordinator verification', 'The Coordinator confirms checker approval, implementation evidence when required, tester success, and the exact Tab 1 JSON contract. Only then does it return the result for persistence.', CheckCircle2, 'border-amber-500/40 bg-amber-500/5'],
                      ['14. PHP JSON validation and persistence', 'The existing PHP save action validates the Coordinator result, writes the phase revision, and reads the database setting back. This is system persistence, not an unsupervised AI change.', Database, 'border-emerald-500/40 bg-emerald-500/5'],
                      ['15. React result hydration and terminal state', 'React applies only the verified server result, updates the editor and saved state, stores the orchestration report, and displays a terminal COMPLETED or FAILED outcome. The prior draft remains intact on failure.', CheckCircle2, 'border-emerald-500/40 bg-emerald-500/5'],
                      ['Failure gates', 'Bridge unavailable, no active Chat thread, invalid plan, checker rejection, missing approval, unauthorized writer, incomplete implementation evidence, tester failure, invalid JSON, persistence failure, or read-back mismatch stops the flow safely.', ShieldCheck, 'border-rose-500/40 bg-rose-500/5'],
                    ].map(([label, description, Icon, color], index, steps) => <li key={String(label)} className="relative"><article className={cn('flex items-start gap-3 rounded-lg border p-4 shadow-xs', String(color))}><span className="grid size-9 shrink-0 place-items-center rounded-full border bg-background text-xs font-semibold"><Icon className="size-4" /></span><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><p className="font-medium">{String(label)}</p>{String(label) === 'Failure gates' ? <Badge variant="outline" className="border-rose-500/40 text-rose-700 dark:text-rose-300">Stops safely</Badge> : null}</div><p className="mt-1 text-xs leading-5 text-muted-foreground">{String(description)}</p></div></article>{index < steps.length - 1 ? <div className="flex justify-center py-1" aria-hidden="true"><ChevronDown className="size-4 text-muted-foreground" /></div> : null}</li>)}
                      </ol>
                    </section>
                  </TabsContent>
                </Tabs>
              </main>
              <aside className={cn('min-w-0 space-y-3 lg:sticky lg:top-2 lg:self-start', narrativeProcessTab === 'canvas' && 'hidden')} aria-label="Narrative refinement flow summary">
                <section className="rounded-lg border bg-muted/20 p-4">
                  <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">At a glance</p>
                  <dl className="mt-3 grid gap-3 text-xs">
                    <div><dt className="font-medium text-foreground">Starts with</dt><dd className="mt-1 text-muted-foreground">The current Narrative &amp; Cleanup editor value.</dd></div>
                    <div><dt className="font-medium text-foreground">Uses</dt><dd className="mt-1 text-muted-foreground">PHP Memory RAG, the generated handoff context, and the visible Codex Chat bridge.</dd></div>
                    <div><dt className="font-medium text-foreground">Returns</dt><dd className="mt-1 text-muted-foreground">The exact Stage 1 JSON contract, implementation evidence when authorized, saved revision, and verified active draft.</dd></div>
                    <div><dt className="font-medium text-foreground">On failure</dt><dd className="mt-1 text-muted-foreground">The prior draft stays intact and React reports the failed gate.</dd></div>
                  </dl>
                </section>
                <section className="rounded-lg border border-violet-500/30 bg-violet-500/5 p-4" aria-labelledby="narrative-coordinator-schema-title">
                  <div className="flex items-center justify-between gap-2"><p id="narrative-coordinator-schema-title" className="text-xs font-semibold uppercase tracking-wider text-violet-700 dark:text-violet-300">Coordinator process schema</p><Badge variant="outline">{narrativeCoordinatorProcess.schemaVersion}</Badge></div>
                  <p className="mt-2 text-xs leading-5 text-muted-foreground">{narrativeCoordinatorProcess.coordinator.objective}</p>
                  <dl className="mt-3 grid gap-2 text-xs">
                    <div><dt className="font-medium text-foreground">Coordinator gates</dt><dd className="mt-1 text-muted-foreground">{narrativeCoordinatorProcess.coordinator.label} · plan · approval · final verification</dd></div>
                    <div><dt className="font-medium text-foreground">Analysis agents</dt><dd className="mt-1 text-muted-foreground">Up to 3 selected from {narrativeCoordinatorProcess.specialistCalls} active configured agents; checker and tester gates are separate.</dd></div>
                    <div><dt className="font-medium text-foreground">Skills ({narrativeCoordinatorProcess.skills.length})</dt><dd className="mt-1 text-muted-foreground">{narrativeCoordinatorProcess.skills.map((skill) => `${skill.label} (${skill.id})`).join(' · ')}</dd></div>
                    <div><dt className="font-medium text-foreground">Required response schema ({narrativeCoordinatorProcess.responseSchema.length})</dt><dd className="mt-1 break-words text-muted-foreground">{narrativeCoordinatorProcess.responseSchema.map((field) => field.key).join(' · ')}</dd></div>
                  </dl>
                </section>
                <section className="rounded-lg border border-emerald-500/30 bg-emerald-500/5 p-4">
                  <div className="flex items-center gap-2 text-sm font-semibold"><CheckCircle2 className="size-4 text-emerald-600 dark:text-emerald-300" />Completion evidence</div>
                  <p className="mt-2 text-xs leading-5 text-muted-foreground">The flow is complete only after the saved narrative is read back and matches the persisted active draft.</p>
                </section>
                <section className="rounded-lg border border-amber-500/30 bg-amber-500/5 p-4">
                  <div className="flex items-center gap-2 text-sm font-semibold"><ShieldCheck className="size-4 text-amber-600 dark:text-amber-300" />Scope boundary</div>
                  <p className="mt-2 text-xs leading-5 text-muted-foreground">This viewer explains the request path only. Opening it never sends a request or changes the draft.</p>
                </section>
              </aside>
            </div>
          </div>
          <DialogFooter className="sticky bottom-0 z-30 m-0 flex w-full min-w-0 shrink-0 flex-row items-center justify-between gap-3 rounded-none border-t bg-popover px-6 py-4 shadow-sm sm:flex-row sm:justify-between">
            <p role="status" aria-live="polite" className="min-w-0 flex-1 text-left text-xs text-muted-foreground">Blueprint viewer · no action started</p>
            <Button type="button" variant="outline" className="shrink-0" onClick={() => setNarrativeProcessOpen(false)}>Close</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
      <Dialog open={draftGuideOpen} onOpenChange={setDraftGuideOpen}>
        <DialogContent showCloseButton={false} className={cn(dialogSizeClass('XL'), 'flex h-[calc(100dvh-2rem)] max-h-[calc(100dvh-2rem)] min-h-0 flex-col gap-0 overflow-hidden p-0')}>
          <DialogHeader className="sticky top-0 z-10 shrink-0 border-b bg-popover px-6 py-5 pr-14">
            <DialogClose render={<Button type="button" variant="ghost" size="icon-sm" className="absolute top-4 right-4 text-muted-foreground hover:text-foreground" aria-label="Close Long draft guide" title="Close Long draft guide" />}>
              <X />
            </DialogClose>
            <DialogTitle className="flex items-center gap-2"><BookOpen />Long draft guide</DialogTitle>
            <DialogDescription>Use meaning-based sections to keep the Tab 1 narrative complete and easier to review in Codex Chat.</DialogDescription>
          </DialogHeader>
          <div className="min-h-0 flex-1 overflow-y-auto px-6 py-6">
            <div className="mx-auto grid max-w-5xl gap-6">
              <section aria-labelledby="narrative-draft-guide-title" className="rounded-lg border border-sky-500/30 bg-sky-500/5 p-5">
                <h2 id="narrative-draft-guide-title" className="text-base font-semibold">Long draft guide</h2>
        <p className="mt-2 text-sm leading-6 text-muted-foreground">For Tab 1, split the draft by meaning rather than by character count. Keep complete paragraphs, requirements, URLs, and ideas together when sending sections to the VS Code Codex Chat bridge.</p>
              </section>
              <section aria-labelledby="narrative-draft-guide-sections-title" className="grid gap-4">
                <div>
                  <h2 id="narrative-draft-guide-sections-title" className="text-base font-semibold">Suggested sections</h2>
                  <p className="mt-1 text-sm text-muted-foreground">Use these headings to organize the narrative before sending it for review.</p>
                </div>
                <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3" aria-label="Suggested narrative sections">
                  {narrativeDraftGuideSections.map((section, index) => <div key={section} className="flex min-w-0 items-start gap-3 rounded-md border bg-muted/20 p-4"><span className="grid size-7 shrink-0 place-items-center rounded-full border bg-background text-xs font-semibold text-muted-foreground">{index + 1}</span><code className="min-w-0 break-words pt-1 font-mono text-sm text-foreground">## {section}</code></div>)}
                </div>
              </section>
              <section aria-labelledby="narrative-draft-guide-copy-title" className="grid gap-3 rounded-lg border bg-muted/20 p-5">
                <div>
                  <h2 id="narrative-draft-guide-copy-title" className="text-base font-semibold">Ready to copy and paste</h2>
                  <p className="mt-1 text-sm text-muted-foreground">Copy the complete Markdown guide for use in Codex Chat or project notes.</p>
                </div>
                <Textarea value={narrativeDraftGuideCopyText} readOnly aria-label="Ready-to-copy Long draft guide" className="min-h-64 resize-y bg-background font-mono text-sm leading-6" />
              </section>
            </div>
          </div>
          <DialogFooter className="sticky bottom-0 shrink-0 flex-row items-center justify-between bg-popover">
            <p role="status" aria-live="polite" className="text-xs text-muted-foreground">{draftGuideCopyMessage || 'The guide is formatted as Markdown for direct reuse.'}</p>
            <Button type="button" variant="outline" size="sm" onClick={() => void copyDraftGuide()}><Copy data-icon="inline-start" />Copy to Clipboard</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
      <AlertDialog open={aiConfirmationScope !== null} onOpenChange={(open) => { if (!open) setAiConfirmationScope(null) }}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle className="flex items-center gap-2"><Sparkles className="size-4 text-sky-600 dark:text-sky-300" />{aiConfirmationScope ? aiConfirmationDetails[aiConfirmationScope].title : 'Confirm AI Task'}</AlertDialogTitle>
            <AlertDialogDescription className="grid gap-2 text-left">
              <span>{aiConfirmationScope ? aiConfirmationDetails[aiConfirmationScope].description : ''}</span>
              <span className="rounded-md bg-muted/60 p-3 text-xs leading-5 text-foreground">Tab: <strong>{aiConfirmationScope ? aiConfirmationDetails[aiConfirmationScope].tab : ''}</strong><br />BuilderX will prepare this bounded request and send it to the active VS Code Codex Chat through the local bridge. The local background AI action will not run.</span>
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction type="button" onClick={confirmTabAiAction}><MessageCircle />Send to Codex Chat</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </Card>
  )
}

function PhaseTaskCard({ task }: { task: Record<string, any> }) {
  const isCompleted = phaseNumber(task, 'is_completed') === 1
  const checklist = Array.isArray(task.checklist) ? task.checklist : []
  const notes = Array.isArray(task.notes) ? task.notes : []

  return (
    <Card>
      <CardHeader className="flex min-w-0 flex-col gap-3 lg:flex-row lg:items-start lg:justify-between">
        <div className="min-w-0">
          <Badge variant={isCompleted ? 'default' : 'secondary'}>{phaseField(task, 'task_code')}</Badge>
          <CardTitle className="mt-2 break-words text-lg tracking-normal">{phaseField(task, 'task_title', 'Untitled Target')}</CardTitle>
          <CardDescription className="mt-1 max-w-4xl break-words">{phaseField(task, 'task_details', 'No task details saved.')}</CardDescription>
        </div>
	        <form method="post" onSubmit={handlePhaseJsonSubmit} className="shrink-0">
	          <input type="hidden" name="csrf" value={phaseData?.csrf || ''} />
	          <input type="hidden" name="action" value="update_task" />
          <input type="hidden" name="task_key" value={phaseField(task, 'task_key')} />
          <input type="hidden" name="is_completed" value={isCompleted ? '0' : '1'} />
          <Button type="submit" variant={isCompleted ? 'outline' : 'default'} size="sm">
            <ShieldCheck />
            {isCompleted ? 'Reopen' : 'Complete'}
          </Button>
        </form>
      </CardHeader>
      <CardContent>
        <Tabs defaultValue="checklist">
          <TabsList className="flex w-fit max-w-full overflow-x-auto">
            <TabsTrigger value="checklist"><ShieldCheck />Checklist</TabsTrigger>
            <TabsTrigger value="notes"><Activity />Notes</TabsTrigger>
            <TabsTrigger value="source"><BookOpen />Source</TabsTrigger>
          </TabsList>
          <TabsContent value="checklist" className="mt-4 grid gap-2">
            {checklist.length === 0 ? <p className="text-sm text-muted-foreground">No checklist items saved.</p> : checklist.map((item: Record<string, any>) => {
              const isDone = phaseNumber(item, 'is_done') === 1
              return (
                <form key={phaseField(item, 'checklist_key')} method="post" onSubmit={handlePhaseJsonSubmit} className="flex min-w-0 items-start gap-3 rounded-md border p-3">
                  <input type="hidden" name="csrf" value={phaseData?.csrf || ''} />
                  <input type="hidden" name="action" value="update_checklist" />
                  <input type="hidden" name="checklist_key" value={phaseField(item, 'checklist_key')} />
                  <input type="hidden" name="is_done" value={isDone ? '0' : '1'} />
                  <Button type="submit" variant={isDone ? 'default' : 'outline'} size="icon-sm" className="shrink-0" aria-label={isDone ? 'Mark checklist pending' : 'Mark checklist done'}>
                    <ShieldCheck />
                  </Button>
                  <div className="min-w-0 flex-1">
                    <p className="break-words text-sm font-medium leading-5">{phaseField(item, 'checklist_title', phaseField(item, 'checklist_text', 'Checklist Item'))}</p>
                    <p className="mt-1 text-xs text-muted-foreground">{isDone ? 'Done' : 'Pending'}</p>
                  </div>
                </form>
              )
            })}
          </TabsContent>
          <TabsContent value="notes" className="mt-4 grid gap-3">
            {notes.length === 0 ? <p className="text-sm text-muted-foreground">No review notes saved.</p> : notes.map((note: Record<string, any>) => (
              <div key={phaseField(note, 'note_key')} className="rounded-md border p-3">
                <div className="mb-2 flex flex-wrap items-center justify-between gap-2">
                  <Badge variant={phaseField(note, 'note_status') === 'DONE' ? 'default' : 'secondary'}>{phaseField(note, 'note_status', 'PENDING')}</Badge>
                  <span className="text-xs text-muted-foreground">{phaseField(note, 'created_at')}</span>
                </div>
                <p className="whitespace-pre-wrap text-sm leading-6">{noteUserFacingText(note, 'No review note text saved.')}</p>
              </div>
            ))}
            <form method="post" onSubmit={handlePhaseJsonSubmit} className="grid gap-3 rounded-md border bg-muted/30 p-3">
              <input type="hidden" name="csrf" value={phaseData?.csrf || ''} />
              <input type="hidden" name="action" value="add_note" />
              <input type="hidden" name="task_key" value={phaseField(task, 'task_key')} />
              <Label htmlFor={`note-${phaseField(task, 'task_key')}`}>Review Note</Label>
              <Textarea id={`note-${phaseField(task, 'task_key')}`} name="note_text" rows={3} required />
              <Button type="submit" size="sm" className="w-fit"><Plus />Add Note</Button>
            </form>
          </TabsContent>
          <TabsContent value="source" className="mt-4">
            <pre className="max-h-96 overflow-auto rounded-md border bg-muted/40 p-4 text-xs leading-5 whitespace-pre-wrap">{phaseField(task, 'task_reference') || phaseField(task, 'task_acceptance_checklist') || 'No source reference saved.'}</pre>
          </TabsContent>
        </Tabs>
      </CardContent>
    </Card>
  )
}

function PhaseSettingsView() {
  const settings = phaseData?.settings ?? {}
  const parallelAgents = Array.isArray(settings.parallelAgents) ? settings.parallelAgents : []
  const orchestrationReports = Array.isArray(phaseData?.orchestrationReports) ? phaseData.orchestrationReports : []
  const parallelSkills = Array.isArray(settings.parallelSkills) ? settings.parallelSkills : []
  const requestedAgentId = new URLSearchParams(window.location.search).get('agent') || ''
  const firstAgentId = String(parallelAgents[0]?.id || '')
  const initialAgentId = parallelAgents.some((agent: Record<string, any>) => String(agent.id || '') === requestedAgentId)
    ? requestedAgentId
    : firstAgentId
  const [selectedAgentId, setSelectedAgentId] = React.useState(initialAgentId)
  const selectedAgent = parallelAgents.find((agent: Record<string, any>) => String(agent.id || '') === selectedAgentId) || parallelAgents[0] || null
  const selectedAgentIsCoordinator = String(selectedAgent?.id || '') === 'coordinator'
  const assignedSkillIds = new Set(parallelAgents
    .filter((agent: Record<string, any>) => String(agent.id || '') !== String(selectedAgent?.id || ''))
    .map((agent: Record<string, any>) => String(agent.skill || ''))
    .filter(Boolean))
  const availableAgentSkills = parallelSkills.filter((skill: Record<string, any>) => String(skill.id || '') === String(selectedAgent?.skill || '') || !assignedSkillIds.has(String(skill.id || '')))
  const skillLabel = (skillId: unknown) => String(parallelSkills.find((skill: Record<string, any>) => String(skill.id || '') === String(skillId || ''))?.label || 'No skill assigned')
  const [selectedAgentActive, setSelectedAgentActive] = React.useState(selectedAgent?.active !== false)
  const [selectedAgentSkill, setSelectedAgentSkill] = React.useState(String(selectedAgent?.skill || ''))
  const [parallelPingBusy, setParallelPingBusy] = React.useState(false)
  const [parallelPingResult, setParallelPingResult] = React.useState<Record<string, any> | null>(null)
  const [coordinatorRunBusy, setCoordinatorRunBusy] = React.useState(false)
  const [coordinatorRunResult, setCoordinatorRunResult] = React.useState<Record<string, any> | null>(null)

  React.useEffect(() => {
    setSelectedAgentActive(selectedAgent?.active !== false)
    setSelectedAgentSkill(String(selectedAgent?.skill || ''))
  }, [selectedAgentId, selectedAgent?.active, selectedAgent?.skill])

  async function testAllParallelAgentPings() {
    if (parallelPingBusy || parallelAgents.length === 0) return
    setParallelPingBusy(true)
    setParallelPingResult(null)
    try {
      const response = await fetch(`${visualCodexBridgeUrl}/orchestration-test`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ workspace_root: phaseData?.projectRoot || '', parallel_agents: parallelAgents }),
      })
      const result = await response.json()
      if (!response.ok || result?.ok !== true) throw new Error(result?.message || 'The parallel agent ping test failed.')
      setParallelPingResult(result)
    } catch (error) {
      setParallelPingResult({ ok: false, message: error instanceof Error ? error.message : 'The Codex Chat panel test failed.' })
    } finally {
      setParallelPingBusy(false)
    }
  }

  async function testCoordinatorOrchestration() {
    if (coordinatorRunBusy || parallelAgents.length < 2) return
    setCoordinatorRunBusy(true)
    setCoordinatorRunResult(null)
    let orchestrationRunKey = ''
    try {
      const objective = 'Verify the staged BuilderX Codex Chat lifecycle: coordinator analysis and minimum specialist selection, independent checker, coordinator approval, tester, final verification, and terminal result. This test is review-only; do not edit files or database records.'
      const reportStart = new FormData()
      reportStart.set('csrf', phaseData?.csrf || '')
      reportStart.set('action', 'begin_phase_orchestration_report')
      reportStart.set('phase_key', phaseData?.selectedPhaseKey || '')
      reportStart.set('mode', 'smart-task')
      reportStart.set('task_label', 'Smart Coordinator staged workflow test')
      reportStart.set('objective', objective)
      reportStart.set('max_rounds', '3')
      reportStart.set('configured_specialist_count', String(parallelAgents.filter((agent: Record<string, any>) => agent.active !== false && String(agent.id || '') !== 'coordinator').length))
      const reportStartResponse = await fetch('./', { method: 'POST', body: reportStart, headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' } })
      const reportStartResult = await reportStartResponse.json()
      if (!reportStartResponse.ok || !(reportStartResult.ok || reportStartResult.success)) throw new Error(reportStartResult.message || 'The coordinator process report could not be started.')
      orchestrationRunKey = String(reportStartResult.data?.run_key || '')
      const response = await fetch(`${visualCodexBridgeUrl}/orchestration-run`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          workspace_root: phaseData?.projectRoot || '',
          parallel_agents: parallelAgents,
          test_prompt: objective,
          orchestration_mode: 'smart-task',
          task_level: 'adaptive',
          task_label: 'Smart Coordinator staged workflow test',
          orchestration_run_key: orchestrationRunKey,
        }),
      })
      const result = await response.json()
      if (!response.ok || result?.ok !== true) throw new Error(result?.message || 'The coordinator orchestration test failed.')
      const reportForm = new FormData()
      reportForm.set('csrf', phaseData?.csrf || '')
      reportForm.set('action', 'complete_phase_orchestration_report')
      reportForm.set('run_key', orchestrationRunKey)
      reportForm.set('orchestration_result', JSON.stringify(result))
      const reportResponse = await fetch('./', { method: 'POST', body: reportForm, headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' } })
      const reportResult = await reportResponse.json()
      const report = reportResponse.ok && (reportResult.ok || reportResult.success) ? reportResult.data?.report : null
      if (report && phaseData) phaseData.orchestrationReports = [report, ...(phaseData.orchestrationReports || [])].slice(0, 10)
      setCoordinatorRunResult(report ? { ...result, report } : result)
    } catch (error) {
      const message = error instanceof Error ? error.message : 'The coordinator orchestration test failed.'
      if (orchestrationRunKey !== '') {
        const reportFail = new FormData()
        reportFail.set('csrf', phaseData?.csrf || '')
        reportFail.set('action', 'fail_phase_orchestration_report')
        reportFail.set('run_key', orchestrationRunKey)
        reportFail.set('failure_reason', message)
        await fetch('./', { method: 'POST', body: reportFail, headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' } }).catch(() => undefined)
      }
      setCoordinatorRunResult({ ok: false, message })
    } finally {
      setCoordinatorRunBusy(false)
    }
  }

  return (
    <Card>
      <CardHeader className="gap-0.5">
        <CardTitle>AI Agent Settings</CardTitle>
        <CardDescription>Manage parallel agents and runtime settings.</CardDescription>
      </CardHeader>
      <CardContent>
        <Tabs defaultValue="parallel-agents" className="w-full gap-1">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <TabsList className="h-auto">
              <TabsTrigger className="flex-none px-3" value="parallel-agents"><Activity />Parallel Agent Settings</TabsTrigger>
              <TabsTrigger className="flex-none px-3" value="others"><Settings />Others</TabsTrigger>
            </TabsList>
            <div className="flex items-center gap-1">
              <Tooltip>
                <TooltipTrigger render={<Button type="button" variant="outline" size="icon-sm" className="border-sky-500/40 text-sky-600 hover:bg-sky-500/10 hover:text-sky-700 dark:text-sky-300 dark:hover:text-sky-200" aria-label={parallelPingBusy ? 'Testing Codex Chat panels' : 'Test Codex Chat panels'} title={parallelPingBusy ? 'Testing Codex Chat panels' : 'Test Codex Chat panels'} onClick={() => void testAllParallelAgentPings()} disabled={parallelPingBusy || parallelAgents.length === 0} />}>
                  {parallelPingBusy ? <LoaderCircle className="animate-spin" /> : <Activity />}
                </TooltipTrigger>
                <TooltipContent>{parallelPingBusy ? 'Testing Codex Chat panels' : 'Test Codex Chat panels'}</TooltipContent>
              </Tooltip>
              <Tooltip>
                <TooltipTrigger render={<Button type="button" variant="outline" size="icon-sm" className="border-violet-500/40 text-violet-600 hover:bg-violet-500/10 hover:text-violet-700 dark:text-violet-300 dark:hover:text-violet-200" aria-label={coordinatorRunBusy ? 'Running coordinator orchestration' : 'Test coordinator orchestration'} title={coordinatorRunBusy ? 'Running coordinator orchestration' : 'Test coordinator orchestration'} onClick={() => void testCoordinatorOrchestration()} disabled={coordinatorRunBusy || parallelAgents.length < 2} />}>
                  {coordinatorRunBusy ? <LoaderCircle className="animate-spin" /> : <Workflow />}
                </TooltipTrigger>
                <TooltipContent>{coordinatorRunBusy ? 'Running coordinator orchestration' : 'Test coordinator orchestration'}</TooltipContent>
              </Tooltip>
            </div>
          </div>
          <TabsContent value="parallel-agents" className="mt-2">
            {parallelPingResult ? <div className="mb-3 grid gap-2 rounded-lg border bg-background/60 p-2" role="status" aria-live="polite">
              <div className="flex flex-wrap items-center justify-between gap-2"><p className="text-sm font-semibold">Codex Chat panel results</p><Badge variant={parallelPingResult.ok === false ? 'destructive' : 'outline'}>{parallelPingResult.ok === false ? 'TEST FAILED' : `${String(parallelPingResult.chat_panel_created_count || 0)} / ${String(parallelAgents.filter((agent: Record<string, any>) => agent.active !== false).length)} created`}</Badge></div>
              <p className="text-xs text-muted-foreground">{String(parallelPingResult.message || '')}</p>
              <div className="grid gap-2 sm:grid-cols-2">
                {parallelAgents.map((agent: Record<string, any>) => {
                  const agentId = String(agent.id || '')
                  const runtimeRole = Array.isArray(parallelPingResult.roles) ? parallelPingResult.roles.find((role: Record<string, any>) => String(role.id || '') === agentId) : null
                  const inactive = agent.active === false
                  const resultStatus = inactive ? 'skipped' : String(runtimeRole?.status || 'unavailable')
                  const resultClass = resultStatus === 'session-created' ? 'text-emerald-600 dark:text-emerald-300' : resultStatus === 'skipped' ? 'text-muted-foreground' : 'text-destructive'
                  return <div key={agentId} className="rounded border bg-muted/10 p-2"><div className="flex items-center justify-between gap-2"><span className="min-w-0 truncate text-[11px] font-medium">{String(agent.name || agentId)}</span><span className={cn('text-[10px] font-semibold uppercase', resultClass)}>{resultStatus.replaceAll('-', ' ')}</span></div><p className="mt-1 text-[10px] leading-4 text-muted-foreground">{inactive ? 'Inactive agent was skipped.' : String(runtimeRole?.detail || 'No Codex Chat panel status was returned.')}</p></div>
                })}
              </div>
            </div> : null}
            {coordinatorRunResult ? <div className="mb-3 grid gap-2 rounded-lg border bg-background/60 p-2" role="status" aria-live="polite">
              <div className="flex flex-wrap items-center justify-between gap-2"><p className="text-sm font-semibold">Coordinator orchestration results</p><Badge variant={coordinatorRunResult.ok === false || coordinatorRunResult.merge_completed !== true ? 'destructive' : 'outline'}>{coordinatorRunResult.ok === false ? 'TEST FAILED' : `${String(coordinatorRunResult.completed_specialist_count || 0)} / ${String(coordinatorRunResult.selected_specialist_count || coordinatorRunResult.configured_specialist_count || 0)} analysts completed`}</Badge></div>
              <p className="text-xs text-muted-foreground">{String(coordinatorRunResult.message || '')}</p>
              {coordinatorRunResult.report ? <div className="grid gap-2 rounded border border-violet-500/30 bg-violet-500/5 p-2"><div className="flex flex-wrap items-center gap-1.5"><span className="text-[11px] font-semibold">Complete process report</span><Badge variant="outline">{String(coordinatorRunResult.report.status || 'RUNNING')}</Badge><Badge variant="outline">Total AI calls: {String(coordinatorRunResult.report.total_agent_call_count || 0)}</Badge><Badge variant="outline">Coordinator: {String(coordinatorRunResult.report.coordinator_call_count || 0)}</Badge><Badge variant="outline">Specialists: {String(coordinatorRunResult.report.specialist_call_count || 0)}</Badge><Badge variant="outline">Rounds: {String(coordinatorRunResult.report.rounds_completed || 0)}</Badge></div><p className="text-[10px] text-muted-foreground">Every visible Coordinator plan/merge and specialist call is counted with its round, agent, status, session, start/end time, and duration.</p><details><summary className="cursor-pointer text-[11px] font-medium">View call timeline ({Array.isArray(coordinatorRunResult.report.calls) ? coordinatorRunResult.report.calls.length : 0})</summary><div className="mt-2 grid gap-1">{(Array.isArray(coordinatorRunResult.report.calls) ? coordinatorRunResult.report.calls : []).map((call: Record<string, any>, index: number) => <div key={`${String(call.call_key || call.sequence_number || index)}`} className="grid gap-1 rounded border bg-background/60 p-2 text-[10px] sm:grid-cols-[auto_1fr_auto]"><span className="font-semibold">#{String(call.sequence_number || index + 1)} R{String(call.round_number || 0)} {String(call.role_type || 'agent')}</span><span>{String(call.agent_label || call.agent_id || 'AI agent')} · {String(call.call_type || 'call')} · {String(call.status || 'unknown')}</span><span className="text-muted-foreground">{String(call.duration_ms || 0)} ms</span></div>)}</div></details></div> : null}
              {coordinatorRunResult.coordinator ? <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-4"><div className="rounded border bg-muted/10 p-2"><p className="text-[11px] font-semibold">Plan</p><p className="mt-1 text-[10px] uppercase text-muted-foreground">{String(coordinatorRunResult.coordinator.plan_status || (coordinatorRunResult.coordinator.plan_response ? 'completed' : 'unavailable'))}</p></div><div className="rounded border bg-muted/10 p-2"><p className="text-[11px] font-semibold">Checker</p><p className="mt-1 text-[10px] uppercase text-muted-foreground">{coordinatorRunResult.checker?.contract_valid === true ? 'approved' : 'not returned'}</p></div><div className="rounded border bg-muted/10 p-2"><p className="text-[11px] font-semibold">Tester</p><p className="mt-1 text-[10px] uppercase text-muted-foreground">{coordinatorRunResult.tester?.release_ready === true ? 'release ready' : 'not returned'}</p></div><div className="rounded border bg-muted/10 p-2"><p className="text-[11px] font-semibold">Final verification</p><p className="mt-1 text-[10px] uppercase text-muted-foreground">{String(coordinatorRunResult.coordinator.final_verification_status || coordinatorRunResult.coordinator.merge_status || 'unavailable')}</p></div></div> : null}
              {Array.isArray(coordinatorRunResult.specialists) ? <div className="grid gap-2 sm:grid-cols-2">{coordinatorRunResult.specialists.map((specialist: Record<string, any>) => <div key={String(specialist.id || specialist.label)} className="rounded border bg-muted/10 p-2"><div className="flex items-center justify-between gap-2"><span className="min-w-0 truncate text-[11px] font-medium">{String(specialist.label || specialist.id || 'Specialist')}</span><span className={cn('text-[10px] font-semibold uppercase', specialist.status === 'completed' ? 'text-emerald-600 dark:text-emerald-300' : 'text-destructive')}>{String(specialist.status || 'unavailable')}</span></div><p className="mt-1 text-[10px] leading-4 text-muted-foreground">{String(specialist.detail || '')}</p></div>)}</div> : null}
              {String(coordinatorRunResult.coordinator?.merge_response || '').trim() ? <div className="rounded border bg-muted/10 p-2"><p className="text-[11px] font-semibold">Merged result</p><pre className="mt-2 max-h-64 overflow-auto whitespace-pre-wrap text-[10px] leading-4 text-muted-foreground">{String(coordinatorRunResult.coordinator.merge_response)}</pre></div> : null}
            </div> : null}
            {orchestrationReports.length > 0 ? <div className="mb-3 grid gap-2 rounded-lg border bg-background/60 p-2"><div className="flex items-center justify-between gap-2"><p className="text-sm font-semibold">Saved orchestration process reports</p><Badge variant="outline">{orchestrationReports.length}</Badge></div><div className="grid gap-1">{orchestrationReports.slice(0, 10).map((report: Record<string, any>) => <details key={String(report.run_key || report.created_at)} className="rounded border bg-muted/10 p-2"><summary className="cursor-pointer text-[11px] font-medium">{String(report.task_label || 'Coordinator run')} · {String(report.status || 'UNKNOWN')} · {String(report.total_agent_call_count || 0)} AI calls · {String(report.rounds_completed || 0)} rounds</summary><div className="mt-2 grid gap-1 text-[10px] text-muted-foreground"><span>Started: {String(report.started_at || 'unknown')} · Completed: {String(report.completed_at || 'in progress')}</span><span>Coordinator calls: {String(report.coordinator_call_count || 0)} · Specialist calls: {String(report.specialist_call_count || 0)}</span><span>Run key: {String(report.run_key || 'unknown')}</span></div></details>)}</div></div> : null}
            {selectedAgent ? <div className="grid min-h-0 gap-3 lg:grid-cols-[15rem_minmax(0,1fr)]">
              <ScrollArea className="h-96 min-h-0 rounded-lg border lg:h-[calc(100vh-24rem)] lg:max-h-[42rem]">
                <div role="listbox" aria-label="Parallel AI agents" className="grid content-start gap-2 bg-muted/10 p-2">
                  <p className="px-2 py-1 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">AI agents</p>
                  {parallelAgents.map((agent: Record<string, any>) => {
                    const agentId = String(agent.id || '')
                    const selected = agentId === String(selectedAgent.id || '')
                    const active = agent.active !== false
                    return <Button key={agentId} type="button" variant={selected ? 'secondary' : 'ghost'} className="h-auto min-h-12 justify-start whitespace-normal px-3 py-2 text-left" onClick={() => setSelectedAgentId(agentId)} role="option" aria-selected={selected}><span className="flex min-w-0 items-center gap-2"><span className="min-w-0"><span className="block break-words text-sm font-medium">{String(agent.name || agentId)}</span><span className={cn('mt-0.5 block truncate text-[11px]', active ? 'text-emerald-600 dark:text-emerald-300' : 'text-muted-foreground')}>{skillLabel(agent.skill)}</span></span><span className={cn('ml-auto size-2 shrink-0 rounded-full', active ? 'bg-emerald-500' : 'bg-muted-foreground/40')} title={active ? 'Active specialist' : 'Inactive specialist'} aria-label={active ? 'Active specialist' : 'Inactive specialist'} /></span></Button>
                  })}
                </div>
              </ScrollArea>
              <ScrollArea className="h-96 min-h-0 rounded-lg border lg:h-[calc(100vh-24rem)] lg:max-h-[42rem]">
              <form key={String(selectedAgent.id || '')} method="post" className="grid content-start gap-3 p-3">
                <input type="hidden" name="csrf" value={phaseData?.csrf || ''} />
                <input type="hidden" name="action" value="save_parallel_agent_settings" />
                <input type="hidden" name="agent_id" value={String(selectedAgent.id || '')} />
                <input type="hidden" name="agent_active" value={selectedAgentActive ? '1' : '0'} />
                <h3 className="text-lg font-semibold">{String(selectedAgent.name || selectedAgent.id || 'AI Agent')}</h3>
                <div className="grid gap-2">
                  <Label htmlFor={`parallel-agent-name-${String(selectedAgent.id || 'agent')}`}>Agent name</Label>
                  <Input id={`parallel-agent-name-${String(selectedAgent.id || 'agent')}`} name="agent_name" defaultValue={String(selectedAgent.name || '')} maxLength={80} required readOnly={selectedAgentIsCoordinator} />
                </div>
                <div className="grid gap-2">
                  <Label htmlFor={`parallel-agent-skill-${String(selectedAgent.id || 'agent')}`}>Agent skill</Label>
                  {selectedAgentIsCoordinator ? <><input type="hidden" name="agent_skill" value="coordination" /><div className="flex min-h-8 items-center justify-between gap-2 rounded-lg border bg-muted/20 px-2.5 text-sm"><span>Coordination</span><Badge variant="secondary">Permanent</Badge></div></> : <><input type="hidden" name="agent_skill" value={selectedAgentSkill === '__none__' ? '' : selectedAgentSkill} /><Select value={selectedAgentSkill || '__none__'} onValueChange={(value) => setSelectedAgentSkill(value || '__none__')}><SelectTrigger id={`parallel-agent-skill-${String(selectedAgent.id || 'agent')}`} className="w-full"><SelectValue placeholder="No skill assigned" /></SelectTrigger><SelectContent><SelectGroup><SelectItem value="__none__">No skill assigned</SelectItem>{availableAgentSkills.map((skill: Record<string, any>) => <SelectItem key={String(skill.id || '')} value={String(skill.id || '')}>{String(skill.label || skill.id || 'Skill')}</SelectItem>)}</SelectGroup></SelectContent></Select><p className="text-xs text-muted-foreground">Skills assigned to other agents are not available.</p></>}
                </div>
                <div className="flex items-center justify-between gap-4 rounded-md border bg-muted/20 p-3">
                  <Label htmlFor={`parallel-agent-active-${String(selectedAgent.id || 'agent')}`}>{selectedAgentIsCoordinator ? 'Permanent coordinator' : 'Agent status'}</Label>
                  <Switch id={`parallel-agent-active-${String(selectedAgent.id || 'agent')}`} checked={selectedAgentIsCoordinator || selectedAgentActive} onCheckedChange={setSelectedAgentActive} disabled={selectedAgentIsCoordinator} aria-label={`Set ${String(selectedAgent.name || selectedAgent.id || 'agent')} active`} />
                </div>
                <Button type="submit" className="w-fit"><Save />Save</Button>
              </form>
              </ScrollArea>
            </div> : <p className="rounded-lg border border-dashed p-6 text-center text-sm text-muted-foreground">No parallel agents are configured.</p>}
          </TabsContent>
          <TabsContent value="others" className="mt-4 grid gap-4">
            <Card className="border-dashed">
              <CardHeader>
                <CardTitle className="text-base">AI Runtime Settings</CardTitle>
                <CardDescription>Configure the bounded Codex Chat runtime used by Phase Manager actions.</CardDescription>
              </CardHeader>
              <CardContent><CodexSettingsDialog sourceView="settings" /></CardContent>
            </Card>
          </TabsContent>
        </Tabs>
      </CardContent>
    </Card>
  )
}

function projectFlowEntrypointForFlowKey(flowKey: string): { route: string; label: string; owner: string } {
  if (flowKey === 'user') return { route: '/', label: 'User Portal', owner: 'User Portal' }

  return { route: '/administrator/', label: 'Administrator', owner: 'Administrator' }
}

function projectFlowTableTargetsFromNotes(notes: Array<Record<string, any>>): Array<string> {
  return uniqueProjectFlowValues(notes.map((note) => {
    const target = phaseField(note, 'crudTargetTable', 'NONE')
    if (target === 'NEW') return phaseField(note, 'crudNewTableName', 'New Table')
    if (target === 'NONE') return ''

    return target
  }))
}

function projectFlowEntriesGeneratedFromUiUxFlow(baseEntries: Array<Record<string, any>>): Array<Record<string, any>> {
  const flows = phaseData?.uiUxFlow?.flows
  if (!Array.isArray(flows)) return baseEntries

  const entryMap = new Map<string, Record<string, any>>()
  baseEntries.forEach((entry) => {
    const route = phaseField(entry, 'route')
    if (route !== '') {
      entryMap.set(route, { ...entry, views: projectFlowViews(entry).map((view) => ({ ...view })) })
    }
  })

  const mappedPhaseTasks = new Set<string>()
  Array.from(entryMap.values()).forEach((entry) => {
    projectFlowViews(entry).forEach((view) => {
      const phaseTask = phaseField(view, 'phaseTask')
      if (phaseTask !== '') mappedPhaseTasks.add(phaseTask)
    })
  })

  flows.forEach((flow: Record<string, any>) => {
    if (uiUxFlowRecordIsDeleted(flow)) return

    const flowKey = phaseField(flow, 'key', 'admin')
    const entrySeed = projectFlowEntrypointForFlowKey(flowKey)
    const route = entrySeed.route
    const entry = entryMap.get(route) || { route, label: entrySeed.label, owner: entrySeed.owner, views: [] }
    const views = projectFlowViews(entry)

    activeUiUxFlowSections(flow.sections).forEach((section: Record<string, any>) => {
      const sectionKey = phaseField(section, 'key', 'section')
      const groups = Array.isArray(section.groups) ? section.groups : []

      groups.forEach((group: Record<string, any>) => {
        const phaseKey = phaseField(group, 'phaseKey')
        const phaseCode = phaseField(group, 'phaseCode')
        const groupKey = phaseField(group, 'key', phaseKey)
        if (phaseKey === '' || phaseCode === '' || phaseCode.toUpperCase() === 'P0') return
        if (mappedPhaseTasks.has(phaseCode)) return

        const subphases = Array.isArray(group.subphases) ? group.subphases : []
        const viewUrl = `${route}#${sectionKey}-${phaseCode.toLowerCase()}`
        views.push({
          key: `uiux-${flowKey}-${sectionKey}-${groupKey}`,
          label: phaseField(group, 'label', phaseCode),
          url: viewUrl,
          phaseTask: phaseCode,
          generatedFrom: 'UI-UX Flow',
          actions: subphases.map((subphase: Record<string, any>, subphaseIndex: number) => {
            const notes = Array.isArray(subphase.notes) ? subphase.notes : []
            return {
              id: `uiux-${flowKey}-${sectionKey}-${groupKey}-${phaseField(subphase, 'taskKey', String(subphaseIndex))}`,
              type: 'UI-UX Task',
              label: phaseField(subphase, 'label', 'Planned UI-UX Task'),
              from: viewUrl,
              to: viewUrl,
              frontendComponent: phaseField(section, 'label', 'UI-UX Flow'),
              backendAction: '',
              phpEntry: '',
              tables: projectFlowTableTargetsFromNotes(notes),
              security: [],
              phaseTask: phaseField(subphase, 'taskCode', ''),
              phaseKey,
              groupKey,
              taskKey: phaseField(subphase, 'taskKey', String(subphaseIndex)),
              notes: notes.filter((note: Record<string, any>) => !uiUxFlowRecordIsDeleted(note)),
            }
          }),
        })
        mappedPhaseTasks.add(phaseCode)
      })
    })

    entry.views = views
    entryMap.set(route, entry)
  })

  return Array.from(entryMap.values())
}

function projectFlowEntries(): Array<Record<string, any>> {
  const entries = phaseData?.projectFlow?.entrypoints
  const baseEntries = Array.isArray(entries) ? entries : []

  return projectFlowEntriesGeneratedFromUiUxFlow(baseEntries)
}

function projectFlowViews(entry: Record<string, any>): Array<Record<string, any>> {
  return Array.isArray(entry.views) ? entry.views : []
}

function projectFlowActions(record: Record<string, any>): Array<Record<string, any>> {
  return Array.isArray(record.actions) ? record.actions : []
}

function countProjectFlowViews(entries: Array<Record<string, any>>): number {
  return entries.reduce((total, entry) => total + projectFlowViews(entry).length, 0)
}

function countProjectFlowActions(entries: Array<Record<string, any>>): number {
  return entries.reduce((total, entry) => {
    const entryActions = projectFlowActions(entry).length
    const viewActions = projectFlowViews(entry).reduce((viewTotal, view) => viewTotal + projectFlowActions(view).length, 0)

    return total + entryActions + viewActions
  }, 0)
}

function projectFlowAllActions(entries: Array<Record<string, any>>): Array<{ entry: Record<string, any>; view?: Record<string, any>; action: Record<string, any> }> {
  return entries.flatMap((entry) => {
    const entryActions = projectFlowActions(entry).map((action) => ({ entry, action }))
    const viewActions = projectFlowViews(entry).flatMap((view) => projectFlowActions(view).map((action) => ({ entry, view, action })))

    return [...entryActions, ...viewActions]
  })
}

function uniqueProjectFlowValues(values: Array<string>): Array<string> {
  return Array.from(new Set(values.map((value) => value.trim()).filter(Boolean))).sort((first, second) => first.localeCompare(second))
}

function projectFlowTables(entries: Array<Record<string, any>>): Array<string> {
  return uniqueProjectFlowValues(projectFlowAllActions(entries).flatMap(({ action }) => Array.isArray(action.tables) ? action.tables : []))
}

function projectFlowSecurityRules(entries: Array<Record<string, any>>): Array<string> {
  return uniqueProjectFlowValues(projectFlowAllActions(entries).flatMap(({ action }) => Array.isArray(action.security) ? action.security : []))
}

function projectFlowBackendEntries(entries: Array<Record<string, any>>): Array<string> {
  return uniqueProjectFlowValues(entries.map((entry) => phaseField(entry.backend, 'phpEntry')))
}

function projectFlowPhaseMappings(entries: Array<Record<string, any>>): Array<string> {
  return uniqueProjectFlowValues([
    ...entries.flatMap((entry) => projectFlowViews(entry).map((view) => phaseField(view, 'phaseTask'))),
    ...projectFlowAllActions(entries).map(({ action }) => phaseField(action, 'phaseTask')),
  ])
}

function projectFlowPageRows(entries: Array<Record<string, any>>): Array<Record<string, any>> {
  return entries.flatMap((entry) => [
    {
      route: phaseField(entry, 'route'),
      label: phaseField(entry, 'label', 'Entrypoint'),
      owner: phaseField(entry, 'owner', 'Project'),
      source: phaseField(entry.frontend, 'source', '-'),
      backend: phaseField(entry.backend, 'phpEntry', '-'),
      kind: 'Entrypoint',
      actions: projectFlowActions(entry).length,
    },
    ...projectFlowViews(entry).map((view) => ({
      route: phaseField(view, 'url'),
      label: phaseField(view, 'label', 'View'),
      owner: phaseField(entry, 'owner', 'Project'),
      source: phaseField(entry.frontend, 'source', '-'),
      backend: phaseField(entry.backend, 'phpEntry', '-'),
      kind: 'Page View',
      phaseTask: phaseField(view, 'phaseTask'),
      actions: projectFlowActions(view).length,
    })),
  ])
}

type ProjectFlowChartNode = {
  id: string
  label: string
  fullLabel: string
  kind: 'terminator' | 'process' | 'decision' | 'document' | 'note' | 'form' | 'database'
  type: string
  responsibility: string
  x: number
  y: number
  width: number
  height: number
}

type ProjectFlowChartEdge = {
  id: string
  from: string
  to: string
}

type ProjectFlowNodePosition = {
  x: number
  y: number
}

function truncateFlowLabel(value: string, maxLength = 26): string {
  const label = value.trim()

  return label.length > maxLength ? `${label.slice(0, maxLength - 1)}...` : label
}

function projectFlowLayoutStorageKey(): string {
  const projectKey = phaseData?.projectBasePath || window.location.pathname.split('/phases/')[0] || '/'
  const version = phaseField(phaseData?.projectFlow, 'version', '1')

  return `builderx:project-flow-layout:${encodeURIComponent(projectKey)}:${encodeURIComponent(version)}:canvas-v5-complete-note-symbols`
}

function readProjectFlowLayout(): Record<string, ProjectFlowNodePosition> {
  if (typeof window === 'undefined') return {}

  try {
    const raw = window.localStorage.getItem(projectFlowLayoutStorageKey())
    const parsed = raw ? JSON.parse(raw) : {}
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return {}

    return Object.entries(parsed).reduce<Record<string, ProjectFlowNodePosition>>((positions, [key, value]) => {
      const position = value as Partial<ProjectFlowNodePosition>
      if (Number.isFinite(position.x) && Number.isFinite(position.y)) {
        positions[key] = { x: Number(position.x), y: Number(position.y) }
      }

      return positions
    }, {})
  } catch {
    return {}
  }
}

function writeProjectFlowLayout(positions: Record<string, ProjectFlowNodePosition>): void {
  if (typeof window === 'undefined') return

  if (Object.keys(positions).length === 0) {
    window.localStorage.removeItem(projectFlowLayoutStorageKey())
    return
  }

  window.localStorage.setItem(projectFlowLayoutStorageKey(), JSON.stringify(positions))
}

type ProjectFlowV2LayoutState = {
  positions: Record<string, ProjectFlowNodePosition>
  viewport: { x: number; y: number; scale: number }
}

function projectFlowV2LayoutStorageKey(): string {
  const projectKey = phaseData?.projectBasePath || window.location.pathname.split('/phases/')[0] || '/'
  const version = phaseField(phaseData?.projectFlow, 'version', '1')

  return `builderx:project-flow-layout:${encodeURIComponent(projectKey)}:${encodeURIComponent(version)}:network-v6-neural-globe`
}

function readProjectFlowV2Layout(): ProjectFlowV2LayoutState {
  const fallback: ProjectFlowV2LayoutState = {
    positions: {},
    viewport: { x: 0, y: 0, scale: 1 },
  }
  if (typeof window === 'undefined') return fallback

  try {
    const raw = window.localStorage.getItem(projectFlowV2LayoutStorageKey())
    const parsed = raw ? JSON.parse(raw) : null
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return fallback

    const positions = parsed.positions && typeof parsed.positions === 'object' && !Array.isArray(parsed.positions)
      ? Object.entries(parsed.positions).reduce<Record<string, ProjectFlowNodePosition>>((result, [key, value]) => {
        const position = value as Partial<ProjectFlowNodePosition>
        if (Number.isFinite(position.x) && Number.isFinite(position.y)) {
          result[key] = { x: Number(position.x), y: Number(position.y) }
        }
        return result
      }, {})
      : {}
    const savedViewport = parsed.viewport && typeof parsed.viewport === 'object' ? parsed.viewport : {}

    return {
      positions,
      viewport: {
        x: Number.isFinite(savedViewport.x) ? Number(savedViewport.x) : fallback.viewport.x,
        y: Number.isFinite(savedViewport.y) ? Number(savedViewport.y) : fallback.viewport.y,
        scale: Number.isFinite(savedViewport.scale) ? Number(savedViewport.scale) : fallback.viewport.scale,
      },
    }
  } catch {
    return fallback
  }
}

function writeProjectFlowV2Layout(state: ProjectFlowV2LayoutState): void {
  if (typeof window === 'undefined') return

  window.localStorage.setItem(projectFlowV2LayoutStorageKey(), JSON.stringify(state))
}

function buildProjectFlowChart(entries: Array<Record<string, any>>): { nodes: ProjectFlowChartNode[]; edges: ProjectFlowChartEdge[]; height: number } {
  const nodes: ProjectFlowChartNode[] = []
  const edges: ProjectFlowChartEdge[] = []
  const routeNodeIds = new Map<string, string>()
  const edgeIds = new Set<string>()
  const noteColumns = 6
  const noteX = 980
  const notePitch = 116
  const relationFormX = 1710
  const relationTableX = 1900

  entries.forEach((entry, entryIndex) => {
    const route = phaseField(entry, 'route')
    if (route !== '' && !routeNodeIds.has(route)) {
      routeNodeIds.set(route, `entry-${entryIndex}`)
    }
    projectFlowViews(entry).forEach((view: Record<string, any>, viewIndex: number) => {
      const url = phaseField(view, 'url')
      if (url !== '') {
        routeNodeIds.set(url, `view-${entryIndex}-${viewIndex}`)
      }
    })
  })

  function addEdge(from: string, to: string) {
    if (from === '' || to === '') return
    const id = `${from}-${to}`
    if (edgeIds.has(id)) return
    edgeIds.add(id)
    edges.push({ id, from, to })
  }

  function actionLayout(action: Record<string, any>) {
    const notes = projectFlowNetworkNotes(action)
    const actionTables = Array.isArray(action.tables)
      ? action.tables.map((table: unknown) => String(table).trim()).filter(Boolean)
      : []
    const noteTableNames = new Set(notes.map((note) => projectFlowNetworkTableName(note)).filter(Boolean))
    const extraTables = actionTables.filter((table: string) => !noteTableNames.has(table))
    const relationshipCount = notes.reduce((total, note) => {
      const forms = projectFlowNetworkFormInstances(note)
      return total + Math.max(forms.length, projectFlowNetworkTableName(note, forms[0]) !== '' ? 1 : 0)
    }, 0) + extraTables.length
    const noteRows = Math.ceil(notes.length / noteColumns)

    return {
      notes,
      extraTables,
      relationshipCount,
      height: Math.max(96, noteRows * 56 + 16, relationshipCount * 70 + 16),
    }
  }

  function addActionCluster(action: Record<string, any>, actionId: string, parentId: string, top: number) {
    const layout = actionLayout(action)
    const actionY = top + (layout.height - 60) / 2
    let relationshipIndex = 0
    nodes.push({
      id: actionId,
      label: truncateFlowLabel(phaseField(action, 'label', 'Action'), 18),
      fullLabel: phaseField(action, 'label', 'Action'),
      kind: 'decision',
      type: phaseField(action, 'type', 'action'),
      responsibility: phaseField(action, 'backendAction', '') ? `Run ${phaseField(action, 'backendAction')} in ${phaseField(action, 'phpEntry', 'PHP entrypoint')}.` : `Execute ${phaseField(action, 'phaseTask', 'the connected UI / UX task')}.`,
      x: 800,
      y: actionY,
      width: 136,
      height: 60,
    })
    addEdge(parentId, actionId)

    layout.notes.forEach((note: Record<string, any>, noteIndex: number) => {
      const noteId = `${actionId}-note-${noteIndex}`
      const noteCode = phaseField(note, 'noteCode', `Note ${noteIndex + 1}`)
      const detail = projectFlowNetworkNoteDetail(note)
      const forms = projectFlowNetworkFormInstances(note)
      const tableName = projectFlowNetworkTableName(note, forms[0])
      const relationStart = relationshipIndex
      nodes.push({
        id: noteId,
        label: truncateFlowLabel(noteCode, 16),
        fullLabel: `${noteCode} — ${detail}`,
        kind: 'note',
        type: 'Implementation Note',
        responsibility: detail,
        x: noteX + (noteIndex % noteColumns) * notePitch,
        y: top + 8 + Math.floor(noteIndex / noteColumns) * 56,
        width: 104,
        height: 42,
      })
      addEdge(actionId, noteId)

      const formIds: string[] = []
      forms.forEach((form: Record<string, any>, formIndex: number) => {
        const formId = `${noteId}-form-${formIndex}`
        const fieldCount = projectFlowNetworkFormFieldCount(form)
        formIds.push(formId)
        nodes.push({
          id: formId,
          label: truncateFlowLabel(phaseField(form, 'form_name', `Form ${formIndex + 1}`), 20),
          fullLabel: phaseField(form, 'form_name', `Form ${formIndex + 1}`),
          kind: 'form',
          type: 'Form Builder',
          responsibility: `${fieldCount} proposed field${fieldCount === 1 ? '' : 's'} connected to ${noteCode}.`,
          x: relationFormX,
          y: top + 8 + relationshipIndex * 70,
          width: 142,
          height: 62,
        })
        addEdge(noteId, formId)
        relationshipIndex += 1
      })

      if (tableName !== '') {
        const tableId = `${noteId}-table`
        const fieldCount = projectFlowNetworkTableFieldCount(note, tableName)
        const relationSlot = forms.length > 0 ? relationStart + (forms.length - 1) / 2 : relationshipIndex++
        nodes.push({
          id: tableId,
          label: truncateFlowLabel(tableName, 20),
          fullLabel: tableName,
          kind: 'database',
          type: 'Database Table',
          responsibility: `${fieldCount} proposed field${fieldCount === 1 ? '' : 's'} connected to ${noteCode}.`,
          x: relationTableX,
          y: top + 10 + relationSlot * 70,
          width: 138,
          height: 58,
        })
        if (formIds.length > 0) {
          formIds.forEach((formId) => addEdge(formId, tableId))
        } else {
          addEdge(noteId, tableId)
        }
      }
    })

    layout.extraTables.forEach((tableName: string, tableIndex: number) => {
      const tableId = `${actionId}-table-${tableIndex}`
      nodes.push({
        id: tableId,
        label: truncateFlowLabel(tableName, 20),
        fullLabel: tableName,
        kind: 'database',
        type: 'Database Table',
        responsibility: `Documented table connected to ${phaseField(action, 'label', 'this action')}.`,
        x: relationTableX,
        y: top + 10 + relationshipIndex * 70,
        width: 138,
        height: 58,
      })
      relationshipIndex += 1
      addEdge(actionId, tableId)
    })

    return layout.height
  }

  let y = 12

  entries.forEach((entry, entryIndex) => {
    const entryId = `entry-${entryIndex}`
    const backendId = `backend-${entryIndex}`
    const hasBackend = phaseField(entry.backend, 'phpEntry') !== ''
    const entryActions = projectFlowActions(entry)
    const views = projectFlowViews(entry)
    const entryActionBlocks = entryActions.map((action) => actionLayout(action).height)
    const entryActionRowsHeight = entryActionBlocks.reduce((total, height) => total + height + 18, 0)
    const viewBlocks = views.map((view) => {
      const actions = projectFlowActions(view)
      return actions.length > 0
        ? actions.reduce((total, action) => total + actionLayout(action).height + 18, 0)
        : 96
    })
    const viewRowsHeight = Math.max(96, viewBlocks.reduce((total, blockHeight) => total + blockHeight + 18, 0))
    const viewStartY = y + 104 + entryActionRowsHeight
    const hasFlowContent = hasBackend || entryActions.length > 0 || views.length > 0
    const laneHeight = hasFlowContent ? Math.max(240, 122 + entryActionRowsHeight + viewRowsHeight) : 104

    nodes.push({
      id: entryId,
      label: truncateFlowLabel(`${phaseField(entry, 'label', 'Page')} ${phaseField(entry, 'route', '')}`, 30),
      fullLabel: `${phaseField(entry, 'label', 'Route')} ${phaseField(entry, 'route', '')}`.trim(),
      kind: 'terminator',
      type: 'Page Entrypoint',
      responsibility: phaseField(entry, 'owner', 'Open project route.'),
      x: 28,
      y: y + 18,
      width: 178,
      height: 52,
    })
    if (hasBackend) {
      nodes.push({
        id: backendId,
        label: truncateFlowLabel(phaseField(entry.backend, 'phpEntry'), 24),
        fullLabel: phaseField(entry.backend, 'phpEntry'),
        kind: 'document',
        type: 'PHP Entrypoint',
        responsibility: phaseField(entry.backend, 'responsibility', 'Prepare payload, handle backend actions, load Vite assets, and mount React.'),
        x: 292,
        y: y + 16,
        width: 176,
        height: 58,
      })
      addEdge(entryId, backendId)
    }

    if (entryActions.length > 0) {
      let nextEntryActionY = y + 96
      entryActions.forEach((action: Record<string, any>, actionIndex: number) => {
        const actionId = `entry-action-${entryIndex}-${actionIndex}`
        const targetId = routeNodeIds.get(phaseField(action, 'to')) || ''
        const actionHeight = addActionCluster(action, actionId, entryId, nextEntryActionY)
        nextEntryActionY += actionHeight + 18
        if (targetId !== '') {
          addEdge(actionId, targetId)
        }
        if (hasBackend && phaseField(action, 'backendAction', '') !== '') {
          addEdge(actionId, backendId)
        }

      })
    }

    let nextViewY = viewStartY
    views.forEach((view: Record<string, any>, viewIndex: number) => {
      const viewId = `view-${entryIndex}-${viewIndex}`
      const viewActions = projectFlowActions(view)
      const viewBlockHeight = viewBlocks[viewIndex] || 96
      const viewY = nextViewY + (viewBlockHeight - 58) / 2
      nextViewY += viewBlockHeight + 18
      nodes.push({
        id: viewId,
        label: truncateFlowLabel(phaseField(view, 'label', 'View'), 22),
        fullLabel: phaseField(view, 'label', 'View'),
        kind: 'process',
        type: 'Page View',
        responsibility: `Render ${phaseField(view, 'url', 'view route')} for ${phaseField(view, 'phaseTask', 'unmapped phase/task')}.`,
        x: 540,
        y: viewY,
        width: 168,
        height: 58,
      })
      addEdge(hasBackend ? backendId : entryId, viewId)

      let nextActionY = nextViewY - viewBlockHeight - 18
      viewActions.forEach((action: Record<string, any>, actionIndex: number) => {
        const actionId = `view-action-${entryIndex}-${viewIndex}-${actionIndex}`
        const actionTo = phaseField(action, 'to')
        const targetId = actionTo === phaseField(view, 'url') ? viewId : (routeNodeIds.get(actionTo) || '')
        const actionHeight = addActionCluster(action, actionId, viewId, nextActionY)
        nextActionY += actionHeight + 18
        if (targetId !== '') {
          addEdge(actionId, targetId)
        }
        if (hasBackend && phaseField(action, 'backendAction', '') !== '') {
          addEdge(actionId, backendId)
        }

      })
    })

    y += laneHeight + 34
  })

  return { nodes, edges, height: Math.max(360, y + 20) }
}

function projectFlowNodeCenter(node: ProjectFlowChartNode): { x: number; y: number } {
  return {
    x: node.x + node.width / 2,
    y: node.y + node.height / 2,
  }
}

function ProjectFlowSymbol({ node, isSelected, onPointerDown, onClick }: { node: ProjectFlowChartNode; isSelected: boolean; onPointerDown: (event: React.PointerEvent<SVGGElement>, node: ProjectFlowChartNode) => void; onClick: (node: ProjectFlowChartNode) => void }) {
  const labelX = node.x + node.width / 2
  const labelY = node.y + node.height / 2 + 3
  const symbolProps = {
    className: 'cursor-move select-none',
    'data-node-id': node.id,
    'data-node-kind': node.kind,
    role: 'button',
    tabIndex: 0,
    'aria-label': `${node.type}: ${node.fullLabel}`,
    onPointerDown: (event: React.PointerEvent<SVGGElement>) => onPointerDown(event, node),
    onClick: (event: React.MouseEvent<SVGGElement>) => {
      event.stopPropagation()
      onClick(node)
    },
    onKeyDown: (event: React.KeyboardEvent<SVGGElement>) => {
      if (event.key !== 'Enter' && event.key !== ' ') return
      event.preventDefault()
      onClick(node)
    },
  }
  const symbolClass = cn('fill-background', isSelected ? 'stroke-ring' : 'stroke-border')

  if (node.kind === 'terminator') {
    return (
      <g {...symbolProps}>
        <rect x={node.x} y={node.y} width={node.width} height={node.height} rx={node.height / 2} className={symbolClass} strokeWidth={isSelected ? 2 : 1} />
        <text x={labelX} y={labelY - 4} textAnchor="middle" className="fill-foreground text-[10px] font-medium">{node.label}</text>
        <text x={labelX} y={labelY + 11} textAnchor="middle" className="fill-muted-foreground text-[8px] uppercase">{truncateFlowLabel(node.type, 18)}</text>
      </g>
    )
  }

  if (node.kind === 'decision') {
    const points = [
      `${labelX},${node.y}`,
      `${node.x + node.width},${node.y + node.height / 2}`,
      `${labelX},${node.y + node.height}`,
      `${node.x},${node.y + node.height / 2}`,
    ].join(' ')

    return (
      <g {...symbolProps}>
        <polygon points={points} className={symbolClass} strokeWidth={isSelected ? 2 : 1} />
        <text x={labelX} y={labelY - 4} textAnchor="middle" className="fill-foreground text-[10px] font-medium">{node.label}</text>
        <text x={labelX} y={labelY + 11} textAnchor="middle" className="fill-muted-foreground text-[8px] uppercase">{truncateFlowLabel(node.type, 16)}</text>
      </g>
    )
  }

  if (node.kind === 'document') {
    const path = `M ${node.x} ${node.y} H ${node.x + node.width} V ${node.y + node.height - 12} Q ${node.x + node.width * 0.75} ${node.y + node.height + 8} ${node.x + node.width / 2} ${node.y + node.height - 2} Q ${node.x + node.width * 0.25} ${node.y + node.height - 12} ${node.x} ${node.y + node.height - 2} Z`

    return (
      <g {...symbolProps}>
        <path d={path} className={symbolClass} strokeWidth={isSelected ? 2 : 1} />
        <text x={labelX} y={labelY - 8} textAnchor="middle" className="fill-foreground text-[10px] font-medium">{node.label}</text>
        <text x={labelX} y={labelY + 7} textAnchor="middle" className="fill-muted-foreground text-[8px] uppercase">{truncateFlowLabel(node.type, 18)}</text>
      </g>
    )
  }

  if (node.kind === 'note') {
    const fold = 10
    const path = `M ${node.x} ${node.y} H ${node.x + node.width - fold} L ${node.x + node.width} ${node.y + fold} V ${node.y + node.height} H ${node.x} Z`

    return (
      <g {...symbolProps}>
        <path d={path} className={cn('fill-[#211a38]', isSelected ? 'stroke-white' : 'stroke-violet-300')} strokeWidth={isSelected ? 2 : 1.2} />
        <path d={`M ${node.x + node.width - fold} ${node.y} V ${node.y + fold} H ${node.x + node.width}`} className="fill-none stroke-violet-300" strokeWidth="1" />
        <circle cx={node.x + 11} cy={node.y + 12} r={3.5} className="fill-violet-300" />
        <text x={labelX + 4} y={labelY - 3} textAnchor="middle" className="fill-white text-[9px] font-medium">{node.label}</text>
        <text x={labelX} y={labelY + 10} textAnchor="middle" className="fill-violet-200 text-[7px] uppercase">Note</text>
      </g>
    )
  }

  if (node.kind === 'form') {
    return (
      <g {...symbolProps}>
        <rect x={node.x} y={node.y} width={node.width} height={node.height} rx={6} className={cn('fill-[#10243c]', isSelected ? 'stroke-white' : 'stroke-amber-300')} strokeWidth={isSelected ? 2 : 1.2} />
        <text x={labelX} y={node.y + 17} textAnchor="middle" className="fill-white text-[9px] font-medium">{node.label}</text>
        <line x1={node.x + 17} y1={node.y + 29} x2={node.x + node.width - 17} y2={node.y + 29} className="stroke-amber-200" strokeWidth="1.2" />
        <line x1={node.x + 17} y1={node.y + 39} x2={node.x + node.width - 29} y2={node.y + 39} className="stroke-amber-200" strokeWidth="1.2" />
        <line x1={node.x + 17} y1={node.y + 49} x2={node.x + node.width - 40} y2={node.y + 49} className="stroke-amber-200" strokeWidth="1.2" />
      </g>
    )
  }

  if (node.kind === 'database') {
    return (
      <g {...symbolProps}>
        <path d={`M ${node.x} ${node.y + 10} C ${node.x} ${node.y - 3} ${node.x + node.width} ${node.y - 3} ${node.x + node.width} ${node.y + 10} V ${node.y + node.height - 10} C ${node.x + node.width} ${node.y + node.height + 3} ${node.x} ${node.y + node.height + 3} ${node.x} ${node.y + node.height - 10} Z`} className={symbolClass} strokeWidth={isSelected ? 2 : 1} />
        <ellipse cx={labelX} cy={node.y + 10} rx={node.width / 2} ry={10} className={cn('fill-muted/30', isSelected ? 'stroke-ring' : 'stroke-border')} strokeWidth={isSelected ? 2 : 1} />
        <text x={labelX} y={labelY - 2} textAnchor="middle" className="fill-foreground text-[10px] font-medium">{node.label}</text>
        <text x={labelX} y={labelY + 13} textAnchor="middle" className="fill-muted-foreground text-[8px] uppercase">{truncateFlowLabel(node.type, 18)}</text>
      </g>
    )
  }

  return (
    <g {...symbolProps}>
      <rect x={node.x} y={node.y} width={node.width} height={node.height} rx={4} className={symbolClass} strokeWidth={isSelected ? 2 : 1} />
      <text x={labelX} y={labelY - 4} textAnchor="middle" className="fill-foreground text-[10px] font-medium">{node.label}</text>
      <text x={labelX} y={labelY + 11} textAnchor="middle" className="fill-muted-foreground text-[8px] uppercase">{truncateFlowLabel(node.type, 18)}</text>
    </g>
  )
}

type UiUxFlowSymbolProps = {
  x: number
  y: number
  width: number
  height: number
  className: string
  opacity?: number
  strokeWidth?: number
}

function UiUxProcessSymbol({ x, y, width, height, className, opacity, strokeWidth = 1.1 }: UiUxFlowSymbolProps) {
  return <rect x={x} y={y} width={width} height={height} rx="4" className={className} opacity={opacity} strokeWidth={strokeWidth} />
}

function UiUxPredefinedProcessSymbol({ x, y, width, height, className, opacity, strokeWidth = 1.1 }: UiUxFlowSymbolProps) {
  return (
    <>
      <rect x={x} y={y} width={width} height={height} rx="4" className={className} opacity={opacity} strokeWidth={strokeWidth} />
      <line x1={x + 14} y1={y + 5} x2={x + 14} y2={y + height - 5} className="stroke-primary" strokeWidth="1" opacity="0.8" />
      <line x1={x + width - 14} y1={y + 5} x2={x + width - 14} y2={y + height - 5} className="stroke-primary" strokeWidth="1" opacity="0.8" />
    </>
  )
}

function UiUxDocumentSymbol({ x, y, width, height, className, opacity, strokeWidth = 1.1 }: UiUxFlowSymbolProps) {
  const path = `M ${x} ${y} H ${x + width} V ${y + height - 12} Q ${x + width * 0.75} ${y + height + 6} ${x + width / 2} ${y + height - 2} Q ${x + width * 0.25} ${y + height - 10} ${x} ${y + height - 2} Z`

  return <path d={path} className={className} opacity={opacity} strokeWidth={strokeWidth} />
}

function UiUxDatabaseSymbol({ x, y, width, height, className, opacity, strokeWidth = 1.1 }: UiUxFlowSymbolProps) {
  return (
    <>
      <path
        d={`M ${x} ${y + 10} C ${x} ${y - 3} ${x + width} ${y - 3} ${x + width} ${y + 10} V ${y + height - 10} C ${x + width} ${y + height + 3} ${x} ${y + height + 3} ${x} ${y + height - 10} Z`}
        className={className}
        opacity={opacity}
        strokeWidth={strokeWidth}
      />
      <ellipse cx={x + width / 2} cy={y + 10} rx={width / 2} ry={10} className="fill-muted/30 stroke-border" strokeWidth={strokeWidth} />
    </>
  )
}

function UiUxFormSymbol({ x, y, width, height, className, opacity, strokeWidth = 1.1 }: UiUxFlowSymbolProps) {
  return (
    <g opacity={opacity}>
      <rect x={x} y={y} width={width} height={height} rx={6} className={className} strokeWidth={strokeWidth} />
      <line x1={x + 13} y1={y + 22} x2={x + width - 13} y2={y + 22} className="stroke-border" strokeWidth="1" opacity="0.9" />
      <rect x={x + 14} y={y + 32} width={width - 28} height="8" rx="4" className="fill-muted stroke-border" strokeWidth="0.8" />
      <rect x={x + 14} y={y + 46} width={width - 28} height="8" rx="4" className="fill-muted stroke-border" strokeWidth="0.8" />
      <rect x={x + 14} y={y + 60} width={Math.max(42, width * 0.48)} height="8" rx="4" className="fill-muted stroke-border" strokeWidth="0.8" />
    </g>
  )
}

function ProjectFlowCanvas({ entries, totalViews, totalActions, sourcePath }: { entries: Array<Record<string, any>>; totalViews: number; totalActions: number; sourcePath: string }) {
  const autoChart = React.useMemo(() => buildProjectFlowChart(entries), [entries])
  const [positions, setPositions] = React.useState<Record<string, ProjectFlowNodePosition>>(() => readProjectFlowLayout())
  const [selectedNodeId, setSelectedNodeId] = React.useState('')
  const dragRef = React.useRef<{
    nodeId: string
    offsetX: number
    offsetY: number
    originX: number
    originY: number
    linked: Array<{ nodeId: string; x: number; y: number }>
  } | null>(null)
  const panRef = React.useRef<{
    startX: number
    startY: number
    originX: number
    originY: number
    moved: boolean
  } | null>(null)
  const suppressCanvasClickRef = React.useRef(false)
  const svgRef = React.useRef<SVGSVGElement>(null)
  const chart = React.useMemo(() => {
    const nodes = autoChart.nodes.map((node) => {
      const position = positions[node.id]

      return position ? { ...node, x: position.x, y: position.y } : node
    })
    const width = nodes.length > 0 ? Math.max(1240, ...nodes.map((node) => node.x + node.width)) : 1240
    const height = nodes.length > 0 ? Math.max(...nodes.map((node) => node.y + node.height)) : autoChart.height

    return { ...autoChart, nodes, width, height }
  }, [autoChart, positions])
  const nodesById = new Map(chart.nodes.map((node) => [node.id, node]))
  const nodesRef = React.useRef(chart.nodes)
  nodesRef.current = chart.nodes
  const initialFitRef = React.useRef(false)
  const [viewport, setViewport] = React.useState({ x: 0, y: 0, scale: 1 })
  const [isPanning, setIsPanning] = React.useState(false)

  React.useEffect(() => {
    writeProjectFlowLayout(positions)
  }, [positions])

  function directProjectFlowChildren(nodeId: string): Array<ProjectFlowChartNode> {
    const childMatches: Array<(candidateId: string) => boolean> = []
    const entryMatch = nodeId.match(/^entry-(\d+)$/)
    const backendMatch = nodeId.match(/^backend-(\d+)$/)
    const viewMatch = nodeId.match(/^view-(\d+)-(\d+)$/)
    const entryActionMatch = nodeId.match(/^entry-action-(\d+)-(\d+)$/)
    const viewActionMatch = nodeId.match(/^view-action-(\d+)-(\d+)-(\d+)$/)
    const entryNoteMatch = nodeId.match(/^entry-action-(\d+)-(\d+)-note-(\d+)$/)
    const viewNoteMatch = nodeId.match(/^view-action-(\d+)-(\d+)-(\d+)-note-(\d+)$/)
    const entryFormMatch = nodeId.match(/^entry-action-(\d+)-(\d+)-note-(\d+)-form-(\d+)$/)
    const viewFormMatch = nodeId.match(/^view-action-(\d+)-(\d+)-(\d+)-note-(\d+)-form-(\d+)$/)

    if (entryMatch) {
      childMatches.push(
        (candidateId) => candidateId === `backend-${entryMatch[1]}`,
        (candidateId) => new RegExp(`^entry-action-${entryMatch[1]}-\\d+$`).test(candidateId),
        (candidateId) => new RegExp(`^view-${entryMatch[1]}-\\d+$`).test(candidateId),
      )
    } else if (backendMatch) {
      childMatches.push((candidateId) => new RegExp(`^view-${backendMatch[1]}-\\d+$`).test(candidateId))
    } else if (viewMatch) {
      childMatches.push((candidateId) => new RegExp(`^view-action-${viewMatch[1]}-${viewMatch[2]}-\\d+$`).test(candidateId))
    } else if (entryActionMatch) {
      childMatches.push(
        (candidateId) => new RegExp(`^entry-action-${entryActionMatch[1]}-${entryActionMatch[2]}-note-\\d+$`).test(candidateId),
        (candidateId) => new RegExp(`^entry-action-${entryActionMatch[1]}-${entryActionMatch[2]}-table-\\d+$`).test(candidateId),
      )
    } else if (viewActionMatch) {
      childMatches.push(
        (candidateId) => new RegExp(`^view-action-${viewActionMatch[1]}-${viewActionMatch[2]}-${viewActionMatch[3]}-note-\\d+$`).test(candidateId),
        (candidateId) => new RegExp(`^view-action-${viewActionMatch[1]}-${viewActionMatch[2]}-${viewActionMatch[3]}-table-\\d+$`).test(candidateId),
      )
    } else if (entryNoteMatch || viewNoteMatch) {
      childMatches.push(
        (candidateId) => new RegExp(`^${nodeId}-form-\\d+$`).test(candidateId),
        (candidateId) => candidateId === `${nodeId}-table`,
      )
    } else if (entryFormMatch || viewFormMatch) {
      const noteId = nodeId.replace(/-form-\d+$/, '')
      childMatches.push((candidateId) => candidateId === `${noteId}-table`)
    }

    return chart.nodes.filter((candidate) => childMatches.some((matches) => matches(candidate.id)))
  }

  function linkedProjectFlowNodes(nodeId: string): Array<ProjectFlowChartNode> {
    const linked: ProjectFlowChartNode[] = []
    const visited = new Set([nodeId])
    const queue = [nodeId]

    while (queue.length > 0) {
      const currentNodeId = queue.shift()
      if (!currentNodeId) continue

      directProjectFlowChildren(currentNodeId).forEach((child) => {
        if (visited.has(child.id)) return
        visited.add(child.id)
        linked.push(child)
        queue.push(child.id)
      })
    }

    return linked
  }

  const svgViewportClientPoint = React.useCallback((clientX: number, clientY: number) => {
    const svg = svgRef.current
    if (!svg) return { x: 0, y: 0 }

    const screenMatrix = svg.getScreenCTM()
    if (screenMatrix) {
      const point = svg.createSVGPoint()
      point.x = clientX
      point.y = clientY
      const transformedPoint = point.matrixTransform(screenMatrix.inverse())
      return { x: transformedPoint.x, y: transformedPoint.y }
    }

    const rect = svg.getBoundingClientRect()
    return {
      x: ((clientX - rect.left) / rect.width) * chart.width,
      y: ((clientY - rect.top) / rect.height) * chart.height,
    }
  }, [chart.height, chart.width])

  function svgViewportPoint(event: React.PointerEvent<SVGSVGElement | SVGGElement>) {
    return svgViewportClientPoint(event.clientX, event.clientY)
  }

  function svgPointerPoint(event: React.PointerEvent<SVGSVGElement | SVGGElement>) {
    const rawPoint = svgViewportPoint(event)

    return {
      x: (rawPoint.x - viewport.x) / viewport.scale,
      y: (rawPoint.y - viewport.y) / viewport.scale,
    }
  }

  const fitViewport = React.useCallback(() => {
    const svg = svgRef.current
    const surface = svg?.parentElement
    if (!surface || nodesRef.current.length === 0) return
    const rect = surface.getBoundingClientRect()
    const bounds = nodesRef.current.reduce((result, node) => ({
      minX: Math.min(result.minX, node.x),
      minY: Math.min(result.minY, node.y),
      maxX: Math.max(result.maxX, node.x + node.width),
      maxY: Math.max(result.maxY, node.y + node.height),
    }), { minX: Number.POSITIVE_INFINITY, minY: Number.POSITIVE_INFINITY, maxX: Number.NEGATIVE_INFINITY, maxY: Number.NEGATIVE_INFINITY })
    const padding = 96
    const contentWidth = Math.max(1, bounds.maxX - bounds.minX)
    const contentHeight = Math.max(1, bounds.maxY - bounds.minY)
    const contentCenterX = (bounds.minX + bounds.maxX) / 2
    const contentCenterY = (bounds.minY + bounds.maxY) / 2
    const scale = Math.min(1, Math.max(0.18, Math.min((rect.width - padding) / contentWidth, (rect.height - padding) / contentHeight)))
    setViewport({
      scale,
      x: chart.width / 2 - contentCenterX * scale,
      y: chart.height / 2 - contentCenterY * scale,
    })
  }, [chart.height, chart.width])

  function zoomAt(nextScale: number) {
    setViewport((current) => {
      const scale = Math.min(2.5, Math.max(0.18, nextScale))
      const centerX = chart.width / 2
      const centerY = chart.height / 2
      const contentX = (centerX - current.x) / current.scale
      const contentY = (centerY - current.y) / current.scale

      return {
        scale,
        x: centerX - contentX * scale,
        y: centerY - contentY * scale,
      }
    })
  }

  React.useEffect(() => {
    if (initialFitRef.current) return
    initialFitRef.current = true
    const frame = window.requestAnimationFrame(fitViewport)
    return () => window.cancelAnimationFrame(frame)
  }, [fitViewport])

  React.useEffect(() => {
    const svg = svgRef.current
    if (!svg) return

    function handleWheel(event: WheelEvent) {
      event.preventDefault()
      const pointer = svgViewportClientPoint(event.clientX, event.clientY)
      const pixelDelta = event.deltaMode === WheelEvent.DOM_DELTA_LINE
        ? event.deltaY * 16
        : event.deltaMode === WheelEvent.DOM_DELTA_PAGE
          ? event.deltaY * svg!.clientHeight
          : event.deltaY
      const boundedDelta = Math.max(-240, Math.min(240, pixelDelta))
      const zoomFactor = Math.exp(-boundedDelta * 0.0015)

      setViewport((current) => {
        const scale = Math.min(2.5, Math.max(0.18, current.scale * zoomFactor))
        const contentX = (pointer.x - current.x) / current.scale
        const contentY = (pointer.y - current.y) / current.scale

        return {
          scale,
          x: pointer.x - contentX * scale,
          y: pointer.y - contentY * scale,
        }
      })
    }

    svg.addEventListener('wheel', handleWheel, { passive: false })
    return () => svg.removeEventListener('wheel', handleWheel)
  }, [svgViewportClientPoint])

  function handleNodePointerDown(event: React.PointerEvent<SVGGElement>, node: ProjectFlowChartNode) {
    event.preventDefault()
    event.stopPropagation()
    panRef.current = null
    setIsPanning(false)
    const point = svgPointerPoint(event)
    dragRef.current = {
      nodeId: node.id,
      offsetX: point.x - node.x,
      offsetY: point.y - node.y,
      originX: node.x,
      originY: node.y,
      linked: linkedProjectFlowNodes(node.id).map((linkedNode) => ({
        nodeId: linkedNode.id,
        x: linkedNode.x,
        y: linkedNode.y,
      })),
    }
    event.currentTarget.setPointerCapture(event.pointerId)
  }

  function handleSvgPointerDown(event: React.PointerEvent<SVGSVGElement>) {
    if (event.pointerType === 'mouse' && event.button !== 0) return
    event.preventDefault()
    const point = svgViewportPoint(event)
    dragRef.current = null
    panRef.current = {
      startX: point.x,
      startY: point.y,
      originX: viewport.x,
      originY: viewport.y,
      moved: false,
    }
    setIsPanning(true)
    event.currentTarget.setPointerCapture(event.pointerId)
  }

  function handleSvgPointerMove(event: React.PointerEvent<SVGSVGElement>) {
    const drag = dragRef.current
    const pan = panRef.current
    if (!drag && pan) {
      const point = svgViewportPoint(event)
      const deltaX = point.x - pan.startX
      const deltaY = point.y - pan.startY
      if (Math.abs(deltaX) > 2 || Math.abs(deltaY) > 2) pan.moved = true
      setViewport((current) => ({
        ...current,
        x: pan.originX + deltaX,
        y: pan.originY + deltaY,
      }))
      return
    }
    if (!drag) return

    const node = nodesById.get(drag.nodeId)
    if (!node) return

    const point = svgPointerPoint(event)
    const nextX = Math.max(0, point.x - drag.offsetX)
    const nextY = Math.max(0, point.y - drag.offsetY)
    const deltaX = nextX - drag.originX
    const deltaY = nextY - drag.originY

    setPositions((current) => {
      const nextPositions = {
        ...current,
        [drag.nodeId]: { x: Math.round(nextX), y: Math.round(nextY) },
      }

      drag.linked.forEach((linkedNode) => {
        nextPositions[linkedNode.nodeId] = {
          x: Math.max(0, Math.round(linkedNode.x + deltaX)),
          y: Math.max(0, Math.round(linkedNode.y + deltaY)),
        }
      })

      return nextPositions
    })
  }

  function handleSvgPointerUp() {
    const pan = panRef.current
    if (pan?.moved) {
      suppressCanvasClickRef.current = true
      window.requestAnimationFrame(() => {
        suppressCanvasClickRef.current = false
      })
    }
    dragRef.current = null
    panRef.current = null
    setIsPanning(false)
  }

  function handleCanvasClick() {
    if (suppressCanvasClickRef.current) return
    setSelectedNodeId('')
  }

  function resetLayout() {
    dragRef.current = null
    panRef.current = null
    setIsPanning(false)
    setPositions({})
    setSelectedNodeId('')
    window.requestAnimationFrame(() => window.requestAnimationFrame(fitViewport))
  }
  const selectedNode = selectedNodeId ? nodesById.get(selectedNodeId) : null
  const nodeCounts = chart.nodes.reduce<Record<string, number>>((counts, node) => {
    counts[node.kind] = (counts[node.kind] || 0) + 1
    return counts
  }, {})

  return (
    <Card className="min-w-0 overflow-hidden border-border/80 shadow-sm">
      <CardHeader className="flex min-w-0 min-h-16 flex-col gap-3 border-b bg-muted/20 py-3 lg:flex-row lg:items-center lg:justify-between">
        <div className="min-w-0">
          <Badge variant="secondary">Data Structure V1</Badge>
          <CardTitle className="mt-1 text-base tracking-normal">Page Connection Map</CardTitle>
          <CardDescription className="mt-1 max-w-4xl text-xs">Route, phase, task, note, Form Builder, and database connections. Drag empty canvas to pan, scroll to zoom, or drag a symbol to move its branch.</CardDescription>
        </div>
        <div className="flex min-w-0 max-w-full flex-wrap items-center justify-start gap-2 text-xs text-muted-foreground lg:justify-end">
          <Badge variant="outline">{entries.length} Entrypoints</Badge>
          <Badge variant="outline">{totalViews} Views</Badge>
          <Badge variant="outline">{totalActions} Actions</Badge>
          <Badge variant="outline">{nodeCounts.note || 0} Notes</Badge>
          <Badge variant="outline">{nodeCounts.form || 0} Forms</Badge>
          <Badge variant="outline">{nodeCounts.database || 0} Tables</Badge>
          <Badge variant="outline">{chart.nodes.length} Nodes</Badge>
          <Badge variant="outline">{chart.edges.length} Links</Badge>
          <Separator orientation="vertical" className="hidden data-vertical:h-6 lg:block" />
          <Tooltip>
            <TooltipTrigger
              render={
                <Button type="button" variant="outline" size="icon-sm" aria-label="Reset Layout" onClick={resetLayout} />
              }
            >
              <RotateCcw />
            </TooltipTrigger>
            <TooltipContent>Reset Layout</TooltipContent>
          </Tooltip>
          <Tooltip>
            <TooltipTrigger
              render={<Button type="button" variant="outline" size="icon-sm" aria-label="Zoom out" onClick={() => zoomAt(viewport.scale * 0.85)} />}
            >
              <ZoomOut />
            </TooltipTrigger>
            <TooltipContent>Zoom Out</TooltipContent>
          </Tooltip>
          <span className="min-w-12 text-center text-xs text-muted-foreground">{Math.round(viewport.scale * 100)}%</span>
          <Tooltip>
            <TooltipTrigger
              render={<Button type="button" variant="outline" size="icon-sm" aria-label="Zoom in" onClick={() => zoomAt(viewport.scale * 1.15)} />}
            >
              <ZoomIn />
            </TooltipTrigger>
            <TooltipContent>Zoom In</TooltipContent>
          </Tooltip>
          <Button type="button" variant="outline" size="sm" onClick={fitViewport}><Frame />Fit map</Button>
        </div>
      </CardHeader>
      <CardContent className="p-0">
        <div className="grid min-w-0 bg-[#101726] lg:grid-cols-[minmax(0,1fr)_280px]">
          <div className="relative h-[calc(100vh-350px)] min-h-[360px] min-w-0 overflow-hidden bg-[radial-gradient(circle_at_50%_48%,rgba(31,51,87,0.82)_0%,rgba(20,36,63,0.74)_58%,#0b1020_100%)]">
          <svg
            ref={svgRef}
            width="100%"
            height="100%"
            viewBox={`0 0 ${chart.width} ${chart.height}`}
            preserveAspectRatio="xMidYMid meet"
            role="img"
            aria-label="Project flowchart canvas"
            className={cn('h-full w-full touch-none', isPanning ? 'cursor-grabbing' : 'cursor-grab')}
            onPointerDown={handleSvgPointerDown}
            onPointerMove={handleSvgPointerMove}
            onPointerUp={handleSvgPointerUp}
            onPointerCancel={handleSvgPointerUp}
            onPointerLeave={handleSvgPointerUp}
            onClick={handleCanvasClick}
          >
            <defs>
              <marker id="flow-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto" markerUnits="strokeWidth">
                <path d="M 0 0 L 8 4 L 0 8 z" fill="#83a6d9" />
              </marker>
            </defs>
            <rect width={chart.width} height={chart.height} fill="transparent" />
            <g transform={`translate(${viewport.x} ${viewport.y}) scale(${viewport.scale})`}>
            {chart.edges.map((edge) => {
              const from = nodesById.get(edge.from)
              const to = nodesById.get(edge.to)
              if (!from || !to) return null
              const fromCenter = projectFlowNodeCenter(from)
              const toCenter = projectFlowNodeCenter(to)
              const startX = fromCenter.x < toCenter.x ? from.x + from.width : from.x
              const endX = fromCenter.x < toCenter.x ? to.x : to.x + to.width

              return (
                <path
                  key={edge.id}
                  d={`M ${startX} ${fromCenter.y} C ${(startX + endX) / 2} ${fromCenter.y}, ${(startX + endX) / 2} ${toCenter.y}, ${endX} ${toCenter.y}`}
                  className="fill-none stroke-[#5f7fb8]"
                  strokeOpacity="0.62"
                  strokeWidth="1.25"
                  markerEnd="url(#flow-arrow)"
                />
              )
            })}
            {chart.nodes.map((node) => (
              <ProjectFlowSymbol
                key={node.id}
                node={node}
                isSelected={selectedNodeId === node.id}
                onPointerDown={handleNodePointerDown}
                onClick={(clickedNode) => setSelectedNodeId(clickedNode.id)}
              />
            ))}
            </g>
          </svg>
          </div>
          <aside className="min-w-0 overflow-y-auto border-t border-white/10 bg-[#0b1020]/90 p-4 text-slate-200 lg:border-l lg:border-t-0">
            <div className="flex items-center gap-2">
              <Frame className="text-sky-300" />
              <h3 className="text-sm font-semibold tracking-normal">Selected Node</h3>
            </div>
            <div className="mt-4 rounded-md border border-white/10 bg-white/[0.04] p-3">
              <p className="text-base font-semibold text-white">{selectedNode?.fullLabel || 'Project flow'}</p>
              <p className="mt-1 text-xs uppercase text-sky-200">{selectedNode?.type || 'Map overview'}</p>
              <p className="mt-3 text-sm leading-6 text-slate-300">{selectedNode?.responsibility || 'Select a route, phase, task, note, form, or table symbol to inspect its responsibility.'}</p>
            </div>
            <div className="mt-4 grid gap-2 text-xs text-slate-300">
              <div className="flex min-w-0 flex-wrap items-start justify-between gap-2 rounded-md border border-white/10 px-3 py-2"><span className="shrink-0">Source</span><span className="min-w-0 break-all text-right font-mono text-sky-200">{sourcePath}</span></div>
              <div className="flex items-center justify-between rounded-md border border-white/10 px-3 py-2"><span>Entrypoints</span><span>{entries.length}</span></div>
              <div className="flex items-center justify-between rounded-md border border-white/10 px-3 py-2"><span>Views</span><span>{totalViews}</span></div>
              <div className="flex items-center justify-between rounded-md border border-white/10 px-3 py-2"><span>Actions</span><span>{totalActions}</span></div>
              <div className="flex items-center justify-between rounded-md border border-white/10 px-3 py-2"><span>Notes</span><span>{nodeCounts.note || 0}</span></div>
              <div className="flex items-center justify-between rounded-md border border-white/10 px-3 py-2"><span>Forms</span><span>{nodeCounts.form || 0}</span></div>
              <div className="flex items-center justify-between rounded-md border border-white/10 px-3 py-2"><span>Tables</span><span>{nodeCounts.database || 0}</span></div>
            </div>
          </aside>
        </div>
      </CardContent>
    </Card>
  )
}

type ProjectFlowNetworkNode = {
  id: string
  label: string
  detail: string
  kind: 'root' | 'entry' | 'view' | 'action' | 'note' | 'form' | 'table'
  x: number
  y: number
  radius: number
  orbitAngle?: number
  orbitRadius?: number
  orbitYScale?: number
  depth?: number
}

type ProjectFlowNetworkEdge = {
  id: string
  from: string
  to: string
  kind: 'primary' | 'secondary'
}

function projectFlowNetworkNodeBox(node: ProjectFlowNetworkNode): { width: number; height: number } {
  if (node.kind === 'root') return { width: 168, height: 58 }
  if (node.kind === 'entry') return { width: 42, height: 42 }
  if (node.kind === 'view') return { width: 144, height: 58 }
  if (node.kind === 'note') return { width: 24, height: 24 }
  if (node.kind === 'form' || node.kind === 'table') return { width: 42, height: 42 }
  return { width: 138, height: 58 }
}

function projectFlowNetworkLabelLines(value: string, maxLength = 18): string[] {
  const clean = value.trim()
  if (clean.length <= maxLength) return [clean]

  const words = clean.split(/\s+/)
  const lines: string[] = []
  let current = ''
  words.forEach((word) => {
    const next = current === '' ? word : `${current} ${word}`
    if (current !== '' && next.length > maxLength && lines.length < 2) {
      lines.push(current)
      current = word
    } else {
      current = next
    }
  })
  if (current !== '') lines.push(current)

  if (lines.length > 2) {
    lines.length = 2
    lines[1] = `${lines[1].slice(0, Math.max(1, maxLength - 3)).trimEnd()}...`
  }

  return lines
}

function projectFlowNetworkEdgePoint(node: ProjectFlowNetworkNode, target: ProjectFlowNetworkNode): { x: number; y: number } {
  const box = projectFlowNetworkNodeBox(node)
  const dx = target.x - node.x
  const dy = target.y - node.y
  const scale = 0.5 / Math.max(Math.abs(dx) / box.width, Math.abs(dy) / box.height, 0.0001)

  return {
    x: node.x + dx * scale,
    y: node.y + dy * scale,
  }
}

function projectFlowNetworkNodesOverlap(first: ProjectFlowNetworkNode, second: ProjectFlowNetworkNode, gap = 0): boolean {
  const firstBox = projectFlowNetworkNodeBox(first)
  const secondBox = projectFlowNetworkNodeBox(second)

  return Math.abs(first.x - second.x) < (firstBox.width + secondBox.width) / 2 + gap
    && Math.abs(first.y - second.y) < (firstBox.height + secondBox.height) / 2 + gap
}

function projectFlowNetworkHasOverlap(nodes: ProjectFlowNetworkNode[]): boolean {
  for (let firstIndex = 0; firstIndex < nodes.length; firstIndex += 1) {
    for (let secondIndex = firstIndex + 1; secondIndex < nodes.length; secondIndex += 1) {
      if (projectFlowNetworkNodesOverlap(nodes[firstIndex], nodes[secondIndex])) return true
    }
  }

  return false
}

function projectFlowNetworkNotes(record: Record<string, any>): Array<Record<string, any>> {
  return Array.isArray(record.notes)
    ? record.notes.filter((note: Record<string, any>) => !uiUxFlowRecordIsDeleted(note))
    : []
}

function projectFlowNetworkFormInstances(note: Record<string, any>): Array<Record<string, any>> {
  if (phaseField(note, 'formStatus', 'ACTIVE').toUpperCase() === 'DELETED') return []

  const payload = note.formAiPayload && typeof note.formAiPayload === 'object' && !Array.isArray(note.formAiPayload)
    ? note.formAiPayload
    : {}
  const saved = Array.isArray(payload.form_instances)
    ? payload.form_instances.filter((instance: unknown) => instance && typeof instance === 'object' && !Array.isArray(instance))
    : []
  if (saved.length > 0) return saved as Array<Record<string, any>>

  const enabled = note.formEnabled === true || phaseField(note, 'formEnabled') === '1'
  return enabled || Object.keys(payload).length > 0 ? [payload] : []
}

function projectFlowNetworkTableName(note: Record<string, any>, form?: Record<string, any>): string {
  const target = phaseField(note, 'crudTargetTable', 'NONE')
  if (target === 'NEW') return phaseField(note, 'crudNewTableName')
  if (target !== '' && target !== 'NONE') return target

  return phaseField(form, 'database_table') || phaseField(note?.formAiPayload, 'database_table')
}

function projectFlowNetworkTableFieldCount(note: Record<string, any>, tableName: string): number {
  const suggestions = Array.isArray(note?.crudAiPayload?.table_suggestions) ? note.crudAiPayload.table_suggestions : []
  const suggestion = suggestions.find((item: Record<string, any>) => phaseField(item, 'table_name') === tableName) || suggestions[0]
  const fields = Array.isArray(suggestion?.fields) ? suggestion.fields : []

  return fields.length
}

function projectFlowNetworkFormFieldCount(form: Record<string, any>): number {
  if (Array.isArray(form.fields)) return form.fields.length
  const rows = Array.isArray(form?.builder_layout?.rows) ? form.builder_layout.rows : []

  return rows.reduce((total: number, row: Record<string, any>) => total + (Array.isArray(row.fields) ? row.fields.length : 0), 0)
}

function projectFlowNetworkNoteDetail(note: Record<string, any>): string {
  const text = phaseField(note, 'noteTitle') || phaseField(note, 'description') || phaseField(note, 'label')
  const goal = text.match(/##\s*Goal\s*\n+([^\n]+)/i)?.[1]

  return (goal || text.replace(/^#+\s*/gm, '').split(/\n+/).find((line) => line.trim() !== '') || 'UI / UX implementation note').trim()
}

function buildProjectFlowNetwork(entries: Array<Record<string, any>>): { nodes: ProjectFlowNetworkNode[]; edges: ProjectFlowNetworkEdge[]; width: number; height: number } {
  const width = 1660
  const height = 1360
  const centerX = width / 2
  const centerY = height / 2
  const orbitYScale = 0.78
  const nodes: ProjectFlowNetworkNode[] = []
  const edges: ProjectFlowNetworkEdge[] = []
  const viewsWithEntry = entries.flatMap((entry, entryIndex) => projectFlowViews(entry).map((view, viewIndex) => ({ entry, entryIndex, view, viewIndex })))
  const totalViews = Math.max(1, viewsWithEntry.length)
  let globalViewIndex = 0

  const orbitalNode = (node: Omit<ProjectFlowNetworkNode, 'x' | 'y' | 'depth'>, angle: number, radius: number): ProjectFlowNetworkNode => ({
    ...node,
    orbitAngle: angle,
    orbitRadius: radius,
    orbitYScale,
    x: centerX + Math.cos(angle) * radius,
    y: centerY + Math.sin(angle) * radius * orbitYScale,
    depth: Math.sin(angle),
  })

  nodes.push({
    id: 'root',
    label: phaseData?.softwareName || 'BuilderX',
    detail: 'Complete UI / UX neural data structure',
    kind: 'root',
    x: centerX,
    y: centerY,
    radius: 6,
    depth: 1,
  })

  entries.forEach((entry, entryIndex) => {
    const entryId = `network-entry-${entryIndex}`
    const entryAngle = -Math.PI / 2 + (Math.PI * 2 * entryIndex) / Math.max(1, entries.length)
    nodes.push(orbitalNode({
      id: entryId,
      label: truncateFlowLabel(phaseField(entry, 'label', 'Entrypoint'), 22),
      detail: phaseField(entry, 'route', '/'),
      kind: 'entry',
      radius: 3.5,
    }, entryAngle, 135))
    edges.push({ id: `network-root-${entryId}`, from: 'root', to: entryId, kind: 'primary' })

    projectFlowViews(entry).forEach((view: Record<string, any>, viewIndex: number) => {
      const viewId = `network-view-${entryIndex}-${viewIndex}`
      const viewAngle = -Math.PI / 2 + (Math.PI * 2 * globalViewIndex) / totalViews
      const actions = projectFlowActions(view)
      globalViewIndex += 1
      nodes.push(orbitalNode({
        id: viewId,
        label: truncateFlowLabel(phaseField(view, 'label', 'Phase'), 24),
        detail: phaseField(view, 'phaseTask') || phaseField(view, 'url', ''),
        kind: 'view',
        radius: 3,
      }, viewAngle, 250))
      edges.push({ id: `network-${entryId}-${viewId}`, from: entryId, to: viewId, kind: 'primary' })

      actions.forEach((action: Record<string, any>, actionIndex: number) => {
        const actionId = `network-action-${entryIndex}-${viewIndex}-${actionIndex}`
        const actionAngle = viewAngle + (actionIndex - (actions.length - 1) / 2) * 0.12
        const notes = projectFlowNetworkNotes(action)
        const actionTables = Array.isArray(action.tables)
          ? action.tables.map((table: unknown) => String(table).trim()).filter(Boolean)
          : []
        const noteTableNames = new Set(notes.map((note) => projectFlowNetworkTableName(note)).filter(Boolean))
        const extraTables = actionTables.filter((table: string) => !noteTableNames.has(table))
        const relationshipCount = notes.reduce((total, note) => {
          const forms = projectFlowNetworkFormInstances(note)
          return total + Math.max(forms.length, projectFlowNetworkTableName(note, forms[0]) !== '' ? 1 : 0)
        }, 0) + extraTables.length
        const relationshipSpan = Math.min(0.7, Math.max(0.2, relationshipCount * 0.18))
        let relationshipIndex = 0

        nodes.push(orbitalNode({
          id: actionId,
          label: truncateFlowLabel(phaseField(action, 'label', 'Task'), 22),
          detail: phaseField(action, 'phaseTask') || phaseField(action, 'type', 'task'),
          kind: 'action',
          radius: 2.5,
        }, actionAngle, 420))
        edges.push({ id: `network-${viewId}-${actionId}`, from: viewId, to: actionId, kind: 'secondary' })

        const noteRingCounts = [0, 1, 2].map((ringIndex) => notes.filter((_note, noteIndex) => noteIndex % 3 === ringIndex).length)
        notes.forEach((note: Record<string, any>, noteIndex: number) => {
          const noteId = `network-note-${entryIndex}-${viewIndex}-${actionIndex}-${noteIndex}`
          const ringIndex = noteIndex % 3
          const ringSlot = Math.floor(noteIndex / 3)
          const ringCount = Math.max(1, noteRingCounts[ringIndex])
          const sectorSpan = (Math.PI * 2) / totalViews - 0.2
          const noteAngle = actionAngle - sectorSpan / 2 + sectorSpan * (ringSlot + 1) / (ringCount + 1)
          const noteRadius = 520 + ringIndex * 55
          const forms = projectFlowNetworkFormInstances(note)
          const tableName = projectFlowNetworkTableName(note, forms[0])
          const relationStart = relationshipIndex

          nodes.push(orbitalNode({
            id: noteId,
            label: truncateFlowLabel(phaseField(note, 'noteCode', `Note ${noteIndex + 1}`), 24),
            detail: projectFlowNetworkNoteDetail(note),
            kind: 'note',
            radius: 2.5,
          }, noteAngle, noteRadius))
          edges.push({ id: `network-${actionId}-${noteId}`, from: actionId, to: noteId, kind: 'secondary' })

          const formIds: string[] = []
          forms.forEach((form: Record<string, any>, formIndex: number) => {
            const formId = `network-form-${entryIndex}-${viewIndex}-${actionIndex}-${noteIndex}-${formIndex}`
            const relationAngle = actionAngle - relationshipSpan / 2 + relationshipSpan * (relationshipIndex + 0.5) / Math.max(1, relationshipCount)
            const fieldCount = projectFlowNetworkFormFieldCount(form)
            formIds.push(formId)
            nodes.push(orbitalNode({
              id: formId,
              label: truncateFlowLabel(phaseField(form, 'form_name', `Form ${formIndex + 1}`), 28),
              detail: `${fieldCount} proposed field${fieldCount === 1 ? '' : 's'}${phaseField(form, 'platform') ? ` · ${phaseField(form, 'platform')}` : ''}`,
              kind: 'form',
              radius: 2.5,
            }, relationAngle, 705))
            edges.push({ id: `network-${noteId}-${formId}`, from: noteId, to: formId, kind: 'secondary' })
            relationshipIndex += 1
          })

          if (tableName !== '') {
            const tableId = `network-table-${entryIndex}-${viewIndex}-${actionIndex}-${noteIndex}`
            const relationSlot = forms.length > 0 ? relationStart + (forms.length - 1) / 2 : relationshipIndex++
            const relationAngle = actionAngle - relationshipSpan / 2 + relationshipSpan * (relationSlot + 0.5) / Math.max(1, relationshipCount)
            const fieldCount = projectFlowNetworkTableFieldCount(note, tableName)
            nodes.push(orbitalNode({
              id: tableId,
              label: truncateFlowLabel(tableName, 28),
              detail: `${fieldCount} proposed field${fieldCount === 1 ? '' : 's'}`,
              kind: 'table',
              radius: 2.5,
            }, relationAngle, 780))
            if (formIds.length > 0) {
              formIds.forEach((formId, formIndex) => edges.push({ id: `network-${formId}-${tableId}-${formIndex}`, from: formId, to: tableId, kind: 'secondary' }))
            } else {
              edges.push({ id: `network-${noteId}-${tableId}`, from: noteId, to: tableId, kind: 'secondary' })
            }
          }
        })

        extraTables.forEach((tableName: string, tableIndex: number) => {
          const tableId = `network-action-table-${entryIndex}-${viewIndex}-${actionIndex}-${tableIndex}`
          const relationAngle = actionAngle - relationshipSpan / 2 + relationshipSpan * (relationshipIndex + 0.5) / Math.max(1, relationshipCount)
          relationshipIndex += 1
          nodes.push(orbitalNode({ id: tableId, label: truncateFlowLabel(tableName, 28), detail: 'Documented table', kind: 'table', radius: 2.5 }, relationAngle, 780))
          edges.push({ id: `network-${actionId}-${tableId}`, from: actionId, to: tableId, kind: 'secondary' })
        })
      })
    })
  })

  return { nodes, edges, width, height }
}

function ProjectFlowNetworkView({ entries, totalViews, totalActions, sourcePath }: { entries: Array<Record<string, any>>; totalViews: number; totalActions: number; sourcePath: string }) {
  const graph = React.useMemo(() => buildProjectFlowNetwork(entries), [entries])
  const svgRef = React.useRef<SVGSVGElement>(null)
  const dragRef = React.useRef<
    | { mode: 'node'; nodeId: string; offsetX: number; offsetY: number }
    | { mode: 'pan'; startX: number; startY: number; originX: number; originY: number }
    | null
  >(null)
  const [savedLayout] = React.useState(() => readProjectFlowV2Layout())
  const [positions, setPositions] = React.useState<Record<string, ProjectFlowNodePosition>>(savedLayout.positions)
  const [viewport, setViewport] = React.useState(savedLayout.viewport)
  const [rotation, setRotation] = React.useState(0)
  const [selectedNodeId, setSelectedNodeId] = React.useState('root')
  const [hoveredNodeId, setHoveredNodeId] = React.useState('')
  const nodes = React.useMemo(() => {
    const centerX = graph.width / 2
    const centerY = graph.height / 2
    const rotatedNodes = graph.nodes.map((node) => {
      if (!Number.isFinite(node.orbitAngle) || !Number.isFinite(node.orbitRadius)) return node
      const angle = Number(node.orbitAngle) + rotation
      const radius = Number(node.orbitRadius)
      const yScale = Number(node.orbitYScale) || 0.78

      return {
        ...node,
        x: centerX + Math.cos(angle) * radius,
        y: centerY + Math.sin(angle) * radius * yScale,
        depth: Math.sin(angle),
      }
    })
    const positionedNodes = rotatedNodes.map((node) => {
      const position = positions[node.id]

      return position ? { ...node, x: position.x, y: position.y } : node
    })

    return projectFlowNetworkHasOverlap(positionedNodes) ? rotatedNodes : positionedNodes
  }, [graph.height, graph.nodes, graph.width, positions, rotation])
  const nodesRef = React.useRef(nodes)
  nodesRef.current = nodes
  const nodesById = new Map(nodes.map((node) => [node.id, node]))
  const selectedNode = nodesById.get(selectedNodeId) || graph.nodes[0]
  const nodeCounts = graph.nodes.reduce<Record<string, number>>((counts, node) => {
    counts[node.kind] = (counts[node.kind] || 0) + 1
    return counts
  }, {})

  React.useEffect(() => {
    writeProjectFlowV2Layout({ positions, viewport })
  }, [positions, viewport])

  function clampZoom(value: number): number {
    return Math.min(2.5, Math.max(0.12, value))
  }

  function svgPointerPoint(event: React.PointerEvent<SVGSVGElement | SVGGElement> | React.WheelEvent<SVGSVGElement>) {
    const svg = svgRef.current
    if (!svg) return { x: graph.width / 2, y: graph.height / 2 }

    const rect = svg.getBoundingClientRect()

    return {
      x: ((event.clientX - rect.left) / rect.width) * graph.width,
      y: ((event.clientY - rect.top) / rect.height) * graph.height,
    }
  }

  function contentPoint(point: { x: number; y: number }, targetViewport = viewport): { x: number; y: number } {
    return {
      x: (point.x - targetViewport.x) / targetViewport.scale,
      y: (point.y - targetViewport.y) / targetViewport.scale,
    }
  }

  function zoomAt(rawPoint: { x: number; y: number }, nextScale: number) {
    setViewport((current) => {
      const scale = clampZoom(nextScale)
      const contentX = (rawPoint.x - current.x) / current.scale
      const contentY = (rawPoint.y - current.y) / current.scale

      return {
        scale,
        x: rawPoint.x - contentX * scale,
        y: rawPoint.y - contentY * scale,
      }
    })
  }

  function rotateGlobe(delta: number) {
    setPositions({})
    setRotation((current) => current + delta)
  }

  const fitViewport = React.useCallback(() => {
    const svg = svgRef.current
    const surface = svg?.parentElement
    if (!surface) return
    const rect = surface.getBoundingClientRect()
    const fitNodes = nodesRef.current
    if (fitNodes.length === 0) return

    const bounds = fitNodes.reduce((result, node) => {
      const box = projectFlowNetworkNodeBox(node)
      return {
        minX: Math.min(result.minX, node.x - box.width / 2),
        minY: Math.min(result.minY, node.y - box.height / 2),
        maxX: Math.max(result.maxX, node.x + box.width / 2),
        maxY: Math.max(result.maxY, node.y + box.height / 2),
      }
    }, { minX: Number.POSITIVE_INFINITY, minY: Number.POSITIVE_INFINITY, maxX: Number.NEGATIVE_INFINITY, maxY: Number.NEGATIVE_INFINITY })
    const padding = 96
    const contentWidth = Math.max(1, bounds.maxX - bounds.minX)
    const contentHeight = Math.max(1, bounds.maxY - bounds.minY)
    const contentCenterX = (bounds.minX + bounds.maxX) / 2
    const contentCenterY = (bounds.minY + bounds.maxY) / 2
    const scale = clampZoom(Math.min((rect.width - padding) / contentWidth, (rect.height - padding) / contentHeight) * 0.95)
    setViewport({
      scale,
      x: graph.width / 2 - contentCenterX * scale,
      y: graph.height / 2 - contentCenterY * scale,
    })
  }, [graph.height, graph.width])

  React.useEffect(() => {
    if (Object.keys(savedLayout.positions).length > 0 || savedLayout.viewport.x !== 0 || savedLayout.viewport.y !== 0 || savedLayout.viewport.scale !== 1) return
    const frame = window.requestAnimationFrame(fitViewport)
    return () => window.cancelAnimationFrame(frame)
  }, [fitViewport, savedLayout.positions, savedLayout.viewport.scale, savedLayout.viewport.x, savedLayout.viewport.y])

  React.useEffect(() => {
    const svg = svgRef.current
    if (!svg) return undefined
    const svgElement = svg

    function handleNativeWheel(event: WheelEvent) {
      event.preventDefault()
      if (event.shiftKey || Math.abs(event.deltaX) > Math.abs(event.deltaY)) {
        setPositions({})
        setRotation((current) => current + (event.deltaY + event.deltaX > 0 ? 0.12 : -0.12))
        return
      }
      const rect = svgElement.getBoundingClientRect()
      const rawPoint = {
        x: ((event.clientX - rect.left) / rect.width) * graph.width,
        y: ((event.clientY - rect.top) / rect.height) * graph.height,
      }
      setViewport((current) => {
        const scale = clampZoom(current.scale * (event.deltaY < 0 ? 1.1 : 0.9))
        const contentX = (rawPoint.x - current.x) / current.scale
        const contentY = (rawPoint.y - current.y) / current.scale

        return {
          scale,
          x: rawPoint.x - contentX * scale,
          y: rawPoint.y - contentY * scale,
        }
      })
    }

    svgElement.addEventListener('wheel', handleNativeWheel, { passive: false })
    return () => svgElement.removeEventListener('wheel', handleNativeWheel)
  }, [graph.height, graph.width])


  function handleNodePointerDown(event: React.PointerEvent<SVGGElement>, node: ProjectFlowNetworkNode) {
    event.preventDefault()
    event.stopPropagation()
    const point = contentPoint(svgPointerPoint(event))
    dragRef.current = {
      mode: 'node',
      nodeId: node.id,
      offsetX: point.x - node.x,
      offsetY: point.y - node.y,
    }
    setSelectedNodeId(node.id)
    event.currentTarget.setPointerCapture(event.pointerId)
  }

  function handleSvgPointerDown(event: React.PointerEvent<SVGSVGElement>) {
    const point = svgPointerPoint(event)
    dragRef.current = {
      mode: 'pan',
      startX: point.x,
      startY: point.y,
      originX: viewport.x,
      originY: viewport.y,
    }
    event.currentTarget.setPointerCapture(event.pointerId)
  }

  function handleSvgPointerMove(event: React.PointerEvent<SVGSVGElement>) {
    const drag = dragRef.current
    if (!drag) return

    const point = svgPointerPoint(event)
    if (drag.mode === 'pan') {
      setViewport((current) => ({
        ...current,
        x: drag.originX + point.x - drag.startX,
        y: drag.originY + point.y - drag.startY,
      }))
      return
    }

    const nextPoint = contentPoint(point)
    const draggedNode = nodesRef.current.find((node) => node.id === drag.nodeId)
    if (!draggedNode) return
    const candidate = {
      ...draggedNode,
      x: Math.round(nextPoint.x - drag.offsetX),
      y: Math.round(nextPoint.y - drag.offsetY),
    }
    const collides = nodesRef.current.some((node) => node.id !== candidate.id && projectFlowNetworkNodesOverlap(candidate, node, 8))
    if (collides) return

    setPositions((current) => ({
      ...current,
      [drag.nodeId]: {
        x: candidate.x,
        y: candidate.y,
      },
    }))
  }

  function stopDrag() {
    dragRef.current = null
  }

  function resetNetworkLayout() {
    dragRef.current = null
    setPositions({})
    setViewport({ x: 0, y: 0, scale: 1 })
    setRotation(0)
    setSelectedNodeId('root')
    setHoveredNodeId('')
    window.requestAnimationFrame(fitViewport)
  }

  return (
    <div className="grid min-w-0 gap-3">
      <Card className="min-w-0 overflow-hidden">
            <CardHeader className="flex min-w-0 min-h-16 flex-col gap-3 border-b bg-muted/20 py-3 lg:flex-row lg:items-center lg:justify-between">
          <div className="min-w-0">
            <Badge variant="secondary">Data Structure V2</Badge>
            <CardTitle className="mt-1 text-base tracking-normal">3D Circular Neural Network</CardTitle>
            <p className="mt-1 text-xs text-muted-foreground">Drag to pan · Scroll to zoom · Shift + scroll to orbit</p>
          </div>
          <div className="flex min-w-0 max-w-full flex-wrap items-center justify-start gap-2 text-xs text-muted-foreground lg:justify-end">
            <Badge variant="outline">{entries.length} Entrypoints</Badge>
            <Badge variant="outline">{totalViews} Views</Badge>
            <Badge variant="outline">{totalActions} Actions</Badge>
            <Badge variant="outline">{graph.nodes.length} Nodes</Badge>
            <Badge variant="outline">{nodeCounts.entry || 0} Entry</Badge>
            <Badge variant="outline">{nodeCounts.view || 0} View</Badge>
            <Badge variant="outline">{nodeCounts.action || 0} Action</Badge>
            <Badge variant="outline">{nodeCounts.note || 0} Notes</Badge>
            <Badge variant="outline">{nodeCounts.form || 0} Forms</Badge>
            <Badge variant="outline">{nodeCounts.table || 0} Table</Badge>
            <Separator orientation="vertical" className="hidden data-vertical:h-6 lg:block" />
            <Tooltip>
              <TooltipTrigger render={<Button type="button" variant="outline" size="icon-sm" aria-label="Rotate neural globe left" onClick={() => rotateGlobe(-0.18)} />}>
                <ChevronLeft />
              </TooltipTrigger>
              <TooltipContent>Rotate Left · Shift + Scroll</TooltipContent>
            </Tooltip>
            <Tooltip>
              <TooltipTrigger render={<Button type="button" variant="outline" size="icon-sm" aria-label="Rotate neural globe right" onClick={() => rotateGlobe(0.18)} />}>
                <ChevronRight />
              </TooltipTrigger>
              <TooltipContent>Rotate Right · Shift + Scroll</TooltipContent>
            </Tooltip>
            <Tooltip>
              <TooltipTrigger render={<Button type="button" variant="outline" size="icon-sm" aria-label="Zoom out" onClick={() => zoomAt({ x: graph.width / 2, y: graph.height / 2 }, viewport.scale * 0.85)} />}>
                <ZoomOut />
              </TooltipTrigger>
              <TooltipContent>Zoom Out</TooltipContent>
            </Tooltip>
            <Badge variant="secondary" className="min-w-14 justify-center">{Math.round(viewport.scale * 100)}%</Badge>
            <Tooltip>
              <TooltipTrigger render={<Button type="button" variant="outline" size="icon-sm" aria-label="Zoom in" onClick={() => zoomAt({ x: graph.width / 2, y: graph.height / 2 }, viewport.scale * 1.15)} />}>
                <ZoomIn />
              </TooltipTrigger>
              <TooltipContent>Zoom In</TooltipContent>
            </Tooltip>
            <Button type="button" variant="outline" size="sm" onClick={fitViewport}><Frame />Fit graph</Button>
            <Button type="button" variant="outline" size="sm" onClick={resetNetworkLayout}>
              <RotateCcw />
              Reset
            </Button>
          </div>
        </CardHeader>
        <CardContent className="p-0">
          <div className="grid min-w-0 bg-[#101726] lg:grid-cols-[minmax(0,1fr)_280px]">
            <div className="relative h-[calc(100vh-266px)] min-h-[340px] overflow-hidden bg-[radial-gradient(circle_at_50%_48%,rgba(31,51,87,0.82)_0%,rgba(20,36,63,0.74)_58%,#0b1020_100%)]">
              <svg
                ref={svgRef}
                width="100%"
                height="100%"
                viewBox={`0 0 ${graph.width} ${graph.height}`}
                preserveAspectRatio="xMidYMid meet"
                role="img"
                aria-label="Data Structure V2 three-dimensional circular neural network with UI and UX notes, forms, and tables"
                className="h-full w-full touch-none"
                onPointerDown={handleSvgPointerDown}
                onPointerMove={handleSvgPointerMove}
                onPointerUp={stopDrag}
                onPointerCancel={stopDrag}
                onPointerLeave={stopDrag}
              >
                <defs>
	                  <filter id="data-v2-glow" x="-60%" y="-60%" width="220%" height="220%">
                    <feGaussianBlur stdDeviation="4" result="blur" />
                    <feMerge>
                      <feMergeNode in="blur" />
                      <feMergeNode in="SourceGraphic" />
                    </feMerge>
                  </filter>
                  <radialGradient id="data-v2-globe" cx="50%" cy="46%" r="58%">
                    <stop offset="0%" stopColor="#1d4ed8" stopOpacity="0.2" />
                    <stop offset="58%" stopColor="#0ea5e9" stopOpacity="0.08" />
                    <stop offset="100%" stopColor="#020617" stopOpacity="0" />
                  </radialGradient>
                </defs>
	                <rect width={graph.width} height={graph.height} fill="transparent" />
                <g transform={`translate(${viewport.x} ${viewport.y}) scale(${viewport.scale})`}>
                  <g aria-hidden="true" pointerEvents="none">
                    <ellipse cx={graph.width / 2} cy={graph.height / 2} rx={800} ry={624} fill="url(#data-v2-globe)" stroke="#38bdf8" strokeOpacity={0.22} strokeWidth={1.2} />
                    {[250, 420, 520, 575, 630, 705, 780].map((radius) => (
                      <ellipse key={`orbit-${radius}`} cx={graph.width / 2} cy={graph.height / 2} rx={radius} ry={radius * 0.78} fill="none" stroke="#60a5fa" strokeOpacity={radius >= 620 ? 0.13 : 0.18} strokeWidth={0.8} strokeDasharray={radius >= 620 ? '6 10' : '3 8'} vectorEffect="non-scaling-stroke" />
                    ))}
                    <ellipse cx={graph.width / 2} cy={graph.height / 2} rx={800} ry={160} fill="none" stroke="#38bdf8" strokeOpacity={0.13} strokeWidth={0.8} vectorEffect="non-scaling-stroke" />
                    <ellipse cx={graph.width / 2} cy={graph.height / 2} rx={800} ry={365} fill="none" stroke="#38bdf8" strokeOpacity={0.1} strokeWidth={0.8} vectorEffect="non-scaling-stroke" />
                    <ellipse cx={graph.width / 2} cy={graph.height / 2} rx={255} ry={624} fill="none" stroke="#38bdf8" strokeOpacity={0.11} strokeWidth={0.8} transform={`rotate(18 ${graph.width / 2} ${graph.height / 2})`} vectorEffect="non-scaling-stroke" />
                    <ellipse cx={graph.width / 2} cy={graph.height / 2} rx={255} ry={624} fill="none" stroke="#38bdf8" strokeOpacity={0.11} strokeWidth={0.8} transform={`rotate(-18 ${graph.width / 2} ${graph.height / 2})`} vectorEffect="non-scaling-stroke" />
                  </g>
                  {graph.edges.map((edge) => {
                    const from = nodesById.get(edge.from)
                    const to = nodesById.get(edge.to)
                    if (!from || !to) return null
                    const active = selectedNodeId === from.id || selectedNodeId === to.id
                    const depthOpacity = 0.62 + (((from.depth || 0) + (to.depth || 0) + 2) / 4) * 0.38
                    const startPoint = projectFlowNetworkEdgePoint(from, to)
                    const endPoint = projectFlowNetworkEdgePoint(to, from)
                    return (
                      <line
                        key={edge.id}
                        x1={startPoint.x}
                        y1={startPoint.y}
                        x2={endPoint.x}
                        y2={endPoint.y}
                        stroke={active ? '#8fd3ff' : '#5f7fb8'}
                        strokeOpacity={active ? 0.92 : (edge.kind === 'primary' ? 0.46 : 0.28) * depthOpacity}
                        strokeWidth={active ? 1.7 : edge.kind === 'primary' ? 1.1 : 0.8}
                        vectorEffect="non-scaling-stroke"
                      />
                    )
                  })}
                  {[...nodes].sort((first, second) => (first.depth || 0) - (second.depth || 0)).map((node) => {
                    const selected = selectedNodeId === node.id
                    const box = projectFlowNetworkNodeBox(node)
                    const compact = node.kind === 'entry' || node.kind === 'note' || node.kind === 'form' || node.kind === 'table'
                    const showCompactTooltip = compact && (selected || (node.kind === 'note' && hoveredNodeId === node.id))
                    const labelLines = projectFlowNetworkLabelLines(node.label)
                    const tooltipDetailLines = projectFlowNetworkLabelLines(node.detail, 42)
                    const detail = truncateFlowLabel(node.detail, 24)
                    const textX = node.x - box.width / 2 + 24
                    const labelStartY = node.y - (labelLines.length === 2 ? 10 : 4)
                    const color = node.kind === 'root'
                      ? '#f8fbff'
                      : node.kind === 'entry'
                        ? '#60a5fa'
                        : node.kind === 'view'
                          ? '#93c5fd'
                          : node.kind === 'note'
                            ? '#c4b5fd'
                            : node.kind === 'form'
                              ? '#fbbf24'
                          : node.kind === 'table'
                            ? '#34d399'
                            : '#818cf8'
                    const nodeOpacity = node.kind === 'root' ? 1 : 0.62 + (((node.depth || 0) + 1) / 2) * 0.38
                    const tooltipWidth = node.kind === 'note' ? 460 : Math.max(180, node.label.length * 9 + 28)
                    const tooltipHeight = node.kind === 'note' ? 112 : 52
                    const tooltipScale = 1 / viewport.scale
                    const tooltipContentWidth = tooltipWidth * tooltipScale
                    const tooltipContentHeight = tooltipHeight * tooltipScale
                    const tooltipX = node.x > graph.width / 2 ? node.x - tooltipContentWidth - 18 : node.x + 18
                    const tooltipY = Math.max(12, Math.min(graph.height - tooltipContentHeight - 12, node.y - tooltipContentHeight / 2))
                    return (
                      <g
                        key={node.id}
                        data-node-id={node.id}
                        data-node-kind={node.kind}
                        role="button"
                        tabIndex={0}
                        aria-label={`${node.kind}: ${node.label}. ${node.detail}`}
                        className="cursor-move outline-none"
                        opacity={nodeOpacity}
                        onPointerEnter={() => setHoveredNodeId(node.id)}
                        onPointerLeave={() => setHoveredNodeId((current) => current === node.id ? '' : current)}
                        onFocus={() => setHoveredNodeId(node.id)}
                        onBlur={() => setHoveredNodeId((current) => current === node.id ? '' : current)}
                        onPointerDown={(event) => handleNodePointerDown(event, node)}
                        onClick={(event) => {
                          event.stopPropagation()
                          setSelectedNodeId(node.id)
                        }}
                        onKeyDown={(event) => {
                          if (event.key !== 'Enter' && event.key !== ' ') return
                          event.preventDefault()
                          setSelectedNodeId(node.id)
                        }}
                        filter={selected || node.kind === 'root' ? 'url(#data-v2-glow)' : undefined}
                      >
                        {compact ? (
                          <>
                            <rect x={node.x - box.width / 2} y={node.y - box.height / 2} width={box.width} height={box.height} fill="transparent" />
                            <circle cx={node.x} cy={node.y} r={node.kind === 'note' ? (selected ? 11 : 8.5) : 18} fill="#07111f" fillOpacity={0.96} stroke={color} strokeOpacity={selected ? 1 : 0.82} strokeWidth={selected ? 2.2 : 1.2} vectorEffect="non-scaling-stroke" />
                            {node.kind === 'entry' ? (
                              <g fill="none" stroke={color} strokeWidth={1.5} vectorEffect="non-scaling-stroke">
                                <circle cx={node.x} cy={node.y} r={5} />
                                <path d={`M ${node.x - 11} ${node.y} H ${node.x - 5} M ${node.x + 5} ${node.y} H ${node.x + 11} M ${node.x} ${node.y - 11} V ${node.y - 5} M ${node.x} ${node.y + 5} V ${node.y + 11}`} />
                              </g>
                            ) : node.kind === 'note' ? (
                              <circle cx={node.x} cy={node.y} r={selected ? 6 : 4.5} fill={color} />
                            ) : node.kind === 'form' ? (
                              <g fill="none" stroke={color} strokeWidth={1.5} vectorEffect="non-scaling-stroke">
                                <rect x={node.x - 8} y={node.y - 10} width={16} height={20} rx={2} />
                                <line x1={node.x - 4} y1={node.y - 5} x2={node.x + 5} y2={node.y - 5} />
                                <line x1={node.x - 4} y1={node.y} x2={node.x + 5} y2={node.y} />
                                <line x1={node.x - 4} y1={node.y + 5} x2={node.x + 2} y2={node.y + 5} />
                              </g>
                            ) : (
                              <g fill="none" stroke={color} strokeWidth={1.5} vectorEffect="non-scaling-stroke">
                                <ellipse cx={node.x} cy={node.y - 7} rx={9} ry={4} />
                                <path d={`M ${node.x - 9} ${node.y - 7} V ${node.y + 7} C ${node.x - 9} ${node.y + 12}, ${node.x + 9} ${node.y + 12}, ${node.x + 9} ${node.y + 7} V ${node.y - 7}`} />
                                <path d={`M ${node.x - 9} ${node.y} C ${node.x - 9} ${node.y + 5}, ${node.x + 9} ${node.y + 5}, ${node.x + 9} ${node.y}`} />
                              </g>
                            )}
                            {showCompactTooltip ? (
                              <g className="pointer-events-none" transform={`translate(${tooltipX} ${tooltipY}) scale(${tooltipScale})`}>
                                <rect width={tooltipWidth} height={tooltipHeight} rx={10} fill="#07111f" fillOpacity={0.98} />
                                <text x={18} y={34} fill="#f8fbff" className="select-none text-[22px] font-semibold">{truncateFlowLabel(node.label, 36)}</text>
                                {node.kind === 'note' ? (
                                  <text x={18} y={66} fill="#a9c5e8" className="select-none text-[18px]">
                                    {tooltipDetailLines.map((line, index) => <tspan key={`${node.id}-tooltip-${index}`} x={18} dy={index === 0 ? 0 : 24}>{line}</tspan>)}
                                  </text>
                                ) : null}
                              </g>
                            ) : null}
                          </>
                        ) : (
                          <>
                            <rect
                              x={node.x - box.width / 2}
                              y={node.y - box.height / 2}
                              width={box.width}
                              height={box.height}
                              rx={10}
                              fill="#0b1324"
                              fillOpacity={selected ? 0.98 : 0.9}
                              stroke="none"
                              strokeWidth={0}
                              vectorEffect="non-scaling-stroke"
                            />
                            <circle
                              cx={node.x - box.width / 2 + 12}
                              cy={node.y - box.height / 2 + 14}
                              r={selected ? 5.5 : 4.5}
                              fill={color}
                              fillOpacity={node.kind === 'root' ? 1 : 0.9}
                              stroke={selected ? '#ffffff' : '#b9d9ff'}
                              strokeOpacity={selected ? 0.98 : 0.55}
                              strokeWidth={selected ? 1.6 : 0.8}
                              vectorEffect="non-scaling-stroke"
                            />
                            <text x={textX} y={labelStartY} textAnchor="start" fill={node.kind === 'root' ? '#f8fbff' : selected ? '#ffffff' : '#d7e8ff'} className="pointer-events-none select-none text-[13px] font-medium">
                              {labelLines.map((line, index) => <tspan key={`${node.id}-label-${index}`} x={textX} dy={index === 0 ? 0 : 14}>{line}</tspan>)}
                            </text>
                            {detail ? <text x={textX} y={node.y + box.height / 2 - 9} textAnchor="start" fill={node.kind === 'root' ? '#a5b9d8' : '#83a6d9'} className="pointer-events-none select-none text-[10px]">{detail}</text> : null}
                          </>
                        )}
                      </g>
                    )
                  })}
                </g>
              </svg>
            </div>
            <aside className="min-w-0 border-t border-white/10 bg-[#0b1020]/80 p-4 text-slate-200 lg:border-l lg:border-t-0">
              <div className="flex items-center gap-2">
                <Sparkles className="text-sky-300" />
                <h3 className="text-sm font-semibold tracking-normal">Selected Node</h3>
              </div>
              <div className="mt-4 rounded-md border border-white/10 bg-white/[0.04] p-3">
                <p className="text-base font-semibold text-white">{selectedNode?.label || 'Project'}</p>
                <p className="mt-1 text-xs uppercase text-sky-200">{selectedNode?.kind || 'root'}</p>
                <p className="mt-3 text-sm leading-6 text-slate-300">{selectedNode?.detail || 'Project data structure root.'}</p>
              </div>
              <div className="mt-4 grid gap-2 text-xs text-slate-300">
                <div className="flex min-w-0 flex-wrap items-start justify-between gap-2 rounded-md border border-white/10 px-3 py-2"><span className="shrink-0">Source</span><span className="min-w-0 break-all text-right font-mono text-sky-200">{sourcePath}</span></div>
                <div className="flex items-center justify-between rounded-md border border-white/10 px-3 py-2"><span>Links</span><span>{graph.edges.length}</span></div>
                <div className="flex items-center justify-between rounded-md border border-white/10 px-3 py-2"><span>Notes</span><span>{nodeCounts.note || 0}</span></div>
                <div className="flex items-center justify-between rounded-md border border-white/10 px-3 py-2"><span>Forms</span><span>{nodeCounts.form || 0}</span></div>
                <div className="flex items-center justify-between rounded-md border border-white/10 px-3 py-2"><span>Tables</span><span>{nodeCounts.table || 0}</span></div>
              </div>
            </aside>
          </div>
        </CardContent>
      </Card>
    </div>
  )
}

function ProjectFlowSummaryGrid({ entries, totalViews, totalActions }: { entries: Array<Record<string, any>>; totalViews: number; totalActions: number }) {
  const tables = projectFlowTables(entries)
  const backendEntries = projectFlowBackendEntries(entries)
  const securityRules = projectFlowSecurityRules(entries)
  const phaseMappings = projectFlowPhaseMappings(entries)
  const metrics = [
    { label: 'Entrypoints', value: entries.length, icon: ExternalLink, hint: 'Top-level routes that mount a page shell.' },
    { label: 'Page Views', value: totalViews, icon: LayoutDashboard, hint: 'Views, tabs, or route states inside each shell.' },
    { label: 'Actions', value: totalActions, icon: Activity, hint: 'Clicks, submits, AJAX calls, and navigation events.' },
    { label: 'Tables', value: tables.length, icon: Database, hint: 'Database tables touched by documented actions.' },
    { label: 'PHP Files', value: backendEntries.length, icon: FileText, hint: 'Backend entrypoints preparing payloads or handling actions.' },
    { label: 'Security Rules', value: securityRules.length, icon: ShieldCheck, hint: 'CSRF, admin-only, confirmation, audit, and related rules.' },
    { label: 'Phase Links', value: phaseMappings.length, icon: FolderKanban, hint: 'Phase/Task mappings connected to pages and actions.' },
  ]

  return (
    <section className="grid overflow-hidden rounded-lg border bg-card sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-7">
      {metrics.map((metric) => {
        const Icon = metric.icon

        return (
        <div key={metric.label} className="min-w-0 border-b p-4 last:border-b-0 sm:border-r sm:last:border-r-0 lg:border-b-0">
            <div className="flex items-center justify-between gap-3">
              <p className="text-xs font-medium text-muted-foreground">{metric.label}</p>
              <Icon />
            </div>
            <p className="mt-2 text-2xl font-semibold tracking-normal">{metric.value}</p>
            <p className="mt-1 text-xs text-muted-foreground">{metric.hint}</p>
          </div>
        )
      })}
    </section>
  )
}

function ProjectFlowAction({ action }: { action: Record<string, any> }) {
  const tables = Array.isArray(action.tables) ? action.tables : []
  const security = Array.isArray(action.security) ? action.security : []

  return (
    <div className="rounded-md border bg-muted/20 p-3">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div>
          <p className="text-sm font-semibold">{phaseField(action, 'label', 'Untitled Action')}</p>
          <p className="mt-1 font-mono text-xs text-muted-foreground">{phaseField(action, 'id')}</p>
        </div>
        <Badge variant="secondary">{phaseField(action, 'type', 'action')}</Badge>
      </div>
      <div className="mt-3 grid gap-2 text-xs text-muted-foreground md:grid-cols-2">
        <div><span className="font-medium text-foreground">From:</span> {phaseField(action, 'from', '-')}</div>
        <div><span className="font-medium text-foreground">To:</span> {phaseField(action, 'to', '-')}</div>
        <div><span className="font-medium text-foreground">Component:</span> {phaseField(action, 'frontendComponent', '-')}</div>
        <div><span className="font-medium text-foreground">Backend:</span> {phaseField(action, 'backendAction', '-') || '-'}</div>
        <div><span className="font-medium text-foreground">PHP:</span> {phaseField(action, 'phpEntry', '-')}</div>
        <div><span className="font-medium text-foreground">Phase/Task:</span> {phaseField(action, 'phaseTask', '-') || '-'}</div>
      </div>
      {(tables.length > 0 || security.length > 0) && (
        <div className="mt-3 flex flex-wrap gap-2">
          {tables.map((table: string) => <Badge key={`table-${table}`} variant="outline">{table}</Badge>)}
          {security.map((item: string) => <Badge key={`security-${item}`} variant="secondary">{item}</Badge>)}
        </div>
      )}
    </div>
  )
}

function ProjectFlowPageRegistry({ entries }: { entries: Array<Record<string, any>> }) {
  const rows = projectFlowPageRows(entries)

  return (
    <Card>
      <CardHeader>
        <CardTitle>Page Registry</CardTitle>
        <CardDescription>Every documented entrypoint and page view with source, backend, action count, and Phase/Task mapping.</CardDescription>
      </CardHeader>
      <CardContent>
        <div className="overflow-auto rounded-md border">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Page</TableHead>
                <TableHead>Route</TableHead>
                <TableHead>Owner</TableHead>
                <TableHead>Backend</TableHead>
                <TableHead>Phase/Task</TableHead>
                <TableHead className="text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {rows.map((row, index) => (
                <TableRow key={`${phaseField(row, 'route', 'route')}-${index}`}>
                  <TableCell>
                    <div className="font-medium">{phaseField(row, 'label', 'Page')}</div>
                    <div className="mt-1 text-xs text-muted-foreground">{phaseField(row, 'kind', 'Page')}</div>
                  </TableCell>
                  <TableCell className="font-mono text-xs">{phaseField(row, 'route', '-')}</TableCell>
                  <TableCell>{phaseField(row, 'owner', '-')}</TableCell>
                  <TableCell className="font-mono text-xs">{phaseField(row, 'backend', '-')}</TableCell>
                  <TableCell>{phaseField(row, 'phaseTask', '') || <span className="text-muted-foreground">Unmapped</span>}</TableCell>
                  <TableCell className="text-right">{phaseNumber(row, 'actions')}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>
      </CardContent>
    </Card>
  )
}

function ProjectFlowDataRegistry({ entries }: { entries: Array<Record<string, any>> }) {
  const tables = projectFlowTables(entries)
  const securityRules = projectFlowSecurityRules(entries)
  const backendEntries = projectFlowBackendEntries(entries)
  const actions = projectFlowAllActions(entries)

  return (
    <div className="grid min-w-0 gap-4 lg:grid-cols-[minmax(0,1fr)_320px]">
      <Card>
        <CardHeader>
          <CardTitle>Database Touchpoints</CardTitle>
          <CardDescription>Tables and the documented page actions that read or write them.</CardDescription>
        </CardHeader>
        <CardContent className="grid gap-3">
          {tables.length === 0 ? (
            <p className="text-sm text-muted-foreground">No table touchpoints are documented yet.</p>
          ) : tables.map((table) => {
            const tableActions = actions.filter(({ action }) => Array.isArray(action.tables) && action.tables.includes(table))

            return (
              <div key={table} className="rounded-md border p-3">
                <div className="flex flex-wrap items-center justify-between gap-2">
                  <div>
                    <p className="font-mono text-sm font-semibold">{table}</p>
                    <p className="mt-1 text-xs text-muted-foreground">{tableActions.length} connected action{tableActions.length === 1 ? '' : 's'}</p>
                  </div>
                  <Badge variant="outline">Database</Badge>
                </div>
                <div className="mt-3 flex flex-wrap gap-2">
                  {tableActions.map(({ action }) => <Badge key={`${table}-${phaseField(action, 'id')}`} variant="secondary">{phaseField(action, 'label', 'Action')}</Badge>)}
                </div>
              </div>
            )
          })}
        </CardContent>
      </Card>
      <div className="grid gap-4">
        <Card>
          <CardHeader>
            <CardTitle>Backend Files</CardTitle>
            <CardDescription>PHP entrypoints in the page map.</CardDescription>
          </CardHeader>
          <CardContent className="flex flex-wrap gap-2">
            {backendEntries.map((entry) => <Badge key={entry} variant="outline">{entry}</Badge>)}
          </CardContent>
        </Card>
        <Card>
          <CardHeader>
            <CardTitle>Security Rules</CardTitle>
            <CardDescription>Controls attached to documented actions.</CardDescription>
          </CardHeader>
          <CardContent className="flex flex-wrap gap-2">
            {securityRules.length === 0 ? <span className="text-sm text-muted-foreground">No security rules documented.</span> : securityRules.map((rule) => <Badge key={rule} variant="secondary">{rule}</Badge>)}
          </CardContent>
        </Card>
      </div>
    </div>
  )
}

function ProjectFlowEmptyState({ sourcePath, label = 'Data Structure V1' }: { sourcePath: string; label?: string }) {
  return (
    <Card>
      <CardHeader>
        <Badge variant="secondary" className="w-fit">{label}</Badge>
        <CardTitle className="mt-2 text-lg tracking-normal">No Page Connections Yet</CardTitle>
        <CardDescription className="max-w-3xl">
          This project does not have documented routes, page views, actions, backend entrypoints, or table touchpoints yet. The map will populate after `docs/project/project-flow.json` is updated.
        </CardDescription>
      </CardHeader>
      <CardContent>
        <div className="rounded-md border bg-muted/20 p-4 text-sm text-muted-foreground">
          Source: <span className="font-mono">{sourcePath}</span>
        </div>
      </CardContent>
    </Card>
  )
}

function ProjectFlowViewCard({ entry }: { entry: Record<string, any> }) {
  const views = projectFlowViews(entry)
  const actions = projectFlowActions(entry)

  return (
    <Card>
      <CardHeader>
        <div className="flex flex-col gap-3 lg:flex-row lg:items-start lg:justify-between">
          <div>
            <Badge variant="secondary">{phaseField(entry, 'owner', 'Project')}</Badge>
            <CardTitle className="mt-3 text-xl tracking-normal">{phaseField(entry, 'label', 'Untitled Entrypoint')}</CardTitle>
            <CardDescription className="mt-2 font-mono">{phaseField(entry, 'route', '/')}</CardDescription>
          </div>
          <div className="flex flex-wrap gap-2">
            <Badge variant="outline">{views.length} Views</Badge>
            <Badge variant="outline">{actions.length + views.reduce((count, view) => count + projectFlowActions(view).length, 0)} Actions</Badge>
          </div>
        </div>
      </CardHeader>
      <CardContent className="grid gap-4">
        {entry.backend && (
          <div className="rounded-md border bg-muted/20 p-3 text-sm text-muted-foreground">
            <span className="font-medium text-foreground">{phaseField(entry.backend, 'phpEntry', 'Backend')}:</span> {phaseField(entry.backend, 'responsibility', 'No backend responsibility documented.')}
          </div>
        )}
        {actions.map((action: Record<string, any>) => <ProjectFlowAction key={phaseField(action, 'id')} action={action} />)}
        {views.map((view: Record<string, any>) => (
          <section key={phaseField(view, 'key', phaseField(view, 'url'))} className="rounded-md border p-3">
            <div className="flex flex-wrap items-start justify-between gap-2">
              <div>
                <h3 className="text-sm font-semibold">{phaseField(view, 'label', 'Untitled View')}</h3>
                <p className="mt-1 font-mono text-xs text-muted-foreground">{phaseField(view, 'url', '-')}</p>
              </div>
              <Badge variant="secondary">{phaseField(view, 'phaseTask', '-') || 'Unmapped'}</Badge>
            </div>
            <div className="mt-3 grid gap-3">
              {projectFlowActions(view).length === 0
                ? <p className="text-sm text-muted-foreground">No actions documented yet.</p>
                : projectFlowActions(view).map((action: Record<string, any>) => <ProjectFlowAction key={phaseField(action, 'id')} action={action} />)}
            </div>
          </section>
        ))}
      </CardContent>
    </Card>
  )
}

function ProjectFlowView() {
  const flow = phaseData?.projectFlow ?? {}
  const entries = projectFlowEntries()
  const totalViews = countProjectFlowViews(entries)
  const totalActions = countProjectFlowActions(entries)
  const sourcePath = phaseField(flow, 'sourcePath', 'docs/project/project-flow.json')

  return (
    <div className="grid min-w-0 items-start gap-4">
      {phaseField(flow, 'error') && (
        <Card>
          <CardHeader>
            <CardTitle>Flow Source Error</CardTitle>
            <CardDescription>{phaseField(flow, 'error')}</CardDescription>
          </CardHeader>
        </Card>
      )}

      <ProjectFlowSummaryGrid entries={entries} totalViews={totalViews} totalActions={totalActions} />

      <Tabs defaultValue="map" className="grid min-w-0 gap-4">
        <TabsList className="flex h-auto w-fit max-w-full flex-wrap justify-start overflow-x-auto">
          <TabsTrigger value="map"><Frame />Map</TabsTrigger>
          <TabsTrigger value="pages"><LayoutDashboard />Pages</TabsTrigger>
          <TabsTrigger value="data"><Database />Data</TabsTrigger>
          <TabsTrigger value="source"><BookOpen />Source</TabsTrigger>
        </TabsList>
        <TabsContent value="map" className="grid gap-4">
          {entries.length === 0 ? <ProjectFlowEmptyState sourcePath={sourcePath} /> : <ProjectFlowCanvas entries={entries} totalViews={totalViews} totalActions={totalActions} sourcePath={sourcePath} />}
          {entries.map((entry) => <ProjectFlowViewCard key={phaseField(entry, 'route')} entry={entry} />)}
        </TabsContent>
        <TabsContent value="pages" className="grid gap-4">
          <ProjectFlowPageRegistry entries={entries} />
        </TabsContent>
        <TabsContent value="data" className="grid gap-4">
          <ProjectFlowDataRegistry entries={entries} />
        </TabsContent>
        <TabsContent value="source">
          <Card>
            <CardHeader>
              <CardTitle>JSON Source Preview</CardTitle>
              <CardDescription>AI must update this source when routes, clicks, submits, AJAX calls, backend actions, tables, or Phase/Task mappings change.</CardDescription>
            </CardHeader>
            <CardContent>
              <pre className="max-h-96 overflow-auto rounded-md border bg-muted/40 p-4 text-xs leading-5 whitespace-pre-wrap">{JSON.stringify(flow, null, 2)}</pre>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  )
}

function ProjectFlowV2View() {
  const flow = phaseData?.projectFlow ?? {}
  const entries = projectFlowEntries()
  const totalViews = countProjectFlowViews(entries)
  const totalActions = countProjectFlowActions(entries)
  const sourcePath = phaseField(flow, 'sourcePath', 'docs/project/project-flow.json')

  return (
    <div className="grid gap-4">
      {phaseField(flow, 'error') && (
        <Card>
          <CardHeader>
            <CardTitle>Flow Source Error</CardTitle>
            <CardDescription>{phaseField(flow, 'error')}</CardDescription>
          </CardHeader>
        </Card>
      )}
      {entries.length === 0
        ? <ProjectFlowEmptyState sourcePath={sourcePath} label="Data Structure V2" />
        : <ProjectFlowNetworkView entries={entries} totalViews={totalViews} totalActions={totalActions} sourcePath={sourcePath} />}
    </div>
  )
}

type AiFlowNode = ProjectFlowNetworkNode & {
  evidence: string
}

function buildAiFlowNetwork(flowKey: string, sectionKey: string, memorySummary: Record<string, any> = {}, recentJobs: Array<Record<string, any>> = [], activeJob: AiJobPayload | null = null): { nodes: AiFlowNode[]; edges: ProjectFlowNetworkEdge[]; width: number; height: number } {
  const width = 1080
  const height = 680
  const centerX = width / 2
  const centerY = height / 2
  const currentFlow = uiUxFlowKindLabel(flowKey)
  const fallbackSectionLabel = sectionKey.split('-').map((part) => part.charAt(0).toUpperCase() + part.slice(1)).join(' ')
  const currentSection = phaseField(uiUxFlowSections(flowKey).find((section) => phaseField(section, 'key') === sectionKey), 'label', fallbackSectionLabel)
  const selectedGroups = uiUxFlowSections(flowKey).find((section) => phaseField(section, 'key') === sectionKey)?.groups
  const groupCount = Array.isArray(selectedGroups) ? selectedGroups.length : 0
  const phaseMemory = memorySummary.phase && typeof memorySummary.phase === 'object' ? memorySummary.phase : null
  const generalMemory = memorySummary.general && typeof memorySummary.general === 'object' ? memorySummary.general : {}
  const memoryScope = activeJob?.memory_scope_id || phaseMemory?.scope_id || generalMemory.scope_id || 'general'
  const memoryTokenEstimate = activeJob?.token_usage?.context_tokens_estimated || phaseMemory?.estimated_tokens || 0
  const recentJobCount = recentJobs.length
  const observedJob = activeJob || (recentJobs[0] as AiJobPayload | undefined) || null
  const activeJobStatus = observedJob?.status || 'ready'
  const observedAction = observedJob?.action || 'No explicit action'
  const workerCount = observedJob?.provenance?.worker_count || observedJob?.context?.worker_count || 'targeted'
  const totalProjectPhases = phaseData?.phases?.length || 0
  const totalProjectTasks = phaseData?.tasks?.length || 0
  const nodes: AiFlowNode[] = [
    { id: 'root', label: 'Scoped AI Runtime', detail: `${currentFlow} / ${currentSection}`, evidence: `Read-only view of the scoped AI lifecycle for ${currentFlow} / ${currentSection}. Latest status: ${activeJobStatus}. Opening this page never calls a model.`, kind: 'root', x: centerX, y: centerY, radius: 6 },
    { id: 'screen', label: 'Scope Router', detail: `${currentFlow} / ${currentSection}`, evidence: `The URL selects the active UI-UX flow and section. All later context and actions stay inside this scope until the user changes it.`, kind: 'entry', x: centerX, y: centerY - 150, radius: 3.5 },
    { id: 'clicks', label: 'Flow Snapshot', detail: `${groupCount} groups`, evidence: `Captures the selected section, groups, phase/task/note links, form and database metadata, and source setting as one compact snapshot.`, kind: 'view', x: centerX - 250, y: centerY - 54, radius: 3 },
    { id: 'forms', label: 'Action Gate', detail: observedAction, evidence: 'AI work starts only from an explicit scoped action such as Read Flow, Consolidate, Polish All, or a targeted builder request.', kind: 'view', x: centerX + 250, y: centerY - 54, radius: 3 },
    { id: 'phase-model', label: 'Memory Pack', detail: `${totalProjectPhases} phases / ${totalProjectTasks} tasks`, evidence: 'Builds one bounded handoff from current records, selected flow snapshot, custom rules, source hashes, exclusions, and token estimates.', kind: 'table', x: centerX - 285, y: centerY + 92, radius: 3 },
    { id: 'ai-controls', label: 'Chat Handoff', detail: `${workerCount} scoped roles`, evidence: 'Builds one bounded prompt for the active VS Code Codex Chat session. BuilderX does not start independent local workers.', kind: 'action', x: centerX + 285, y: centerY + 92, radius: 3 },
    { id: 'json-submit', label: 'Chat Request', detail: 'queued / running / done', evidence: 'Stages the scoped prompt, opens the visible Codex Chat handoff, and validates the returned result before it is applied.', kind: 'action', x: centerX, y: centerY + 160, radius: 2.5 },
    { id: 'background-flag', label: 'Execution Policy', detail: 'bounded background run', evidence: 'Background actions are explicitly allow-listed. Health, preview, and readiness checks use zero model workers; write actions remain approval-gated.', kind: 'action', x: centerX + 210, y: centerY + 220, radius: 2.5 },
    { id: 'php-dispatch', label: 'Coordinator Merge', detail: 'collect / dedupe / validate', evidence: 'The coordinator collects targeted worker results, removes duplicate findings, detects conflicts, validates source hashes, and produces one compact result.', kind: 'entry', x: centerX, y: centerY + 272, radius: 3 },
    { id: 'job-store', label: 'Job Checkpoints', detail: `${recentJobCount} recent jobs`, evidence: 'Stores prompt provenance, selected context, checkpoints, token estimates, result state, retry data, and errors for restart recovery and inspection.', kind: 'table', x: centerX - 250, y: centerY + 232, radius: 3 },
    { id: 'memory-resolver', label: 'Bounded RAG', detail: memoryScope, evidence: `Retrieves only relevant phase memory and approved project guidance. Current estimated memory context: ${memoryTokenEstimate} tokens; sibling phase memory is excluded.`, kind: 'table', x: centerX - 430, y: centerY + 232, radius: 3 },
    { id: 'token-meter', label: 'Token Budget', detail: `${observedJob?.token_usage?.total_tokens_estimated || 0} estimated`, evidence: 'Tracks prompt, retrieved context, completion, total usage, and estimated savings so each execution harvests useful results without repeating large prompts.', kind: 'table', x: centerX + 430, y: centerY + 232, radius: 3 },
    { id: 'worker', label: 'Codex Chat', detail: 'visible session', evidence: 'Receives the scoped request in the active VS Code Codex Chat session. Independent panel prompt injection and worker result APIs are not exposed by the installed extension.', kind: 'action', x: centerX - 250, y: centerY + 340, radius: 3 },
    { id: 'ai-runtime', label: 'Result Validator', detail: 'schema / scope / conflicts', evidence: 'Checks structured output against the selected scope, source hashes, custom rules, worker completeness, and conflict state before it can be applied.', kind: 'action', x: centerX, y: centerY + 410, radius: 3 },
    { id: 'saved-result', label: 'Approval Gate', detail: 'draft until approved', evidence: 'Keeps recommendations and first-time UI contracts as drafts. A human approval is required before mutations, migrations, or reusable patterns are saved.', kind: 'table', x: centerX + 250, y: centerY + 340, radius: 3 },
    { id: 'footer-status', label: 'Memory Preserve', detail: 'result + provenance', evidence: 'Persists the approved result, source hash, compact summary, rollback metadata, and lessons. Only approved summaries are promoted to reusable RAG memory.', kind: 'view', x: centerX + 250, y: centerY + 232, radius: 3 },
  ]
  const edges: ProjectFlowNetworkEdge[] = [
    { id: 'root-screen', from: 'root', to: 'screen', kind: 'primary' },
    { id: 'screen-clicks', from: 'screen', to: 'clicks', kind: 'primary' },
    { id: 'screen-forms', from: 'screen', to: 'forms', kind: 'primary' },
    { id: 'screen-phase-model', from: 'screen', to: 'phase-model', kind: 'secondary' },
    { id: 'clicks-memory-resolver', from: 'clicks', to: 'memory-resolver', kind: 'primary' },
    { id: 'memory-resolver-phase-model', from: 'memory-resolver', to: 'phase-model', kind: 'primary' },
    { id: 'phase-model-ai-controls', from: 'phase-model', to: 'ai-controls', kind: 'primary' },
    { id: 'forms-ai-controls', from: 'forms', to: 'ai-controls', kind: 'primary' },
    { id: 'ai-controls-background-flag', from: 'ai-controls', to: 'background-flag', kind: 'primary' },
    { id: 'background-flag-json-submit', from: 'background-flag', to: 'json-submit', kind: 'secondary' },
    { id: 'forms-json-submit', from: 'forms', to: 'json-submit', kind: 'secondary' },
    { id: 'json-submit-php-dispatch', from: 'json-submit', to: 'php-dispatch', kind: 'primary' },
    { id: 'php-dispatch-job-store', from: 'php-dispatch', to: 'job-store', kind: 'secondary' },
    { id: 'php-dispatch-worker', from: 'php-dispatch', to: 'worker', kind: 'primary' },
    { id: 'worker-ai-runtime', from: 'worker', to: 'ai-runtime', kind: 'primary' },
    { id: 'worker-token-meter', from: 'worker', to: 'token-meter', kind: 'secondary' },
    { id: 'ai-runtime-saved-result', from: 'ai-runtime', to: 'saved-result', kind: 'primary' },
    { id: 'ai-runtime-footer-status', from: 'ai-runtime', to: 'footer-status', kind: 'secondary' },
    { id: 'job-store-footer-status', from: 'job-store', to: 'footer-status', kind: 'primary' },
    { id: 'saved-result-footer-status', from: 'saved-result', to: 'footer-status', kind: 'primary' },
    { id: 'footer-status-root', from: 'footer-status', to: 'root', kind: 'secondary' },
  ]

  return { nodes, edges, width, height }
}

function AiFlowView() {
  const flowKey = selectedUiUxFlowKey()
  const sectionKey = phaseField(selectedUiUxFlowSection(flowKey), 'key', 'header')
  const aiMonitor = useAiJobMonitor()
  const recentJobs = Array.isArray(phaseData?.aiRecentJobs) ? phaseData.aiRecentJobs : []
  const latestJob = aiMonitor.activeJob || (recentJobs[0] as AiJobPayload | undefined) || null
  const graph = buildAiFlowNetwork(flowKey, sectionKey, phaseData?.aiMemory || {}, recentJobs, aiMonitor.activeJob)
  const svgRef = React.useRef<SVGSVGElement>(null)
  const dragRef = React.useRef<
    | { mode: 'node'; nodeId: string; offsetX: number; offsetY: number }
    | { mode: 'pan'; startX: number; startY: number; originX: number; originY: number }
    | null
  >(null)
  const [positions, setPositions] = React.useState<Record<string, ProjectFlowNodePosition>>({})
  const [viewport, setViewport] = React.useState({ x: 0, y: 0, scale: 0.98 })
  const [selectedNodeId, setSelectedNodeId] = React.useState('root')
  const nodes = React.useMemo(() => graph.nodes.map((node) => {
    const position = positions[node.id]

    return position ? { ...node, x: position.x, y: position.y } : node
  }), [graph.nodes, positions])
  const nodesById = new Map(nodes.map((node) => [node.id, node]))
  const selectedNode = nodesById.get(selectedNodeId) || nodes[0]
  const aiProcessing = ['queued', 'running'].includes(aiMonitor.activeJob?.status || '')
  const aiStatusLabel = latestJob?.status || 'ready'
  const memoryScope = aiMonitor.activeJob?.memory_scope_id || phaseData?.aiMemory?.phase?.scope_id || phaseData?.aiMemory?.general?.scope_id || 'general'
  const estimatedTokens = latestJob?.token_usage?.total_tokens_estimated || latestJob?.token_usage?.total_tokens || 0
  const processItems = [
    aiProcessing
      ? `${aiMonitor.activeJob?.label || 'AI task'} is ${aiStatusLabel}.`
      : latestJob
        ? `Latest recorded job: ${latestJob.label || latestJob.action || 'AI action'} (${latestJob.status}).`
        : 'No recorded AI job is currently available.',
    `Scope Router locks this run to ${uiUxFlowKindLabel(flowKey)} / ${phaseField(selectedUiUxFlowSection(flowKey), 'label', sectionKey)}.`,
    'Flow Snapshot and custom rules become one bounded memory pack.',
    `Bounded RAG resolves ${memoryScope}; sibling phase memory is excluded.`,
    'Chat Handoff sends one scoped request to the active VS Code Codex Chat session.',
    'BuilderX validates the returned Chat result once before saving it.',
    'Validator checks schema, scope, conflicts, and approval state before any write.',
    'Approved summaries preserve provenance and become reusable memory; drafts do not.',
  ]

  function clampZoom(value: number): number {
    return Math.min(2.4, Math.max(0.45, value))
  }

  function svgPointerPoint(event: React.PointerEvent<SVGSVGElement | SVGGElement>) {
    const svg = svgRef.current
    if (!svg) return { x: graph.width / 2, y: graph.height / 2 }

    const rect = svg.getBoundingClientRect()
    return {
      x: ((event.clientX - rect.left) / rect.width) * graph.width,
      y: ((event.clientY - rect.top) / rect.height) * graph.height,
    }
  }

  function contentPoint(point: { x: number; y: number }): { x: number; y: number } {
    return {
      x: (point.x - viewport.x) / viewport.scale,
      y: (point.y - viewport.y) / viewport.scale,
    }
  }

  function zoomAt(rawPoint: { x: number; y: number }, nextScale: number) {
    setViewport((current) => {
      const scale = clampZoom(nextScale)
      const contentX = (rawPoint.x - current.x) / current.scale
      const contentY = (rawPoint.y - current.y) / current.scale

      return {
        scale,
        x: rawPoint.x - contentX * scale,
        y: rawPoint.y - contentY * scale,
      }
    })
  }

  React.useEffect(() => {
    const svg = svgRef.current
    if (!svg) return undefined
    const svgElement = svg

    function handleNativeWheel(event: WheelEvent) {
      event.preventDefault()
      const rect = svgElement.getBoundingClientRect()
      const rawPoint = {
        x: ((event.clientX - rect.left) / rect.width) * graph.width,
        y: ((event.clientY - rect.top) / rect.height) * graph.height,
      }
      setViewport((current) => {
        const scale = clampZoom(current.scale * (event.deltaY < 0 ? 1.1 : 0.9))
        const contentX = (rawPoint.x - current.x) / current.scale
        const contentY = (rawPoint.y - current.y) / current.scale

        return {
          scale,
          x: rawPoint.x - contentX * scale,
          y: rawPoint.y - contentY * scale,
        }
      })
    }

    svgElement.addEventListener('wheel', handleNativeWheel, { passive: false })
    return () => svgElement.removeEventListener('wheel', handleNativeWheel)
  }, [graph.height, graph.width])

  const fitViewport = React.useCallback(() => {
    const svg = svgRef.current
    const surface = svg?.parentElement
    if (!surface) return

    const rect = surface.getBoundingClientRect()
    const scale = clampZoom(Math.min((rect.width - 48) / graph.width, (rect.height - 48) / graph.height))
    setViewport({
      scale,
      x: (graph.width - graph.width * scale) / 2,
      y: (graph.height - graph.height * scale) / 2,
    })
  }, [graph.height, graph.width])

  React.useEffect(() => {
    const svg = svgRef.current
    const surface = svg?.parentElement
    if (!surface) return undefined

    const frame = window.requestAnimationFrame(fitViewport)
    const observer = typeof ResizeObserver !== 'undefined' ? new ResizeObserver(fitViewport) : null
    observer?.observe(surface)

    return () => {
      window.cancelAnimationFrame(frame)
      observer?.disconnect()
    }
  }, [fitViewport])

  function handleNodePointerDown(event: React.PointerEvent<SVGGElement>, node: AiFlowNode) {
    event.preventDefault()
    event.stopPropagation()
    const point = contentPoint(svgPointerPoint(event))
    dragRef.current = { mode: 'node', nodeId: node.id, offsetX: point.x - node.x, offsetY: point.y - node.y }
    setSelectedNodeId(node.id)
    event.currentTarget.setPointerCapture(event.pointerId)
  }

  function handleSvgPointerDown(event: React.PointerEvent<SVGSVGElement>) {
    const point = svgPointerPoint(event)
    dragRef.current = { mode: 'pan', startX: point.x, startY: point.y, originX: viewport.x, originY: viewport.y }
    event.currentTarget.setPointerCapture(event.pointerId)
  }

  function handleSvgPointerMove(event: React.PointerEvent<SVGSVGElement>) {
    const drag = dragRef.current
    if (!drag) return
    const point = svgPointerPoint(event)
    if (drag.mode === 'pan') {
      setViewport((current) => ({ ...current, x: drag.originX + point.x - drag.startX, y: drag.originY + point.y - drag.startY }))
      return
    }
    const nextPoint = contentPoint(point)
    setPositions((current) => ({ ...current, [drag.nodeId]: { x: Math.round(nextPoint.x - drag.offsetX), y: Math.round(nextPoint.y - drag.offsetY) } }))
  }

  function resetLayout() {
    dragRef.current = null
    setPositions({})
    fitViewport()
    setSelectedNodeId('root')
  }

  function stopDrag() {
    dragRef.current = null
  }

  return (
    <Card className="min-w-0 overflow-hidden border-border/80 shadow-sm">
      <CardHeader className="flex min-h-16 min-w-0 flex-col gap-2 border-b bg-muted/20 py-3 lg:flex-row lg:items-center lg:justify-between">
        <div className="min-w-0">
          <Badge variant="secondary">Scoped AI Flow</Badge>
          <CardTitle className="mt-1 truncate text-base tracking-normal">{uiUxFlowKindLabel(flowKey)} / {phaseField(selectedUiUxFlowSection(flowKey), 'label', sectionKey)} Lifecycle</CardTitle>
          <CardDescription className="mt-1 text-xs">Read-only execution map for the current scope. AI runs only from explicit scoped actions.</CardDescription>
        </div>
        <div className="flex min-w-0 flex-wrap items-center justify-end gap-2 text-xs text-muted-foreground">
          <Badge variant="outline" className={cn('gap-1.5', aiProcessing ? 'border-amber-500/50 text-amber-700 dark:text-amber-300' : 'border-emerald-500/50 text-emerald-700 dark:text-emerald-300')}>
            <span className={cn('size-1.5 rounded-full', aiProcessing ? 'bg-amber-500' : 'bg-emerald-500')} aria-hidden="true" />
            {aiProcessing ? `AI ${aiStatusLabel}` : latestJob ? `Last ${aiStatusLabel}` : 'AI ready'}
          </Badge>
          <Button type="button" variant="outline" size="sm" onClick={() => { window.location.href = phaseLocalHref({ view: 'flow', ui_ux_flow: flowKey, ui_ux_section: sectionKey }) }}>
            <ExternalLink />
            Open Flow
          </Button>
          <Badge variant="outline">{graph.nodes.length} Nodes</Badge>
          <Badge variant="outline">{graph.edges.length} Links</Badge>
          <Badge variant="outline">{aiBackgroundActions.size} Background AI Actions</Badge>
          <Tooltip>
            <TooltipTrigger render={<Button type="button" variant="outline" size="icon-sm" aria-label="Zoom out" onClick={() => zoomAt({ x: graph.width / 2, y: graph.height / 2 }, viewport.scale * 0.85)} />}>
              <ZoomOut />
            </TooltipTrigger>
            <TooltipContent>Zoom Out</TooltipContent>
          </Tooltip>
          <Badge variant="secondary" className="min-w-14 justify-center">{Math.round(viewport.scale * 100)}%</Badge>
          <Tooltip>
            <TooltipTrigger render={<Button type="button" variant="outline" size="icon-sm" aria-label="Zoom in" onClick={() => zoomAt({ x: graph.width / 2, y: graph.height / 2 }, viewport.scale * 1.15)} />}>
              <ZoomIn />
            </TooltipTrigger>
            <TooltipContent>Zoom In</TooltipContent>
          </Tooltip>
          <Button type="button" variant="outline" size="sm" onClick={resetLayout}>
            <RotateCcw />
            Reset
          </Button>
        </div>
      </CardHeader>
      <CardContent className="p-0">
        <div className="grid min-w-0 gap-px border-b border-white/10 bg-white/10 sm:grid-cols-2 xl:grid-cols-4">
          <div className="min-w-0 bg-[#0b1020] px-4 py-3">
            <span className="block text-[10px] uppercase tracking-wider text-slate-400">Scope</span>
            <strong className="mt-1 block truncate text-sm text-slate-100">{uiUxFlowKindLabel(flowKey)} / {phaseField(selectedUiUxFlowSection(flowKey), 'label', sectionKey)}</strong>
          </div>
          <div className="min-w-0 bg-[#0b1020] px-4 py-3">
            <span className="block text-[10px] uppercase tracking-wider text-slate-400">Memory</span>
            <strong className="mt-1 block truncate font-mono text-xs text-emerald-300">{memoryScope}</strong>
          </div>
          <div className="min-w-0 bg-[#0b1020] px-4 py-3">
            <span className="block text-[10px] uppercase tracking-wider text-slate-400">Latest job</span>
            <strong className="mt-1 block truncate text-sm text-slate-100">{latestJob?.label || latestJob?.action || 'None recorded'}</strong>
          </div>
          <div className="min-w-0 bg-[#0b1020] px-4 py-3">
            <span className="block text-[10px] uppercase tracking-wider text-slate-400">Estimated tokens</span>
            <strong className="mt-1 block text-sm text-sky-300">{estimatedTokens || 'Bounded'}</strong>
          </div>
        </div>
        <div className="grid min-w-0 bg-[#101726] lg:grid-cols-[minmax(0,1fr)_320px]">
          <div className="relative h-[calc(100vh-350px)] min-h-[360px] min-w-0 overflow-hidden bg-[radial-gradient(circle_at_50%_48%,rgba(31,51,87,0.82)_0%,rgba(20,36,63,0.74)_58%,#0b1020_100%)]">
            <svg
              ref={svgRef}
              width="100%"
              height="100%"
              viewBox={`0 0 ${graph.width} ${graph.height}`}
              preserveAspectRatio="xMidYMid meet"
              role="img"
              aria-label="AI Flow centered process graph"
              className="h-full w-full touch-none"
              onPointerDown={handleSvgPointerDown}
              onPointerMove={handleSvgPointerMove}
              onPointerUp={stopDrag}
              onPointerCancel={stopDrag}
              onPointerLeave={stopDrag}
            >
              <defs>
                <filter id="ai-flow-glow" x="-60%" y="-60%" width="220%" height="220%">
                  <feGaussianBlur stdDeviation="4" result="blur" />
                  <feMerge>
                    <feMergeNode in="blur" />
                    <feMergeNode in="SourceGraphic" />
                  </feMerge>
                </filter>
              </defs>
              <rect width={graph.width} height={graph.height} fill="transparent" />
              <g transform={`translate(${viewport.x} ${viewport.y}) scale(${viewport.scale})`}>
                {graph.edges.map((edge) => {
                  const from = nodesById.get(edge.from)
                  const to = nodesById.get(edge.to)
                  if (!from || !to) return null
                  const active = selectedNodeId === from.id || selectedNodeId === to.id

                  return (
                    <line
                      key={edge.id}
                      x1={from.x}
                      y1={from.y}
                      x2={to.x}
                      y2={to.y}
                      stroke={active ? '#8fd3ff' : '#5f7fb8'}
                      strokeOpacity={active ? 0.92 : edge.kind === 'primary' ? 0.48 : 0.3}
                      strokeWidth={active ? 1.8 : edge.kind === 'primary' ? 1.1 : 0.8}
                      strokeDasharray={aiProcessing ? '5 5' : undefined}
                      vectorEffect="non-scaling-stroke"
                    />
                  )
                })}
                {nodes.map((node) => {
                  const selected = selectedNodeId === node.id
                  const color = node.kind === 'root'
                    ? '#f8fbff'
                    : node.kind === 'entry'
                      ? '#60a5fa'
                      : node.kind === 'view'
                        ? '#93c5fd'
                        : node.kind === 'table'
                          ? '#34d399'
                          : '#a78bfa'
                  const labelOffset = node.kind === 'root' ? 18 : 14

                  return (
                    <g
                      key={node.id}
                      className="cursor-move"
                      onPointerDown={(event) => handleNodePointerDown(event, node)}
                      onClick={(event) => {
                        event.stopPropagation()
                        setSelectedNodeId(node.id)
                      }}
                      filter={selected || node.kind === 'root' ? 'url(#ai-flow-glow)' : undefined}
                    >
                      <circle
                        cx={node.x}
                        cy={node.y}
                        r={selected ? node.radius + 1.5 : node.radius}
                        fill={color}
                        fillOpacity={node.kind === 'root' ? 1 : 0.92}
                        stroke={selected ? '#ffffff' : '#b9d9ff'}
                        strokeOpacity={selected ? 0.98 : 0.58}
                        strokeWidth={selected ? 1.6 : 0.8}
                        vectorEffect="non-scaling-stroke"
                      />
                      <text x={node.x} y={node.y + labelOffset} textAnchor="middle" fill={selected ? '#ffffff' : '#9dccff'} className="pointer-events-none select-none text-[10px] font-medium">
                        {node.label}
                      </text>
                      <text x={node.x} y={node.y + labelOffset + 12} textAnchor="middle" fill="#83a6d9" className="pointer-events-none select-none text-[8px]">
                        {truncateFlowLabel(node.detail, 30)}
                      </text>
                    </g>
                  )
                })}
              </g>
            </svg>
          </div>
          <aside className="min-w-0 overflow-y-auto border-t border-white/10 bg-[#0b1020]/90 p-4 text-slate-200 lg:border-l lg:border-t-0">
            <div className="flex items-center gap-2">
              <Activity className={cn('text-sky-300', aiProcessing && 'animate-pulse')} />
              <h3 className="text-sm font-semibold tracking-normal">Selected Step</h3>
            </div>
            <div className="mt-4 rounded-md border border-white/10 bg-white/[0.04] p-3">
              <p className="text-base font-semibold text-white">{selectedNode?.label || 'AI Flow'}</p>
              <p className="mt-1 text-xs uppercase text-sky-200">{selectedNode?.kind || 'root'}</p>
              <p className="mt-3 text-sm leading-6 text-slate-300">{selectedNode?.evidence || selectedNode?.detail}</p>
            </div>
            <div className="mt-4 grid gap-2 text-xs text-slate-300">
              {processItems.map((item, index) => (
                <div key={item} className="grid grid-cols-[24px_minmax(0,1fr)] gap-2 rounded-md border border-white/10 px-3 py-2">
                  <span className="text-sky-200">{index + 1}</span>
                  <span>{item}</span>
                </div>
              ))}
            </div>
          </aside>
        </div>
      </CardContent>
    </Card>
  )
}

