  function togglePhaseAiOperationMode() {
    setPhaseAiOperationMode((current) => {
      const next = current === 'devops' ? 'scoped' : 'devops'
      try {
        window.localStorage.setItem(`${phaseAiOperationStorageKey}:mode`, next)
      } catch {
        // Mode persistence can be unavailable in restricted browser contexts.
      }
      return next
    })
  }

  function openPhaseAiOperationModal(source: 'flow' | 'database' | 'form' = 'flow', jobId = '') {
    setPhaseAiOperationSource(source)
    setPhaseOperationDatabaseRequested(source === 'database')
    setPhaseAiOperationModalOpen(true)
    void refreshPhaseAiOperationStatus(jobId)
  }

  openPhaseAiOperationModalRef.current = openPhaseAiOperationModal

  React.useEffect(() => {
    function openPhaseAiOperationFromFooter(event: Event) {
      const job = (event as CustomEvent<AiJobPayload | null>).detail
      if (job?.id) {
        setUiUxFlowLastAiJob(job)
        recordPhaseOperationJobEventRef.current(job)
      }
      openPhaseAiOperationModalRef.current('flow', job?.id || '')
    }

    window.addEventListener(phaseAiOperationOpenEvent, openPhaseAiOperationFromFooter)
    if (phaseAiOperationRequestedOnLoad && !phaseAiOperationAutoOpenHandledRef.current) {
      phaseAiOperationAutoOpenHandledRef.current = true
      openPhaseAiOperationModalRef.current('flow', phaseAiOperationRequestedJobId)
      const nextUrl = new URL(window.location.href)
      nextUrl.searchParams.delete(phaseAiOperationOpenParam)
      nextUrl.searchParams.delete(phaseAiOperationJobParam)
      window.history.replaceState(window.history.state, '', `${nextUrl.pathname}${nextUrl.search}${nextUrl.hash}`)
    }
    return () => window.removeEventListener(phaseAiOperationOpenEvent, openPhaseAiOperationFromFooter)
  }, [phaseAiOperationRequestedJobId, phaseAiOperationRequestedOnLoad, phaseAiOperationStorageKey])

  React.useEffect(() => {
    if (!phaseAiOperationModalOpen) return undefined
    let cancelled = false

    const loadSystemHealth = async () => {
      try {
        const formData = new FormData()
        formData.set('csrf', phaseData?.csrf || '')
        formData.set('action', 'ai_operation_system_health')
        const response = await fetch('./', {
          method: 'POST',
          body: formData,
          headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' },
        })
        const contentType = response.headers.get('content-type') || ''
        if (!contentType.includes('application/json')) throw new Error('System health returned a non-JSON response.')
        const result = await response.json()
        if (cancelled) return
        const health = result?.data?.system_health || {}
        const metric = (value: unknown): number | null => {
          const numeric = Number(value)
          return Number.isFinite(numeric) ? numeric : null
        }
        setPhaseOperationSystemHealth({
          status: (result.ok || result.success) && health.status === 'online' ? 'online' : 'unavailable',
          health_percent: metric(health.health_percent),
          cpu_percent: metric(health.cpu_percent),
          ram_percent: metric(health.ram_percent),
          temperature_c: metric(health.temperature_c),
          checked_at: String(health.checked_at || ''),
        })
      } catch {
        if (!cancelled) setPhaseOperationSystemHealth((current) => ({ ...current, status: 'unavailable' }))
      }
    }

    setPhaseOperationSystemHealth((current) => ({ ...current, status: 'checking' }))
    void loadSystemHealth()
    const intervalId = window.setInterval(loadSystemHealth, 3000)
    return () => {
      cancelled = true
      window.clearInterval(intervalId)
    }
  }, [phaseAiOperationModalOpen])

  React.useEffect(() => {
    if (!phaseAiOperationDemoActive) {
      setPhaseAiOperationDemoStep(0)
      setPhaseAiOperationDemoWorkerStatuses({})
      return undefined
    }

    setPhaseAiOperationDemoStep(0)
    setPhaseAiOperationDemoWorkerStatuses({})
    let step = 0
    const workerKeys = ['database', 'form', 'ui', 'security', 'verification']
    const timer = window.setInterval(() => {
      step += 1
      if (step >= 15) {
        window.clearInterval(timer)
        setPhaseAiOperationDemoActive(false)
        setPhaseAiOperationDemoStep(0)
        setPhaseAiOperationDemoWorkerStatuses({})
        return
      }
      setPhaseAiOperationDemoStep(step)
      setPhaseAiOperationDemoWorkerStatuses((current) => {
        if (step < 2) return {}
        if (step >= 14) return Object.fromEntries(workerKeys.map((key) => [key, 'Done']))

        const next = { ...current }
        workerKeys.forEach((key) => {
          if (next[key] === 'Done') delete next[key]
        })
        workerKeys.forEach((key) => {
          if (next[key] === 'Working' && Math.random() < 0.38) next[key] = 'Done'
        })
        const working = () => workerKeys.filter((key) => next[key] === 'Working').length
        const queued = () => workerKeys.filter((key) => !next[key] || next[key] === 'N/A')
        const target = Math.min(4, 2 + Math.floor(Math.random() * 3))
        while (working() < target && queued().length > 0) {
          const available = queued()
          const key = available[Math.floor(Math.random() * available.length)]
          next[key] = 'Working'
        }
        return next
      })
    }, 1000)
    return () => window.clearInterval(timer)
  }, [phaseAiOperationDemoActive])

  function startPhaseAiOperationDemo() {
    if (phaseAiOperationDemoActive || uiUxFlowAiJobProcessing || uiUxBatchPolishBusy) return
    setPhaseAiOperationDemoStep(0)
    setPhaseAiOperationDemoWorkerStatuses({})
    setPhaseAiOperationDemoActive(true)
  }

  function runPhaseAiOperationRead() {
    if (phaseAiOperationMode !== 'devops') {
      void runUiUxFlowAiPlan('run_ui_ux_flow_ai_plan')
      return
    }

    const action = Object.keys(uiUxFlowAiPlan).length > 0 ? 'respond_ui_ux_flow_ai_plan' : 'run_ui_ux_flow_ai_plan'
    void runUiUxFlowAiPlan(action, 'DevOps mode: create a compact implementation guide for the selected UI - UX flow. Cover database and migration readiness, field and form validation, security and permissions, testing, deployment, rollback, and operational checks. Keep the guide scoped to the current flow snapshot. Do not execute commands or change files, database records, infrastructure, or deployments.')
  }
  const [uiUxFlowAiFocusPhaseCode, setUiUxFlowAiFocusPhaseCode] = React.useState('ALL')
  const [uiUxFlowAiFocusTaskCode, setUiUxFlowAiFocusTaskCode] = React.useState('NONE')
