  const [uiUxFlowAiChatQueue, setUiUxFlowAiChatQueue] = React.useState<Array<Record<string, any>>>([])
  const [uiUxFlowAiCopiedKey, setUiUxFlowAiCopiedKey] = React.useState('')
  const [noteChatSearch, setNoteChatSearch] = React.useState('')
  const [noteChatStatusFilter, setNoteChatStatusFilter] = React.useState('all')
  const [noteChatSort, setNoteChatSort] = React.useState<'newest' | 'oldest'>('newest')
  const [noteChatSelectedKey, setNoteChatSelectedKey] = React.useState('')
