  function recordPhaseOperationJobEvent(job: AiJobPayload) {
    const eventKey = `${job.id}:${job.status}:${job.updated_at || job.message || job.segment_index || ''}`
    if (eventKey === phaseOperationLastEventRef.current) return

    phaseOperationLastEventRef.current = eventKey
    const isBuilderAction = job.action === 'run_ui_ux_flow_builder_codex'
    const isNoteConsolidation = ['review_note_codex', 'respond_note_review', 'consolidate_note_review'].includes(job.action)
    const operationLabel = isBuilderAction ? 'Scoped Builder action' : isNoteConsolidation ? 'Consolidate note planning' : job.label || 'AI action'
    const statusMessage = job.status === 'queued'
      ? `${operationLabel} queued as one scoped Codex Chat job.`
      : job.status === 'running'
        ? `${operationLabel} is running through the configured Codex Chat.`
        : job.status === 'completed'
          ? `${operationLabel} completed and reported its result.`
          : job.status === 'failed'
            ? `${operationLabel} failed: ${job.error || job.message || 'The AI job failed.'}`
            : `${operationLabel} is ${job.status}.`
    const timestamp = job.updated_at || job.created_at
    setPhaseOperationEvents((current) => [...current, {
      id: eventKey,
      time: timestamp ? new Date(timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }) : '--:--:--',
      worker: 'Codex Chat',
      text: job.message && job.status === 'running' ? job.message : statusMessage,
      status: job.status,
    }].slice(-20))
  }

  recordPhaseOperationJobEventRef.current = recordPhaseOperationJobEvent

  React.useEffect(() => {
    function handleUiUxFlowAiJobUpdate(event: Event) {
      const job = (event as CustomEvent<AiJobPayload>).detail
      const operationActions = ['run_ui_ux_flow_ai_plan', 'respond_ui_ux_flow_ai_plan', 'run_ui_ux_flow_builder_codex']
      if (!job?.id || !operationActions.includes(job.action)) return

      const jobFlow = phaseField(job.context, 'ui_ux_flow')
      const jobSection = phaseField(job.context, 'ui_ux_section')
      if (jobFlow !== flowKey || jobSection !== sectionKey) return

      setUiUxFlowLastAiJob(job)
      recordPhaseOperationJobEvent(job)

      if (job.status === 'completed') {
        const nextPlan = job.result?.data?.ui_ux_flow_ai_plan
        if (nextPlan && typeof nextPlan === 'object' && !Array.isArray(nextPlan)) {
          setUiUxFlowAiPlan(nextPlan)
          if (phaseData) {
            phaseData.uiUxFlowAiPlan = nextPlan
          }
        }
      }

      if (['completed', 'failed', 'cancelled', 'rolled_back'].includes(job.status)) {
        setUiUxFlowAiBusy(false)
      }
    }

    window.addEventListener(aiJobUpdatedEvent, handleUiUxFlowAiJobUpdate)
    return () => window.removeEventListener(aiJobUpdatedEvent, handleUiUxFlowAiJobUpdate)
  }, [flowKey, sectionKey, savedUiUxFlowBuilderResult])

  React.useEffect(() => {
    const refreshActions = new Set([
      'update_note_codex_grammar',
      'update_project_phase_codex_grammar',
      'update_phase_subphase_codex_grammar',
      'suggest_note_database_codex',
      'respond_note_database_codex',
      'suggest_note_form_codex',
      'fix_note_form_settings_codex',
      'run_ui_ux_flow_builder_codex',
      'run_project_phase_builder_codex',
    ])

    function handlePersistedAiJobUpdate(event: Event) {
      const job = (event as CustomEvent<AiJobPayload>).detail
      if (!job?.id) return

      const jobFlow = phaseField(job.context, 'ui_ux_flow')
      const jobSection = phaseField(job.context, 'ui_ux_section')
      if ((jobFlow !== '' && jobFlow !== flowKey) || (jobSection !== '' && jobSection !== sectionKey)) return
      const formSuggestionAction = job.action === 'suggest_note_form_codex' || job.action === 'fix_note_form_settings_codex'
      const formJobNoteKey = phaseField(job.context, 'note_key')
      const openFormNoteKey = phaseField(formBuilderNote, 'noteKey')
      if (formSuggestionAction && phaseAiOperationSource === 'form' && formJobNoteKey !== '' && formJobNoteKey === openFormNoteKey) {
        if (['queued', 'running'].includes(job.status)) {
          setFormAiBusyNoteKey(formJobNoteKey)
          setPhaseOperationEvents((current) => [...current, {
            id: `form-builder-${job.status}-${job.id}`,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
            worker: 'Form Builder',
            text: job.message || 'Form Builder is generating a compact form draft.',
            status: job.status,
          }].slice(-20))
          return
        }
        if (['completed', 'failed', 'cancelled', 'rolled_back'].includes(job.status)) {
          setFormAiBusyNoteKey('')
          if (job.status === 'completed') {
            const nextPayload = job.result?.data?.form_ai_payload
            const nextChat = job.result?.data?.form_ai_chat
            if (nextPayload && typeof nextPayload === 'object' && !Array.isArray(nextPayload)) {
              const nextOverride = {
                formEnabled: true,
                formStatus: 'ACTIVE',
                formAiPayload: nextPayload,
                formAiChat: Array.isArray(nextChat) ? nextChat : formBuilderNote?.formAiChat || [],
              }
              setFormBuilderOverrides((current) => ({ ...current, [formJobNoteKey]: nextOverride }))
              setFormBuilderNote((current) => current ? { ...current, ...nextOverride } : current)
              setPhaseOperationEvents((current) => [...current, {
                id: `form-builder-completed-${job.id}`,
                time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
                worker: 'Form Builder',
                text: 'Compact form draft completed and is ready for review.',
                status: 'completed',
              }].slice(-20))
            }
          } else {
            setPhaseOperationEvents((current) => [...current, {
              id: `form-builder-${job.status}-${job.id}`,
              time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
              worker: 'Form Builder',
              text: job.error || job.message || 'Form Builder generation did not complete.',
              status: job.status,
            }].slice(-20))
          }
          return
        }
      }

      const databaseSuggestionAction = job.action === 'suggest_note_database_codex' || job.action === 'respond_note_database_codex'
      const databaseJobNoteKey = phaseField(job.context, 'note_key')
      const openDatabaseNoteKey = phaseField(databaseStructureNote, 'noteKey')
      if (databaseSuggestionAction && databaseJobNoteKey !== '' && databaseJobNoteKey === openDatabaseNoteKey) {
        if (['queued', 'running'].includes(job.status)) {
          setDatabaseStructureAiJobId(job.id)
          setDatabaseStructureAiBusy(true)
          setDatabaseStructureAiMessage(job.message || 'AI is generating planned fields.')
          return
        }
        if (['completed', 'failed', 'cancelled', 'rolled_back'].includes(job.status)) {
          setDatabaseStructureAiJobId('')
          setDatabaseStructureAiBusy(false)
          if (job.status === 'completed') {
            const nextPayload = job.result?.data?.crud_ai_payload
            const nextChat = job.result?.data?.crud_ai_chat
            if (nextPayload && typeof nextPayload === 'object' && !Array.isArray(nextPayload)) {
              const nextOverride = {
                crudAiPayload: nextPayload,
                crudAiChat: Array.isArray(nextChat) ? nextChat : databaseStructureNote?.crudAiChat || [],
              }
              setDatabaseStructureOverrides((current) => ({ ...current, [databaseJobNoteKey]: nextOverride }))
              setDatabaseStructureNote((current) => current ? { ...current, ...nextOverride } : current)
              setDatabaseStructureAiMessage('Basic fields generated from the note and database rules. Review the draft before migration.')
            } else {
              setDatabaseStructureAiMessage('AI completed without returning planned fields.')
            }
          } else {
            setDatabaseStructureAiMessage(job.error || job.message || 'AI field generation did not complete.')
          }
          return
        }
      }

      if (job.status !== 'completed' || !refreshActions.has(job.action)) return

      // These jobs write the canonical phase/note/form/database payload on the server.
      // Reload once after completion so every diagram symbol reads the same fresh snapshot.
      reloadPagePreservingScroll()
    }

    window.addEventListener(aiJobUpdatedEvent, handlePersistedAiJobUpdate)
      return () => window.removeEventListener(aiJobUpdatedEvent, handlePersistedAiJobUpdate)
  }, [flowKey, sectionKey, phaseAiOperationModalOpen, phaseAiOperationSource, databaseStructureNote, formBuilderNote])

