    setConnectionCrudField(phaseField(connectionNote, 'crudFieldName', 'NONE') || 'NONE')
    setConnectionNewTableName(phaseField(connectionNote, 'crudNewTableName'))
    setConnectionNewFieldName(phaseField(connectionNote, 'crudNewFieldName'))
