  async function runFlowSoftDeleteAction(request: NonNullable<typeof flowDeleteConfirm>) {
    const { action, keyName, keyValue } = request
    if (keyValue === '') return

    const formData = new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', action)
    formData.set(keyName, keyValue)
    formData.set('source_view', 'flow')
    formData.set('ui_ux_flow', flowKey)
    formData.set('ui_ux_section', sectionKey)
    if (action === 'update_phase') {
      formData.set('phase_status', 'DELETED')
    }

    setFlowDeleteBusyKey(`${action}:${keyValue}`)
    try {
      const response = await fetch('./', {
        method: 'POST',
        body: formData,
        headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' },
      })
      const contentType = response.headers.get('content-type') || ''
      const rawText = await response.text()
      if (!contentType.includes('application/json')) {
        window.alert(`Action returned HTML instead of JSON. HTTP ${response.status}. Please refresh and try again.`)
        return
      }
      const result = JSON.parse(rawText)
      if (maybeHandleAiBackgroundJobResult(result)) {
        return
      }
      if (!(result.ok || result.success)) {
        window.alert(result.message || 'Delete failed.')
        return
      }
      reloadPagePreservingScroll()
    } catch (error) {
      window.alert(error instanceof Error ? error.message : 'Delete failed.')
    } finally {
      setFlowDeleteBusyKey('')
    }
  }

  function requestFlowSoftDelete(confirm: NonNullable<typeof flowDeleteConfirm>) {
    if (confirm.keyValue === '') return
    setFlowDeleteConfirm(confirm)
  }

