  function databaseAiSuggestedTableName(note: Record<string, any> | null): string {
    const tableSuggestions = Array.isArray(note?.crudAiPayload?.table_suggestions) ? note?.crudAiPayload?.table_suggestions : []
    const firstSuggestion = tableSuggestions[0]
    const suggestedTableName = phaseField(firstSuggestion, 'table_name').trim()

    return suggestedTableName || phaseField(note?.crudAiPayload, 'recommended_table').trim()
  }

