  async function enableNoteFormSymbol(
    note: Record<string, any>,
    operationSelection = defaultFormOperationSelection(note.formAiPayload),
    createNewForm = false,
    formDetails: Record<string, any> = {},
  ) {
    const noteKey = phaseField(note, 'noteKey')
    if (noteKey === '' || formEnableBusyNoteKey !== '') return

    const formData = new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', 'enable_note_form')
    formData.set('note_key', noteKey)
    formData.set('form_operations', JSON.stringify(formOperationPayload(operationSelection)))
    formData.set('new_form', createNewForm ? '1' : '0')
    if (createNewForm) {
      formData.set('form_name', String(formDetails.form_name || ''))
      formData.set('form_description', String(formDetails.form_description || ''))
      formData.set('form_type', String(formDetails.form_type || 'regular_view'))
      formData.set('database_table', String(formDetails.database_table || ''))
      formData.set('form_storage_targets', JSON.stringify(formDetails.form_storage_targets || {}))
    }

    setFormEnableBusyNoteKey(noteKey)
    try {
      const response = await fetch('./', {
        method: 'POST',
        body: formData,
        headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' },
      })
      const contentType = response.headers.get('content-type') || ''
      const rawText = await response.text()
      if (!contentType.includes('application/json')) {
        window.alert(`Action returned HTML instead of JSON. HTTP ${response.status}. Please refresh and try again.`)
        return
      }
      const result = JSON.parse(rawText)
      if (maybeHandleAiBackgroundJobResult(result)) {
        return
      }
      if (!(result.ok || result.success)) {
        window.alert(result.message || 'Form symbol update failed.')
        return
      }
      const selectedPayload = {
        ...(result.data?.form_ai_payload || note.formAiPayload || {}),
        ...formOperationPayload(operationSelection),
      }
      const nextOverride = {
        formEnabled: true,
        formStatus: 'ACTIVE',
        formAiPayload: selectedPayload,
        formAiChat: Array.isArray(result.data?.form_ai_chat) ? result.data.form_ai_chat : note.formAiChat || [],
        crudTargetTable: phaseField(result.data || {}, 'crud_target_table', phaseField(note, 'crudTargetTable', 'NONE')),
        crudFieldName: phaseField(result.data || {}, 'crud_field_name', phaseField(note, 'crudFieldName', 'NONE')),
      }
      const nextNote = { ...note, ...nextOverride }
      setFormBuilderOverrides((current) => ({ ...current, [noteKey]: nextOverride }))
      showFormBuilderModal(nextNote, phaseField(result.data, 'form_instance_id'))
    } catch (error) {
      window.alert(error instanceof Error ? error.message : 'Form symbol update failed.')
    } finally {
      setFormEnableBusyNoteKey('')
    }
  }

