                              <Button type="button" variant="outline" size="icon-sm" title="Copy complete scoped AI prompt" aria-label={`Copy complete ${noteCode} AI prompt`} onClick={() => void copyUiUxFlowAiText(`task-note-${noteKey}`, taskNoteBuilderPrompt(note))}><Copy /></Button>
