                              const retryActive = noteChatRetryBusyId === messageId || noteChatDeliveryQueue.some((item) => item.id === messageId && ['queued', 'sending', 'processing'].includes(item.status))
                              const deliveryLabel = deliveryStatus === 'saved' ? 'Saved' : deliveryStatus === 'queued' ? 'Queued' : deliveryStatus === 'sending' ? 'Sending' : deliveryStatus === 'processing' ? 'Processing' : deliveryStatus === 'sent' ? 'Submitted' : deliveryStatus === 'completed' ? 'Completed' : deliveryStatus === 'failed' ? 'Failed' : ''
