                                            {['sending', 'processing'].includes(deliveryStatus) ? <LoaderCircle className="size-2.5 animate-spin" /> : null}{deliveryLabel}{deliveryTarget ? ` · ${deliveryTarget === 'vscode' ? 'VS Code AI' : deliveryTarget === 'chat' ? 'Chat' : 'Local AI'}` : ''}
