function PhaseBuilderQuickJump({ label, links }: { label: string; links: Array<{ id: string; label: string }> }) {
  const jumpTo = (event: React.MouseEvent<HTMLAnchorElement>, id: string) => {
    event.preventDefault()
    const target = document.getElementById(id)
    if (!target) return
    window.history.replaceState(null, '', `${window.location.pathname}${window.location.search}#${id}`)
    target.scrollIntoView({ behavior: 'smooth', block: 'start' })
  }

  React.useEffect(() => {
    const hash = window.location.hash.slice(1)
    if (!hash || !links.some((link) => link.id === hash)) return
    const frame = window.requestAnimationFrame(() => document.getElementById(hash)?.scrollIntoView({ behavior: 'auto', block: 'start' }))
    return () => window.cancelAnimationFrame(frame)
  }, [])

  return <nav aria-label={`${label} quick jumps`} className="sticky -top-4 z-20 flex self-start flex-wrap items-center gap-2 rounded-lg bg-background/95 p-3 shadow-sm backdrop-blur supports-[backdrop-filter]:bg-background/85"><span className="mr-1 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">Quick jump</span>{links.map((link) => <a key={link.id} href={`#${link.id}`} onClick={(event) => jumpTo(event, link.id)} className={buttonClassName({ variant: 'outline', size: 'sm' })}>{link.label}</a>)}</nav>
}

function PhaseBuilderGreenHero({ id, eyebrow, title, description, badges }: { id: string; eyebrow: string; title: string; description: string; badges?: React.ReactNode }) {
  return <section id={id} className="scroll-mt-24 rounded-lg bg-gradient-to-br from-emerald-500/10 via-background to-sky-500/10 p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div className="min-w-0"><p className="text-xs font-semibold uppercase tracking-wider text-emerald-700 dark:text-emerald-300">{eyebrow}</p><h2 className="mt-1 break-words text-xl font-semibold">{title}</h2><p className="mt-2 max-w-4xl text-sm leading-6 text-muted-foreground">{description}</p></div>{badges ? <div className="flex flex-wrap items-center gap-2">{badges}</div> : null}</div></section>
}

