  const restartVsCodeBridge = async () => {
    const bridgeUrl = 'http://127.0.0.1:43127'
    const workspaceRoot = '/var/www/html/developer'
    setRestartDialogOpen(false)
    setBridgeRestart({ status: 'restarting', message: 'Restarting VS Code through the BuilderX bridge…' })
    try {
      const restartResponse = await fetch(`${bridgeUrl}/restart`, { method: 'POST', headers: { Accept: 'application/json' } })
      const restart = await restartResponse.json().catch(() => null)
      if (!restartResponse.ok || restart?.ok !== true) throw new Error(String(restart?.message || 'The BuilderX bridge restart was not accepted.'))

      setBridgeRestart({ status: 'restarting', message: 'Restart requested. Verifying bridge readiness…' })
      let lastHealth: any = null
      for (let attempt = 0; attempt < 15; attempt += 1) {
        try {
          const healthResponse = await fetch(`${bridgeUrl}/health?workspace_root=${encodeURIComponent(workspaceRoot)}`, { cache: 'no-store' })
          lastHealth = await healthResponse.json().catch(() => null)
          const readyToSend = healthResponse.ok
            && lastHealth?.ok === true
            && lastHealth?.workspace === workspaceRoot
            && lastHealth?.code_ready === true
            && lastHealth?.context_ready === true
            && lastHealth?.companion_extension_installed === true
            && lastHealth?.builderx_extension_active === true
            && lastHealth?.extension_workspace_ready === true
            && lastHealth?.codex_command_ready === true
            && lastHealth?.extension_probe_state === 'ready'
            && lastHealth?.active_thread_busy === false
          setBridgeHealth({ status: readyToSend ? 'ready' : 'not-ready', readyToSend, threadBusy: lastHealth?.active_thread_busy === true })
          if (readyToSend) {
            setBridgeRestart({ status: 'success', message: 'BuilderX bridge restarted and is ready.' })
            return
          }
        } catch {
          lastHealth = null
          setBridgeHealth({ status: 'error', readyToSend: false, threadBusy: null })
        }
        await new Promise((resolve) => window.setTimeout(resolve, 1000))
      }
      throw new Error(lastHealth?.active_thread_busy === true ? 'VS Code restarted, but the active Codex turn is still busy.' : 'VS Code restarted, but the BuilderX bridge did not become ready.')
    } catch (error) {
      setBridgeRestart({ status: 'error', message: error instanceof Error ? error.message : 'The BuilderX bridge restart failed.' })
    }
  }
