  const readBridgeEventStream = async (url: string, onEvent: (name: string, data: Record<string, any>) => boolean): Promise<void> => {
    const response = await fetch(url, { cache: 'no-store', headers: { Accept: 'text/event-stream' } })
    if (!response.ok || !response.body) throw new Error('The BuilderX bridge progress stream is unavailable.')
    const reader = response.body.getReader()
    const decoder = new TextDecoder()
    let buffer = ''
    let terminal = false
    const dispatch = (block: string) => {
      let name = 'message'
      const dataLines: string[] = []
      for (const line of block.split('\n')) {
        if (line.startsWith('event:')) name = line.slice(6).trim()
        if (line.startsWith('data:')) dataLines.push(line.slice(5).trim())
      }
      if (!dataLines.length) return
      let data: Record<string, any>
      try {
        data = JSON.parse(dataLines.join('\n'))
      } catch {
        throw new Error('The BuilderX bridge returned invalid progress data.')
      }
      terminal = onEvent(name, data)
    }
    while (!terminal) {
      const { done, value } = await reader.read()
      buffer += decoder.decode(value, { stream: !done }).replace(/\r\n/g, '\n')
      let separator = buffer.indexOf('\n\n')
      while (separator >= 0) {
        const block = buffer.slice(0, separator)
        buffer = buffer.slice(separator + 2)
        dispatch(block)
        if (terminal) break
        separator = buffer.indexOf('\n\n')
      }
      if (done) break
    }
    await reader.cancel().catch(() => {})
    if (!terminal) throw new Error('The BuilderX bridge progress stream ended before completion.')
  }
  const sendVsCodeBridgeTask = async (command: string, taskLabel: string, onProgress?: (state: { message: string; response: string; threadId: string }) => void, options: { resultFile?: boolean } = {}) => {
    const bridgeUrl = 'http://127.0.0.1:43127'
    const workspaceRoot = '/var/www/html/developer'
    if (command.trim() === '' || command.length > 2000) throw new Error('BuilderX bridge messages must be non-empty and 2,000 characters or fewer.')
    const report = (message: string, response = '', threadId = '') => onProgress?.({ message, response, threadId })
    report(`Checking the installed BuilderX VS Code bridge before ${taskLabel}…`)
    const healthResponse = await fetch(`${bridgeUrl}/health?workspace_root=${encodeURIComponent(workspaceRoot)}`, { cache: 'no-store' })
    const health = await healthResponse.json().catch(() => null)
    if (!healthResponse.ok || health?.ok !== true || health?.ready_to_send !== true || health?.active_thread_ready !== true || health?.active_thread_busy !== false) {
        throw new Error(health?.active_thread_busy === true
        ? 'The active Codex turn is busy. Try again after it finishes.'
        : String(health?.extension_probe_message || 'The installed BuilderX VS Code bridge has no available Codex send command.'))
    }

    const handoffResponse = await fetch(`${bridgeUrl}${options.resultFile ? '/handoff-result' : '/handoff'}`, { method: 'POST', headers: { Accept: 'application/json', 'Content-Type': 'application/json' }, body: JSON.stringify({ workspace_root: workspaceRoot, command }) })
    const handoff = await handoffResponse.json().catch(() => null)
    const requestId = String(handoff?.delivery?.request_id || '')
    if (!handoffResponse.ok || handoff?.ok !== true || requestId === '') throw new Error(String(handoff?.message || `The BuilderX VS Code bridge did not accept ${taskLabel}.`))

    const threadId = String(handoff?.delivery?.thread_id || health.active_thread_id || '')
    let responseText = ''
    let fileResult: Record<string, unknown> | null = null
    const resultFile = String(handoff?.delivery?.result_file || '')
    report(`${taskLabel} was delivered. Listening for Codex Chat progress…`, '', threadId)
    await readBridgeEventStream(`${bridgeUrl}/events?request_id=${encodeURIComponent(requestId)}`, (event, data) => {
      if (event === 'thread' && data.thread_id) {
        report('Connected to the active Codex Chat session.', responseText, String(data.thread_id))
      } else if (event === 'status') {
        report(String(data.message || 'Codex Chat is processing the request…'), responseText, threadId)
      } else if (event === 'assistant_message') {
        responseText = String(data.text || responseText)
        report('Codex Chat is responding…', responseText, threadId)
      } else if (event === 'failed') {
        throw new Error(String(data.message || 'The active Codex Chat request failed.'))
      } else if (event === 'completed') {
        responseText = String(data.result || responseText)
        fileResult = data.file_result && typeof data.file_result === 'object' && !Array.isArray(data.file_result) ? data.file_result as Record<string, unknown> : fileResult
        report(`${taskLabel} completed.`, responseText, threadId)
        return true
      }
      return false
    })
    if (options.resultFile && !fileResult) {
      const resultResponse = await fetch(`${bridgeUrl}/result?request_id=${encodeURIComponent(requestId)}`, { cache: 'no-store' })
      const result = await resultResponse.json().catch(() => null)
      if (!resultResponse.ok || result?.status !== 'completed' || !result?.file_result || typeof result.file_result !== 'object' || Array.isArray(result.file_result)) {
        throw new Error(String(result?.message || 'The BuilderX result file did not contain a completed JSON object.'))
      }
      fileResult = result.file_result as Record<string, unknown>
      responseText = JSON.stringify(fileResult)
    }
    return { response: responseText, threadId, fileResult, resultFile }
  }
  const validateRequirementsAnalysisResult = (value: unknown): Record<string, any> => {
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
      throw new Error('Requirements Analysis returned an invalid JSON object.')
    }
    const analysis = value as Record<string, any>
    const categoryKeys = ['functionalRequirements', ...requirementsAnalysisProductionCategories.map(({ key }) => key)]
    const requiredKeys = ['schemaVersion', 'contractType', 'source', 'projectAnalysis', 'actors', 'entities', 'portals', ...categoryKeys, 'missingDetailsOrRisks', 'assumptions', 'openQuestions', 'reviewChecklist', 'traceability', 'rag', 'orchestration']
    const missing = requiredKeys.filter((key) => !(key in analysis))
    if (missing.length > 0) throw new Error(`Requirements Analysis is missing required fields: ${missing.join(', ')}.`)
    if (analysis.schemaVersion !== 'builderx.requirements-analysis.v2' || analysis.contractType !== 'builderx.requirements-analysis') {
      throw new Error('Requirements Analysis returned an unsupported contract version.')
    }
    if (!analysis.source || typeof analysis.source !== 'object' || Array.isArray(analysis.source)) throw new Error('Requirements Analysis returned an invalid source object.')
    if (!analysis.projectAnalysis || typeof analysis.projectAnalysis !== 'object' || Array.isArray(analysis.projectAnalysis)) throw new Error('Requirements Analysis returned an invalid projectAnalysis object.')
    if (!analysis.orchestration || typeof analysis.orchestration !== 'object' || Array.isArray(analysis.orchestration)) throw new Error('Requirements Analysis returned an invalid orchestration object.')
    if (!Array.isArray(analysis.orchestration.selectedSpecialists) || !Array.isArray(analysis.orchestration.additionalSpecialistProposals)) throw new Error('Requirements Analysis orchestration must include specialist selections and proposals as arrays.')
    for (const key of categoryKeys) {
      if (!Array.isArray(analysis[key])) throw new Error(`Requirements Analysis category must be an array: ${key}.`)
    }
    return analysis
  }
