      setRoadmapWorkflow((current) => ({ ...current, status: 'error', message: 'Execution Roadmap stage stopped before an unsafe or unverified write.', error: message, events: settleOneFlowEvents(appendOneFlowEvent(current.events, `Workflow stopped: ${message}`, 'error'), 'error') }))
