  const completedPhaseCount = hasRoadmap ? roadmapPhasesForView.filter((phase) => roadmapPhaseStatus(phase, roadmapPhases.indexOf(phase)) === 'Completed').length : phases.filter((phase) => phaseField(phase, 'phase_status') === 'Completed').length

